import React, { useState, useEffect, useRef } from "react";

// ═══════════════════════════════════════════════════════════
// WIREREADY PRO — 500-QUESTION CA ELECTRICIAN EXAM PREP APP
// All questions original field knowledge, no NEC text reproduced
// ═══════════════════════════════════════════════════════════

const ALL_QUESTIONS = [
// MODULE 1: DEFINITIONS & GENERAL (30)
{id:1,mod:1,cat:"Definitions",diff:"Easy",q:"What is the stated purpose of the National Electrical Code?",opts:["Practical safeguarding of persons and property from hazards arising from the use of electricity","Achieve the most efficient electrical installation possible","Provide a design specification for electrical systems","Establish minimum standards for utility service connections"],ans:0,ref:"NEC 90.2(A)",exp:"The NEC's purpose is the practical safeguarding of persons and property from hazards arising from the use of electricity. It is NOT a design specification or instruction manual for untrained persons. Compliance results in an installation essentially free from hazard, but not necessarily efficient or adequate for future expansion."},
{id:2,mod:1,cat:"Definitions",diff:"Easy",q:"What does the term 'ampacity' mean?",opts:["The maximum current in amperes a conductor can carry continuously without exceeding its temperature rating","The minimum voltage a conductor is rated to carry","The cross-sectional area of a conductor in circular mils","The resistance per 1,000 feet of conductor"],ans:0,ref:"NEC Article 100",exp:"Ampacity = maximum current in amperes a conductor can carry continuously under conditions of use without exceeding its temperature rating. This single definition drives all conductor sizing decisions in the NEC."},
{id:3,mod:1,cat:"Definitions",diff:"Easy",q:"What does 'Approved' mean when applied to electrical equipment?",opts:["Listed by a nationally recognized testing laboratory","Tested and labeled by the manufacturer","Acceptable to the authority having jurisdiction","Compliant with applicable UL standards"],ans:2,ref:"NEC Article 100",exp:"Approved = acceptable to the AHJ. The AHJ has final say on what is acceptable. Listed equipment is generally accepted, but 'approved' is the broader standard — the AHJ can approve non-listed equipment when warranted."},
{id:4,mod:1,cat:"Definitions",diff:"Easy",q:"Which chapters of the NEC apply generally to all electrical installations?",opts:["Chapters 1 through 7","Chapters 1 through 4 only","Chapters 1 through 9","Only Chapter 1"],ans:1,ref:"NEC 90.3",exp:"Chapters 1 through 4 apply generally to all electrical installations. Chapters 5, 6, and 7 supplement or modify Chapters 1–7 for special occupancies, equipment, or conditions. Chapter 8 (Communications) is NOT subject to Chapters 1–7 except where specifically referenced in Chapter 8."},
{id:5,mod:1,cat:"Definitions",diff:"Easy",q:"What conductors make up a branch circuit?",opts:["All conductors from the utility meter to the last outlet","Conductors between the service equipment and the first overcurrent device","Conductors between the final overcurrent device protecting the circuit and the outlet(s)","Conductors that supply two or more panelboards"],ans:2,ref:"NEC Article 100",exp:"Branch circuit = conductors between the FINAL overcurrent device protecting the circuit and the outlet(s). The 'final' OCPD is the key identifier. Feeders supply panelboards; branch circuits supply loads."},
{id:6,mod:1,cat:"Definitions",diff:"Easy",q:"A dwelling unit must have permanent provisions for which of the following?",opts:["Living, sleeping, cooking, and sanitation","Eating, sleeping, and at least one bathroom","Sleeping and cooking only","Living, sleeping, and cooking only"],ans:0,ref:"NEC Article 100",exp:"Dwelling unit = a single unit providing complete and independent living facilities, including permanent provisions for LIVING, SLEEPING, COOKING, AND SANITATION. All four required. A hotel room without permanent cooking facilities is NOT a dwelling unit — this distinction determines which NEC rules apply."},
{id:7,mod:1,cat:"Definitions",diff:"Medium",q:"In the NEC, the phrase 'shall be permitted' signals which type of rule?",opts:["A permissive rule — allowed but not required","Explanatory material","An exception overriding a mandatory rule","A mandatory requirement"],ans:0,ref:"NEC 90.5(B)",exp:"'Shall be permitted' = permissive rule — allowed but not required. 'Shall' or 'shall not' = mandatory. Informational notes = explanatory material, not enforceable. Mastering NEC language is critical to correctly interpreting the code on the exam and in the field."},
{id:8,mod:1,cat:"Definitions",diff:"Medium",q:"What is the key difference between 'accessible' as applied to equipment and 'readily accessible'?",opts:["They are interchangeable terms","Accessible equipment requires no tools; readily accessible allows use of tools","Accessible means reachable for operation or renewal; readily accessible means reachable quickly without tools (other than keys), climbing, or removing obstacles","Readily accessible requires a key; accessible does not"],ans:2,ref:"NEC Article 100",exp:"Accessible (equipment) = capable of being reached for operation, renewal, and inspection. Readily accessible = capable of being reached QUICKLY without tools (other than keys), climbing, removing obstacles, or portable ladders. A locked panel can be accessible but not readily accessible. Many NEC sections require one standard or the other — knowing which matters."},
{id:9,mod:1,cat:"Definitions",diff:"Medium",q:"What is the NEC definition of the Authority Having Jurisdiction (AHJ)?",opts:["The local utility company","The NFPA technical committee","The licensed contractor of record","An organization, office, or individual responsible for enforcing requirements of a code or standard, or approving equipment, materials, installations, or procedures"],ans:3,ref:"NEC Article 100",exp:"AHJ = organization, office, or individual responsible for enforcing requirements or approving equipment, materials, installations, or procedures. Typically the local electrical inspector, but can be a fire marshal, insurance inspector, or building official depending on jurisdiction. The AHJ has final interpretive authority on the job."},
{id:10,mod:1,cat:"Definitions",diff:"Medium",q:"A motor disconnect must be 'in sight from' the motor. What does this mean?",opts:["Within the same room as the motor","Visible from anywhere in the building","Visible AND not more than 50 feet distant","Within 10 feet with clear line of sight"],ans:2,ref:"NEC Article 100",exp:"'In Sight From' (Within Sight) = visible AND not more than 50 feet (15 m) distant. BOTH conditions must be met. A disconnect 75 feet away, even if clearly visible, does NOT satisfy this requirement. A common exam trap — memorize both the visibility AND the distance limit."},
{id:11,mod:1,cat:"Definitions",diff:"Medium",q:"What conductors make up a feeder?",opts:["Any conductor larger than 10 AWG","Conductors from the utility transformer to the service entrance","All circuit conductors between the service equipment (or separately derived system source) and the final branch-circuit overcurrent device","Any conductors connecting two panelboards"],ans:2,ref:"NEC Article 100",exp:"Feeder = all circuit conductors between service equipment (or separately derived system source, or other power supply source) and the FINAL branch-circuit OCPD. Feeders supply panelboards or subpanels. The distinction between feeder and branch circuit determines which sizing and protection rules apply."},
{id:12,mod:1,cat:"Definitions",diff:"Medium",q:"A transformer secondary has no direct metallic connection back to its primary circuit conductors except through grounding and bonding connections. How is this source classified?",opts:["A separately derived system","An ungrounded system","A feeder","A service"],ans:0,ref:"NEC Article 100",exp:"Separately derived system = electrical power supply output with no direct connections to circuit conductors of any other electrical source other than those established by grounding and bonding. A transformer secondary is the classic example. Requires its own system bonding jumper and grounding electrode system."},
{id:13,mod:1,cat:"Definitions",diff:"Medium",q:"A 90°C THHN conductor is terminated at a lug rated for 75°C. Which temperature column must be used to determine this conductor's ampacity at the termination?",opts:["90°C column from Table 310.16","60°C column from Table 310.16","75°C column from Table 310.16","The average of the 75°C and 90°C table values"],ans:2,ref:"NEC 110.14(C)",exp:"Termination rule (110.14(C)): use the LOWEST temperature rating of the connected termination, conductor, or device. A 90°C conductor at a 75°C lug = use 75°C column. The 90°C rating can still be used for derating calculations — but the final ampacity at this termination is capped by the 75°C lug. This is one of the most misapplied rules in the field."},
{id:14,mod:1,cat:"Definitions",diff:"Medium",q:"A 480V panelboard has live parts on one side and a grounded concrete wall on the other side of the working space (Condition 2). What is the minimum required depth of working space?",opts:["3 feet","3 feet 6 inches","4 feet","5 feet"],ans:1,ref:"NEC Table 110.26(A)(1)",exp:"Table 110.26(A)(1): 151–600V, Condition 2 (live parts one side, grounded parts other) = 1.0 m (3 ft 6 in). Condition 1 = 3 ft; Condition 3 = 4 ft. Concrete, brick, and tile walls count as grounded, placing most field situations in Condition 2. Know all three conditions and voltages cold."},
{id:15,mod:1,cat:"Definitions",diff:"Medium",q:"What is the minimum required width of working space in front of a 200A panelboard that is 20 inches wide?",opts:["20 inches — match equipment width","24 inches","30 inches","36 inches"],ans:2,ref:"NEC 110.26(A)(2)",exp:"Working space width = equipment width OR 30 inches (762 mm), whichever is GREATER. A 20-inch wide panel requires 30 inches of working space. The work space must also permit at least 90-degree opening of equipment doors or hinged panels."},
{id:16,mod:1,cat:"Definitions",diff:"Medium",q:"Which location does NOT require an arc flash hazard warning label on a panelboard?",opts:["Commercial office building","Industrial facility","Hospital","Single-family dwelling unit"],ans:3,ref:"NEC 110.16(A)",exp:"Arc flash hazard warning labels are required on switchboards, switchgear, panelboards, industrial control panels, meter sockets, and MCCs that are in 'other than dwelling units' and likely to require servicing while energized. Dwelling units are explicitly exempt from this requirement."},
{id:17,mod:1,cat:"Definitions",diff:"Medium",q:"Which best describes a multiwire branch circuit?",opts:["A branch circuit with two or more ungrounded conductors having voltage between them, plus a neutral with equal voltage to each ungrounded conductor, connected to the system neutral","Multiple circuits sharing the same conduit","A circuit that supplies more than one panelboard","Any circuit with more than 20A capacity"],ans:0,ref:"NEC Article 100",exp:"Multiwire branch circuit = two or more ungrounded conductors with voltage between them + a neutral with equal voltage between it and each ungrounded conductor, connected to the system neutral. Requires simultaneous disconnection of all ungrounded conductors — a requirement added specifically to prevent dangerous partial de-energization."},
{id:18,mod:1,cat:"Definitions",diff:"Medium",q:"A room contains a toilet and a bathtub but no sink. Is this a 'bathroom' under the NEC definition?",opts:["Yes — any room with a toilet qualifies","Yes — a toilet and tub together satisfy the definition","No — a bathroom requires a sink plus at least one other plumbing fixture","No — a bathroom requires a sink, toilet, AND tub or shower together"],ans:2,ref:"NEC Article 100",exp:"NEC definition: bathroom = area that includes a SINK plus one or more of: toilet, urinal, tub, shower, bidet, or similar plumbing fixtures. A room with only a toilet and tub but NO SINK is NOT a bathroom under the NEC. This distinction affects GFCI protection and circuit requirements — and it's a question many experienced electricians get wrong."},
{id:19,mod:1,cat:"Definitions",diff:"Medium",q:"What does 'identified' mean when applied to equipment in the NEC?",opts:["Listed by a recognized testing laboratory","Marked with a brand name by the manufacturer","Approved by the AHJ for the specific installation","Recognizable as suitable for the specific purpose, function, use, environment, and application described in the Code requirement"],ans:3,ref:"NEC Article 100",exp:"Identified = recognizable as suitable for the specific purpose, function, use, environment, and application where described in a Code requirement. May be evidenced by listing, labeling, instructions, or markings. Different from 'listed' — identified equipment is not required to be listed, but must be recognizably suitable for its stated use."},
{id:20,mod:1,cat:"Definitions",diff:"Medium",q:"Chapter 8 of the NEC covers communications systems. How does it relate to the requirements in Chapters 1 through 7?",opts:["Chapter 8 is fully subject to all requirements of Chapters 1 through 7","Chapter 8 is completely independent — Chapters 1–7 never apply","Chapter 8 is not subject to Chapters 1 through 7 except where requirements from those chapters are specifically referenced within Chapter 8","Chapter 8 supplements Chapter 7 for special conditions only"],ans:2,ref:"NEC 90.3",exp:"Chapter 8 (Communications) is NOT subject to Chapters 1 through 7 EXCEPT where those chapters are specifically referenced within Chapter 8. This makes Chapter 8 unique — it largely stands alone with selective references. However, definitions from Article 100 do apply to Chapter 8 articles."},
{id:21,mod:1,cat:"Definitions",diff:"Hard",q:"Informational notes appear after many code sections. What is their correct legal status?",opts:["Informational only — not enforceable as requirements of the Code","Enforceable in jurisdictions that adopt the NEC without amendment","Enforceable at the AHJ's discretion","Enforceable when directly referenced by a mandatory rule above them"],ans:0,ref:"NEC 90.5(C)",exp:"Informational notes are explanatory material — informational ONLY and NOT enforceable as requirements of the Code. This includes notes that reference other standards. Only 'shall' and 'shall not' language creates enforceable requirements. On the exam, a question citing an informational note as the basis for a requirement is testing whether you know the note itself cannot mandate anything."},
{id:22,mod:1,cat:"Definitions",diff:"Hard",q:"What is the key distinction between a grounded conductor and an equipment grounding conductor (EGC)?",opts:["They are the same conductor in most residential circuits","The grounded conductor carries normal return current; the EGC is a fault current path connecting non-current-carrying metal parts to the system grounded conductor or grounding electrode conductor","The EGC is grounded at the service; the neutral is grounded only at the panel","The grounded conductor connects to the grounding electrode; the EGC connects to the neutral bus"],ans:1,ref:"NEC Article 100",exp:"Grounded conductor (neutral): intentionally grounded system conductor that carries normal return current. EGC: conductive path connecting normally non-current-carrying metal parts to the grounded conductor or grounding electrode conductor — carries NO normal current, only fault current. The NEC explicitly states that although an EGC is grounded, it is NOT a 'grounded conductor.' Confusing these two in the field causes dangerous wiring errors."},
{id:23,mod:1,cat:"Definitions",diff:"Hard",q:"On a 4-wire delta system where the midpoint of one phase winding is grounded, where must the high-leg marking be applied?",opts:["Only at the service entrance panelboard","Only at the source transformer secondary terminals","At each point on the system where a connection is made if the grounded conductor is also present","Only where the high-leg voltage to ground exceeds 150 volts"],ans:2,ref:"NEC 110.15",exp:"High-leg marking (110.15): orange color or other effective means, applied at EACH POINT ON THE SYSTEM WHERE A CONNECTION IS MADE if the grounded conductor is also present. The B-phase high leg has approximately 208V to ground vs. 120V on the other two legs. Improperly identified, this is a serious shock hazard — the marking must appear throughout the entire system wherever both conductors are present."},
{id:24,mod:1,cat:"Definitions",diff:"Hard",q:"A panelboard is rated for circuits over 100A and has lugs rated for 75°C. A 4/0 AWG THHN conductor is connected. Which ampacity governs this termination?",opts:["The 90°C ampacity of 4/0 THHN","The 60°C ampacity of 4/0","The 75°C ampacity of 4/0","The average of the 75°C and 90°C table values"],ans:2,ref:"NEC 110.14(C)(1)(b)",exp:"For equipment rated over 100A (or conductors larger than 1 AWG): use the 75°C column unless equipment is listed and identified for higher. 4/0 THHN at 75°C = 230A per Table 310.16. The 90°C rating is not wasted — it can still be used for ampacity correction and adjustment factor calculations — but the final ampacity AT THIS TERMINATION is limited to the 75°C value."},
{id:25,mod:1,cat:"Definitions",diff:"Hard",q:"What must be true of the space directly above an indoor panelboard?",opts:["The space must be enclosed and accessible only to qualified persons","The space equal to the equipment's width and depth, from the floor to 6 ft above the equipment or the structural ceiling (whichever is lower), must contain no piping, ducts, or foreign systems","Working space must extend 3 feet in all directions from the equipment","No other electrical equipment may be installed within 10 feet"],ans:1,ref:"NEC 110.26(E)(1)(a)",exp:"Dedicated electrical space (110.26(E)(1)(a)): the space equal to equipment width and depth, extending from the floor to 1.8 m (6 ft) above the equipment or to the structural ceiling (whichever is lower), must be dedicated to the electrical installation — no piping, ducts, leak protection, or foreign systems. Exception: suspended ceilings with removable panels are permitted within this zone."},
{id:26,mod:1,cat:"Definitions",diff:"Hard",q:"Service equipment in a commercial building must be field-marked with the available fault current. What additional piece of information must also appear on that marking?",opts:["The date the fault-current calculation was performed","The utility company's published short-circuit capacity","The equipment's short-circuit current rating","The interrupting rating of all overcurrent devices in the equipment"],ans:0,ref:"NEC 110.24(A)",exp:"110.24(A) requires field marking of service equipment (other than dwelling units) with: (1) the available fault current AND (2) the DATE the fault-current calculation was performed. The calculation must be documented and available to those who design, install, inspect, or maintain the system. If the system is later modified in a way that affects fault current, the marking must be updated."},
{id:27,mod:1,cat:"Definitions",diff:"Hard",q:"Which statement most completely and accurately describes the meaning of 'listed' as defined in the NEC?",opts:["Equipment included in a list published by an organization acceptable to the AHJ that maintains periodic inspection of production and states that the equipment meets applicable standards","Equipment approved by the local AHJ for a specific installation","Equipment tested by any independent third-party laboratory","Equipment bearing a UL, ETL, or CSA certification mark"],ans:0,ref:"NEC Article 100",exp:"Listed = included in a list published by an organization: (1) acceptable to the AHJ, (2) concerned with product evaluation, (3) that maintains periodic inspection of production, and (4) whose listing states the equipment meets applicable standards. UL, ETL, and CSA are common examples, but the AHJ determines which organizations are acceptable. 'Approved' and 'listed' are separate definitions — equipment can be approved without being listed."},
{id:28,mod:1,cat:"Definitions",diff:"Hard",q:"A lockable disconnecting means is not currently locked. What must be true of the locking provisions?",opts:["The provisions may be removed and stored when not in use","The provisions must remain in place regardless of whether a lock is installed","Provisions are only required while the disconnect is actively locked open","Provisions are only required on disconnects rated 200 amperes or more"],ans:1,ref:"NEC 110.25",exp:"110.25: the provisions for locking a disconnect in the open position must remain in place WITH OR WITHOUT the lock installed. This prevents the common field situation where locking hardware is removed and unavailable for LOTO procedures when needed. Exception: cord-and-plug locking provisions are not required to remain in place without the lock."},
{id:29,mod:1,cat:"Definitions",diff:"Hard",q:"Modifications to a commercial building's electrical system change the available fault current at the service. What is required as a result?",opts:["No update is required unless fault current increases by more than 10%","The available fault current must be verified or recalculated and the existing field marking updated to reflect the new level","Only the serving utility can update or revise the fault current marking","A new short-circuit study is required only when overcurrent device ratings are changed"],ans:1,ref:"NEC 110.24(B)",exp:"110.24(B): when modifications affect available fault current at the service, it must be VERIFIED OR RECALCULATED and the field marking ADJUSTED to reflect the new level. Any change that could affect fault current — adding a generator, changing transformer size, adding parallel conductors — triggers this requirement. Accurate fault current data is critical for ensuring equipment ratings remain adequate."},
{id:30,mod:1,cat:"Definitions",diff:"Hard",q:"Conductors other than copper, aluminum, or copper-clad aluminum are being used in an installation. What does the NEC require?",opts:["The installation is prohibited — only those three materials are permitted","The conductor size must be changed accordingly to maintain equivalent current-carrying capacity","The AHJ must approve any alternative conductor material prior to installation","The conductor must be listed for the specific application and voltage"],ans:1,ref:"NEC 110.5",exp:"110.5: conductors used to carry current shall be copper, aluminum, or copper-clad aluminum unless otherwise provided in the Code. If conductor material is not specified, the sizes given apply to copper. If other materials are used, the size shall be changed accordingly to provide equivalent ampacity. This applies to specialty applications such as silver contacts in specific equipment types."},
// MODULE 2: WIRING & OVERCURRENT (45)
{id:31,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"How many 20-ampere small appliance branch circuits must be provided in a dwelling unit?",opts:["At least two 20-ampere circuits","Three circuits minimum","No minimum — based on calculation only","One circuit is sufficient"],ans:0,ref:"NEC 210.11(C)(1)",exp:"At least two 20-ampere small appliance branch circuits must supply the receptacle outlets serving the kitchen, dining room, breakfast room, pantry, and similar areas. These circuits shall have no other outlets and cannot supply lighting fixtures or permanently connected appliances."},
{id:32,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"Where must at least one receptacle outlet be placed in relation to each lavatory basin in a dwelling unit bathroom?",opts:["Within 36 inches of the outside edge of each basin","Anywhere within the bathroom","Adjacent to the mirror","Within 3 feet of the toilet"],ans:0,ref:"NEC 210.52(D)",exp:"At least one receptacle outlet must be installed within 1 m (36 in.) of the outside edge of each lavatory basin. Measurement is from the basin edge, not along the wall. A double vanity requires a receptacle within 36 in. of each basin."},
{id:33,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"What is the maximum overcurrent protective device rating permitted for a circuit with 14 AWG copper branch circuit conductors?",opts:["20 amperes","25 amperes","30 amperes","15 amperes"],ans:3,ref:"NEC 240.4(D)(3)",exp:"14 AWG copper conductors must not be protected by an overcurrent device rated more than 15 amperes. This is one of the absolute small-conductor limits in Article 240 — the next-size-up rule of 240.4(B) does not apply to these conductors."},
{id:34,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"What is the maximum overcurrent protective device rating permitted for a circuit with 12 AWG copper conductors?",opts:["25 amperes","30 amperes","15 amperes","20 amperes"],ans:3,ref:"NEC 240.4(D)(5)",exp:"12 AWG copper conductors must not be protected by an overcurrent device rated more than 20 amperes. This is an absolute limit in 240.4(D) — the next-size-up rule does not apply. Using a 30A device on 12 AWG is a dangerous and common code violation."},
{id:35,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"What is the maximum overcurrent device rating permitted for a branch circuit with 10 AWG copper conductors?",opts:["25 amperes","20 amperes","40 amperes","30 amperes"],ans:3,ref:"NEC 240.4(D)(6)",exp:"10 AWG copper conductors must not be protected by an overcurrent device rated more than 30 amperes. The 240.4(D) small-conductor limits apply regardless of the next-size-up rule. 10 AWG on a 30A circuit is a standard configuration for electric dryers."},
{id:36,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"A load operates at maximum current for 3 hours or more. How is this load classified?",opts:["A surge load","An intermittent load","A continuous load","An overload"],ans:2,ref:"NEC Article 100",exp:"Continuous load is defined as a load where the maximum current is expected to continue for 3 hours or more. This triggers the 125% rule: both the overcurrent device rating and the conductor ampacity must be at least 125% of the continuous load. HVAC systems and most commercial lighting are continuous loads."},
{id:37,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"What is the minimum circuit rating required for a dedicated laundry branch circuit in a dwelling unit?",opts:["15 amperes","30 amperes","25 amperes","20 amperes"],ans:3,ref:"NEC 210.11(C)(2)",exp:"At least one 20-ampere branch circuit must supply the laundry receptacle outlets. This circuit shall have no other outlets. The 20-ampere rating ensures adequate capacity for washing machine motors and other laundry equipment."},
{id:38,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"No point along the floor line of a dwelling unit wall space may be more than how far from a receptacle outlet?",opts:["12 feet","4 feet","8 feet","6 feet"],ans:3,ref:"NEC 210.52(A)(1)",exp:"No point along the floor line in any wall space shall be more than 1.8 m (6 ft), measured horizontally, from a receptacle outlet. This means receptacles are no more than 12 feet apart. Any wall space 2 feet or wider must be included in the spacing calculation."},
{id:39,mod:2,cat:"Wiring & Overcurrent",diff:"Easy",q:"Which two exterior locations of a single-family dwelling each require at least one receptacle outlet accessible at grade level?",opts:["Driveway and backyard","Any two walls","Side of house and garage","Front and rear of the dwelling"],ans:3,ref:"NEC 210.52(E)(1)",exp:"At least one receptacle outlet must be installed at the front and at the rear of a single-family dwelling, accessible at grade level. Both must be GFCI-protected. Balconies, decks, and porches with a usable area of 20 sq ft or greater also require at least one receptacle outlet."},
{id:40,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"The 2023 NEC added a new dedicated branch circuit requirement for which dwelling area?",opts:["Attached garages and detached garages with electric power","Outdoor areas","Master bedroom","Unfinished attic"],ans:0,ref:"NEC 210.11(C)(4)",exp:"New in the 2023 NEC: at least one 120-volt, 20-ampere branch circuit must supply receptacle outlets in attached garages and in detached garages with electric power. This circuit shall have no other outlets, except that Exception No. 1 permits outdoor receptacles to also be on this circuit."},
{id:41,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"In a dwelling unit, which rooms require arc-fault circuit-interrupter (AFCI) protection on 120-volt, 15- and 20-ampere branch circuits?",opts:["All rooms including kitchens, family rooms, dining rooms, living rooms, parlors, libraries, hallways, closets, laundry areas, and similar rooms","Kitchens and living rooms only","Bedrooms only","Bedrooms and bathrooms only"],ans:0,ref:"NEC 210.12(B)",exp:"AFCI protection is required for 120-volt, single-phase 10-, 15-, and 20-ampere branch circuits supplying outlets in dwelling unit rooms including kitchens, family rooms, dining rooms, living rooms, parlors, libraries, sunrooms, recreation rooms, closets, hallways, laundry areas, and similar rooms or areas. AFCI devices protect against arcing faults that can ignite building materials."},
{id:42,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"No point along a kitchen countertop wall line in a dwelling unit may be more than how far from a receptacle outlet?",opts:["36 inches","18 inches","12 inches","24 inches"],ans:3,ref:"NEC 210.52(C)(1)",exp:"No point along the kitchen countertop wall line shall be more than 600 mm (24 in.) from a receptacle outlet measured horizontally. This spacing applies to countertops 12 in. or wider. Countertop receptacles must be installed on the small appliance branch circuits. Islands and peninsulas have their own receptacle requirements."},
{id:43,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"How is the distance measured when determining if a receptacle is within 6 feet of a sink for GFCI protection purposes?",opts:["Straight line across the room","Along the wall surface only","The shortest path a power supply cord would follow without passing through a floor, wall, ceiling, or fixed barrier","Diagonal across the countertop"],ans:2,ref:"NEC 210.8",exp:"Distance is measured as the shortest path a power supply cord connected to the receptacle would follow without piercing a floor, wall, ceiling, or fixed barrier. This cord-path method reflects how a cord would actually be routed to the appliance rather than a theoretical straight-line distance."},
{id:44,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"All services supplying dwelling units now require which 2023 NEC-added device at or immediately adjacent to the service equipment?",opts:["Arc-fault circuit interrupter","Ground-fault circuit interrupter","Type 1 or Type 2 surge-protective device (SPD)","Emergency disconnect rated for available fault current"],ans:2,ref:"NEC 230.67",exp:"New in the 2023 NEC: a listed Type 1 or Type 2 surge-protective device (SPD) must be provided for all services supplying dwelling units, dormitory units, hotel and motel guest rooms, and nursing home patient sleeping rooms. The SPD must be integral to the service equipment or located immediately adjacent to it."},
{id:45,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"A multiwire branch circuit originates at a panelboard. What does the NEC require at the point of origin?",opts:["A means to simultaneously disconnect all ungrounded conductors — a 2-pole breaker or handle-tied pair","An AFCI breaker only","A GFCI breaker for each ungrounded conductor","Individual single-pole breakers are acceptable"],ans:0,ref:"NEC 210.4(B)",exp:"Multiwire branch circuits must have a means to simultaneously disconnect all ungrounded conductors at the point where the branch circuit originates. A 2-pole circuit breaker or handle-tied pair of single-pole breakers satisfies this requirement, preventing the dangerous condition of a shared neutral remaining energized while one leg is opened."},
{id:46,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"What type of receptacles must be installed for all 15- and 20-ampere, 125-volt non-locking receptacles throughout a dwelling unit?",opts:["Weather-resistant receptacles","GFCI receptacles","Ground-fault and AFCI combination receptacles","Tamper-resistant receptacles"],ans:3,ref:"NEC 406.12(A)",exp:"All non-locking 15- and 20-ampere, 125- and 250-volt receptacles throughout dwelling units must be tamper-resistant. The tamper-resistant design uses spring-loaded shutters that open only when both contact slots are pressed simultaneously — preventing children from inserting foreign objects into a single slot."},
{id:47,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"When a conductor's ampacity does not match a standard overcurrent device size, what rule permits use of the next higher standard rating?",opts:["The demand factor rule","The next-size-up rule","The 10% tolerance rule","The continuous load exception"],ans:1,ref:"NEC 240.4(B)",exp:"Where the conductor ampacity does not correspond to a standard overcurrent device rating listed in 240.6, the next higher standard overcurrent device rating shall be permitted — provided: (1) it is not a motor circuit or other circuit with prescribed OCPD sizing, and (2) the next higher standard rating does not exceed 800 amperes."},
{id:48,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"What are the standard overcurrent device ratings listed in Article 240?",opts:["Any round number up to 6,000 amperes","10, 20, 30, 40, 60, 100, 200 amperes only","15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100, 110, 125, 150, 175, 200 amperes and more","Only ratings listed by the device manufacturer"],ans:2,ref:"NEC 240.6(A)",exp:"Standard ampere ratings for fuses and fixed-trip circuit breakers listed in 240.6(A): 15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100, 110, 125, 150, 175, 200, 225, 250, 300, 350, 400, 450, 500, 600, 700, 800 amperes (and more). These are essential for applying the next-size-up rule."},
{id:49,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"For a dwelling unit optional load calculation, what minimum load is assigned to each 20-ampere small appliance branch circuit?",opts:["2,000 VA","1,000 VA","750 VA","1,500 VA"],ans:3,ref:"NEC 220.82(B)(2)",exp:"Each 2-wire, 20-ampere small appliance branch circuit and each laundry branch circuit is assigned 1,500 volt-amperes in the optional load calculation. With the minimum of two small appliance circuits plus one laundry circuit, that is 3 × 1,500 = 4,500 VA assigned before the 40% demand factor applies above 10 kVA."},
{id:50,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"For the general lighting load in a dwelling unit per Table 220.12, what volt-ampere load per square foot is used?",opts:["5 VA/sq ft","1 VA/sq ft","2 VA/sq ft","3 VA/sq ft"],ans:3,ref:"NEC Table 220.12",exp:"Dwelling units use a general lighting load of 3 VA per square foot (33 VA/m²) under Table 220.12. This value applies to both the standard calculation and the optional method per 220.82(B)(1). Floor area is measured from outside dimensions, excluding open porches, garages, and unfinished spaces not adaptable for future use."},
{id:51,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"An overcurrent protective device must be rated not less than what percentage of the continuous load on a branch circuit?",opts:["80 percent","100 percent","110 percent","125 percent"],ans:3,ref:"NEC 210.20(A)",exp:"Where a branch circuit supplies continuous loads, the overcurrent device rating shall not be less than the noncontinuous load plus 125 percent of the continuous load. For an all-continuous load: OCPD rating ≥ load × 1.25. Exception: where the assembly is listed for 100% duty, the OCPD may equal the load."},
{id:52,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"A circuit breaker used to switch fluorescent luminaires must carry what special marking?",opts:["AFCI","HID","GFCI","SWD (Switching Duty)"],ans:3,ref:"NEC 240.83(D)",exp:"Circuit breakers used as switches for fluorescent lighting equipment must be marked SWD (Switching Duty). Standard breakers are not designed for the repetitive on/off cycling under load required by lighting control. The SWD marking confirms the breaker mechanism can withstand switching duty without premature failure."},
{id:53,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"In the optional load calculation for a dwelling unit, how are general loads calculated?",opts:["80% of first 10 kVA, 40% of remainder","50% of all loads","40% of all loads","100% of first 10 kVA plus 40% of the remainder"],ans:3,ref:"NEC 220.82(B)",exp:"Optional method: 100% of the first 10 kVA of all loads, plus 40% of the remainder. Example: 25 kVA total — 10,000 VA at 100% + 15,000 VA at 40% = 10,000 + 6,000 = 16,000 VA demand. This often yields a lower demand than the standard Part III method, allowing smaller service conductors."},
{id:54,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"What general lighting load per square foot is used for an office building load calculation?",opts:["2 VA/sq ft","5 VA/sq ft","1 VA/sq ft","3.5 VA/sq ft"],ans:3,ref:"NEC Table 220.12",exp:"Office buildings use a general lighting load of 3.5 VA per square foot from Table 220.12. Key comparisons: dwellings = 3 VA/sq ft, banks = 3.5 VA/sq ft, schools = 3 VA/sq ft, warehouses = 0.25 VA/sq ft. These minimum load values are used regardless of actual installed wattage."},
{id:55,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"A dwelling unit hallway requires a receptacle outlet only if the hallway is at least how long?",opts:["6 feet","20 feet","15 feet","10 feet"],ans:3,ref:"NEC 210.52(H)",exp:"Dwelling unit hallways of 3 m (10 ft) or more in length require at least one receptacle outlet. Hallways shorter than 10 feet have no receptacle requirement. The intent is to eliminate the need for extension cords in longer hallways for appliance use."},
{id:56,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"In a dwelling unit, how many of the 12 GFCI locations listed in 210.8(A) apply to ALL 125- through 250-volt receptacles on single-phase circuits at 150 volts or less to ground?",opts:["Only kitchens and bathrooms","Only 3 wet locations","All 12 listed locations","Depends on AHJ requirements"],ans:2,ref:"NEC 210.8(A)",exp:"All 12 locations listed in 210.8(A) require GFCI protection: (1) bathrooms, (2) garages and below-grade accessory buildings, (3) outdoors, (4) crawl spaces at/below grade, (5) basements, (6) kitchens, (7) food/beverage prep sink areas, (8) sinks within 6 ft, (9) boathouses, (10) bathtubs/showers within 6 ft, (11) laundry areas, (12) indoor damp/wet locations."},
{id:57,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"A single 20-ampere bathroom circuit supplies receptacles, a luminaire, and an exhaust fan — all within the same bathroom. Is this permitted?",opts:["No — lighting must be on a separate circuit","No — each outlet type requires an individual circuit","No — exhaust fans must be on the HVAC circuit","Yes — when a 20-ampere circuit supplies a single bathroom, other equipment within that same bathroom may also be supplied"],ans:3,ref:"NEC 210.11(C)(3) Exception",exp:"The exception to 210.11(C)(3) permits a 20-ampere circuit supplying a single bathroom to also supply other equipment within that same bathroom, including luminaires and exhaust fans. When the circuit serves more than one bathroom, it cannot supply other loads outside those bathrooms."},
{id:58,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"Multiple neutral conductors from different circuits are installed in the same panelboard. What does the NEC require?",opts:["Grounded conductors must be identified or grouped with their associated ungrounded conductors at least once in the enclosure using wire markers, cable ties, or similar means","Different conductor sizes serve as adequate identification","No identification — white insulation is sufficient","Each neutral must be labeled with its breaker number"],ans:0,ref:"NEC 200.4(B)",exp:"Where more than one neutral conductor from different circuits is in an enclosure, the grounded conductors must be identified or grouped to correspond with the ungrounded conductor(s) using wire markers, cable ties, or similar means — at least at one location within the enclosure. This prevents connecting the wrong neutral when servicing a panel."},
{id:59,mod:2,cat:"Wiring & Overcurrent",diff:"Medium",q:"A circuit breaker used as a switch for high-intensity discharge (HID) luminaires must carry which marking?",opts:["SWD only","Any standard inverse-time breaker","HID marking","Either SWD or HID depending on ballast type"],ans:2,ref:"NEC 240.83(D)",exp:"Circuit breakers used as switches for HID lighting must be marked HID. This is distinct from the SWD marking for fluorescent luminaires. HID ballasts create different switching transients than fluorescent ballasts — an SWD-only rating is not sufficient for HID circuits."},
{id:60,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"The 2023 NEC requires an emergency disconnecting means for one- and two-family dwellings. Where must it be located?",opts:["Inside the house adjacent to the main panel","In the meter socket only","In a readily accessible outdoor location, on or within sight of the dwelling unit","At least 10 feet from any openable window"],ans:2,ref:"NEC 230.85(A)(1)",exp:"New in the 2023 NEC: one- and two-family dwelling units must have an emergency disconnecting means installed in a readily accessible outdoor location on or within sight of the dwelling unit. This allows emergency responders to disconnect power without entering. Multiple disconnects must be grouped. The disconnect must have a short-circuit current rating at least equal to the available fault current."},
{id:61,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A surge-protective device (SPD) required for dwelling unit services must meet what minimum nominal discharge current rating and what type classification?",opts:["5 kA, Type 1 only","15 kA, Type 2 only","20 kA, any type","10 kA, Type 1 or Type 2"],ans:3,ref:"NEC 230.67(C) and (E)",exp:"The 2023 NEC requires the SPD to be a listed Type 1 or Type 2 device with a nominal discharge current rating (In) of not less than 10 kA. The SPD must be integral to the service equipment or immediately adjacent to it. These requirements also apply when service equipment is replaced."},
{id:62,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A conductor has an ampacity of 55 amperes. Using the next-size-up rule, what is the maximum permitted overcurrent device rating?",opts:["50 amperes","70 amperes","55 amperes","60 amperes"],ans:3,ref:"NEC 240.4(B)",exp:"55 amperes does not match a standard size (standard sizes jump from 50A to 60A). The next-size-up rule permits 60 amperes — the next higher standard size. Conditions: (1) not a motor or special circuit, (2) next standard size does not exceed 800A. The 50-to-60A jump is one of the most tested next-size-up scenarios on the CA journeyman exam."},
{id:63,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"What is the maximum overcurrent device size that can be used under the next-size-up rule regardless of conductor ampacity?",opts:["1,200 amperes","No maximum with AHJ approval","2,000 amperes","800 amperes"],ans:3,ref:"NEC 240.4(B)",exp:"The next-size-up rule is limited: the next higher standard overcurrent device size shall not exceed 800 amperes. For conductors with an ampacity greater than 800A, the OCPD must match or be smaller than the conductor ampacity. The 800A limit prevents disproportionate overcurrent devices on large feeder conductors."},
{id:64,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"AFCI protection is required, but wiring from the panel to the first outlet box is run in metal raceway with metal boxes throughout. What AFCI method is acceptable?",opts:["A listed outlet branch-circuit-type AFCI at the first outlet box, protecting the remainder of the circuit","Both an AFCI breaker and an outlet AFCI are required when metal raceway is used","No AFCI required when metallic wiring methods are used","Combination-type AFCI breaker at the panel only — no outlet device needed"],ans:0,ref:"NEC 210.12(A)(5)",exp:"Per 210.12(A)(5): when metal raceway, metal wireways, Type MC or Type AC cable meeting 250.118 with metal boxes and metal enclosures is installed from the overcurrent device to the first outlet, a listed outlet branch-circuit-type AFCI at the first outlet provides required protection for the rest of the circuit. The metallic wiring from panel to first outlet is considered inherently protected."},
{id:65,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"When using the outlet AFCI method per 210.12(A)(3) or (A)(4), what is the maximum permitted wiring length from the panel to the first outlet for 14 AWG conductors?",opts:["70 feet","25 feet","100 feet","50 feet"],ans:3,ref:"NEC 210.12(A)(3)(b) and (A)(4)(b)",exp:"When using these outlet branch-circuit AFCI methods, the maximum length of branch-circuit wiring from the overcurrent device to the first outlet shall not exceed 15.2 m (50 ft) for 14 AWG conductors, or 21.3 m (70 ft) for 12 AWG conductors. The first outlet box must also be marked to indicate it is the first outlet."},
{id:66,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A branch circuit supplies 8 amperes of noncontinuous load and 16 amperes of continuous load. What is the minimum permitted overcurrent device rating?",opts:["24 amperes","30 amperes","25 amperes","20 amperes"],ans:1,ref:"NEC 210.20(A)",exp:"Minimum OCPD = noncontinuous + 125% of continuous. 8A + (16A × 1.25) = 8 + 20 = 28A minimum. The next standard size at or above 28A is 30 amperes. The conductor must also be rated for at least 28A — from Table 310.16, 10 AWG copper at 75°C = 35A, which is sufficient."},
{id:67,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A 15-ampere, 120-volt branch circuit has a 14-ampere continuous load. Is this circuit properly protected with a 15-ampere breaker?",opts:["Yes — 14A is less than 15A so the 15A breaker is adequate","No — the OCPD must be rated not less than 125% of the continuous load: 14A × 1.25 = 17.5A, requiring a 20A device","Yes — a 10% safety factor is acceptable","No — continuous loads require a 30% safety margin"],ans:1,ref:"NEC 210.20(A)",exp:"Continuous load rule: OCPD ≥ 125% of continuous load. 14A × 1.25 = 17.5A minimum OCPD. A 15A breaker is insufficient. The next standard size at or above 17.5A is 20 amperes. A 20A breaker and 12 AWG conductors are required for this circuit."},
{id:68,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A factory-installed receptacle inside a bathroom exhaust fan assembly is not readily accessible. Does it require GFCI protection?",opts:["No — factory-installed, not readily accessible receptacles inside bathroom exhaust fan assemblies are exempt unless required by the installation instructions or listing","Only if the fan is cord-connected","Yes — all bathroom receptacles require GFCI protection","Only if within 6 feet of the shower"],ans:0,ref:"NEC 210.8(A) Exception No. 4",exp:"Exception No. 4 to 210.8(A): factory-installed receptacles that are not readily accessible and are mounted internally to bathroom exhaust fan assemblies do not require GFCI protection unless required by the installation instructions or listing. These receptacles serve the fan motor assembly, not occupant plug-in use."},
{id:69,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A weight-supporting ceiling receptacle (WSCR) is installed to support a ceiling fan that includes an integral general-purpose convenience receptacle. Does the convenience receptacle require GFCI protection?",opts:["Only if the fan is installed in a bathroom","No — the WSCR exception covers all parts of the ceiling fan","No — ceiling receptacles are always exempt","Yes — GFCI protection shall be provided for the integral general-purpose convenience receptacle"],ans:3,ref:"NEC 210.8(A) Exception No. 3",exp:"Exception No. 3 permits listed WSCRs combined with weight-supporting attachment fittings (WSAFs) for ceiling luminaires/fans to omit GFCI for the weight-supporting receptacle. However, if a general-purpose convenience receptacle is integral to the ceiling luminaire or fan, GFCI protection shall be provided for that convenience receptacle."},
{id:70,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A dwelling unit optional load calculation has 32 kVA of general loads. What is the calculated demand for service sizing?",opts:["12,800 VA (40% of 32 kVA)","17,200 VA","32,000 VA","18,800 VA"],ans:3,ref:"NEC 220.82(B)",exp:"Optional method: 100% of first 10 kVA = 10,000 VA; remainder = 32,000 – 10,000 = 22,000 VA × 40% = 8,800 VA; total demand = 10,000 + 8,800 = 18,800 VA. This is significantly less than the full 32,000 VA, illustrating why the optional method often allows smaller service conductors."},
{id:71,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A 12 AWG copper THWN conductor has a 75°C table ampacity of 20A. A temperature correction factor of 0.82 and a conduit fill adjustment factor of 0.70 both apply. What is the derated ampacity?",opts:["20 amperes — Table 240.4(D) limits are absolute","16.4 amperes","14 amperes","11.5 amperes"],ans:3,ref:"NEC 310.15",exp:"Derated ampacity = table ampacity × temperature correction × fill adjustment. 20A × 0.82 × 0.70 = 11.5A. The 12 AWG absolute maximum OCPD of 20A per 240.4(D) still applies to the overcurrent device size, but the conductor may only carry 11.5A continuously under these conditions. Exceeding this level causes overheating even though the 20A breaker won't trip."},
{id:72,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A circuit breaker's ampere rating represents its continuous current capacity. What does a separate interrupting capacity (AIC) rating indicate?",opts:["The maximum continuous load the breaker can carry","The maximum fault current the breaker can safely interrupt without damage","The overcurrent trip threshold as a percentage","The maximum conductor size the breaker accepts"],ans:1,ref:"NEC 110.9",exp:"The interrupting capacity (AIC) rating is the maximum fault current the device can safely interrupt without damage to the device or danger to the installation. Residential breakers are commonly rated 10,000 AIC. If available fault current exceeds the breaker's AIC rating, the breaker can fail catastrophically during a fault event."},
{id:73,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"A listed Class A GFCI for personnel protection trips when sensing what level of ground fault current?",opts:["15 to 20 mA","Greater than 30 mA","10 to 15 mA","4 to 6 mA"],ans:3,ref:"NEC 210.8",exp:"A listed Class A GFCI trips when the ground fault current is in the range of 4 to 6 milliamperes. This threshold is set below the let-go current (approximately 10–20 mA at which muscle contractions prevent releasing an energized conductor) and far below the 50–100 mA range associated with ventricular fibrillation. All personnel protection GFCIs referenced in the NEC are Class A."},
{id:74,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"When a listed outlet branch-circuit AFCI is used at the first outlet under 210.12(A)(3) or (A)(4), what additional marking is required at the first outlet box?",opts:["No marking required for residential installations","The AFCI device manufacturer's model number","A panel directory note is sufficient","The first outlet box must be marked to indicate it is the first outlet of the branch circuit"],ans:3,ref:"NEC 210.12(A)(3)(c) and (A)(4)(c)",exp:"When using the outlet branch-circuit AFCI methods per 210.12(A)(3) or (A)(4), the first outlet box shall be marked to indicate it is the first outlet of the branch circuit. This marking informs future electricians that the AFCI protection device is located in that first outlet box rather than at the panel, preventing them from assuming the panel breaker provides AFCI protection."},
{id:75,mod:2,cat:"Wiring & Overcurrent",diff:"Hard",q:"Article 240 prohibits reconditioning of certain overcurrent protective devices. Which of the following may NOT be reconditioned?",opts:["Low-voltage power circuit breakers","Electromechanical protective relays","Molded-case circuit breakers","Current transformers"],ans:2,ref:"NEC 240.2(A)",exp:"New in the 2023 NEC, 240.2(A) lists equipment that shall not be reconditioned: equipment providing GFPE, GFCIs, low-voltage fuseholders and non-renewable fuses, molded-case circuit breakers, and low-voltage power circuit breaker electronic trip units. By contrast, 240.2(B) permits reconditioning of low-voltage power circuit breakers and electromechanical protective relays and current transformers."},
// MODULE 3: SERVICES & FEEDERS (35)
{id:76,mod:3,cat:"Services & Feeders",diff:"Easy",q:"What is the minimum ampere rating of a service for a single-family dwelling?",opts:["60 amperes","80 amperes","150 amperes","100 amperes"],ans:3,ref:"NEC 230.79(C)",exp:"The service disconnecting means for a single-family dwelling shall have a rating of not less than 100 amperes, 3-wire. In practice, 200-ampere services are standard for new construction to accommodate modern loads including EV charging, but 100 amperes is the NEC minimum."},
{id:77,mod:3,cat:"Services & Feeders",diff:"Easy",q:"What is the minimum size copper conductor permitted for an overhead service entrance?",opts:["12 AWG","10 AWG","6 AWG","8 AWG"],ans:3,ref:"NEC 230.23(B)",exp:"Service-entrance conductors shall not be smaller than 8 AWG copper or 6 AWG aluminum or copper-clad aluminum. Exception: conductors supplying only limited loads of a single branch circuit (small polyphase power, controlled water heaters) may be as small as 12 AWG hard-drawn copper."},
{id:78,mod:3,cat:"Services & Feeders",diff:"Easy",q:"Where must the service disconnecting means be located?",opts:["At a readily accessible location, outside or inside the building nearest the point of entrance of service conductors","Inside a locked meter room","At least 6 feet from any water source","In the center of the building"],ans:0,ref:"NEC 230.70(A)(1)",exp:"The service disconnecting means shall be installed at a readily accessible location either outside of a building or structure or inside nearest the point of entrance of the service conductors. 'Nearest the point of entrance' limits the length of unprotected service conductors inside the building."},
{id:79,mod:3,cat:"Services & Feeders",diff:"Easy",q:"What is the minimum vertical clearance required for overhead service conductors above a roof surface?",opts:["10 feet","6 feet","12 feet","8 feet 6 inches"],ans:3,ref:"NEC 230.24(A)",exp:"Overhead service conductors shall have a vertical clearance of not less than 2.6 m (8 ft 6 in.) above the roof surface. This clearance must be maintained for a distance of not less than 900 mm (3 ft) in all directions from the edge of the roof. Exceptions apply for steeply pitched roofs and short overhang passes."},
{id:80,mod:3,cat:"Services & Feeders",diff:"Easy",q:"The grounded conductor (neutral) of a premises wiring system must be identified by what color?",opts:["Black","Green or bare","Blue","White or gray"],ans:3,ref:"NEC 200.6(A)",exp:"The insulation of grounded conductors 6 AWG or smaller shall be identified by a continuous white or gray outer finish, three white or gray stripes, or by other methods listed in 200.6(A). Green identifies equipment grounding conductors. The neutral/white conductor must never be used as an ungrounded (hot) conductor except as specifically permitted."},
{id:81,mod:3,cat:"Services & Feeders",diff:"Easy",q:"What does the term 'service point' mean?",opts:["The location of the main service panel","The grounding electrode connection","The point of connection between the serving utility and the premises wiring","The metering location"],ans:2,ref:"NEC Article 100",exp:"Service point is the point of connection between the facilities of the serving utility and the premises wiring. Everything from the service point toward the load is subject to the NEC. Everything on the utility side is governed by the National Electrical Safety Code (NESC) and utility rules."},
{id:82,mod:3,cat:"Services & Feeders",diff:"Easy",q:"A service disconnect must be rated for what minimum interrupting duty?",opts:["Rated for the calculated load only","A short-circuit current rating that is not less than the available fault current at the service point","Any UL-listed disconnect is acceptable","10,000 AIC minimum for all services"],ans:1,ref:"NEC 230.82 & 110.9",exp:"Service equipment must have a short-circuit current rating not less than the maximum available fault current at the point of application. Available fault current is determined by the serving utility and used to specify properly rated switchgear, circuit breakers, and fuses."},
{id:83,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Overhead service conductors over a residential property and driveway must maintain what minimum clearance above the ground?",opts:["18 feet","8 feet","15 feet","12 feet"],ans:3,ref:"NEC 230.24(B)",exp:"Overhead service conductors must maintain at least 3.7 m (12 ft) of clearance above residential property and driveways subject to pedestrian or passenger vehicle traffic only. The 5.5 m (18 ft) clearance applies to public streets, alleys, roads, and driveways subject to truck traffic."},
{id:84,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Overhead service conductors must maintain a minimum clearance of how far from openable windows, doors, porches, balconies, and similar locations?",opts:["18 inches","6 feet","1 foot","3 feet"],ans:3,ref:"NEC 230.9(A)",exp:"Service entrance conductors (including drip loops) shall maintain at least 900 mm (3 ft) clearance from openable windows, doors, porches, balconies, ladders, stairs, fire escapes, and similar locations. Conductors passing above the top of a window are exempt from the 3 ft clearance from that window."},
{id:85,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Where the roof slope is 4 in 12 or greater and the voltage between conductors does not exceed 300 volts, what reduction in roof clearance is permitted?",opts:["No reduction is permitted","Clearance may be reduced to 18 inches","Clearance may be reduced to 3 feet","Clearance may be reduced to 5 feet"],ans:2,ref:"NEC 230.24(A) Exception No. 2",exp:"Exception No. 2 to 230.24(A): where the voltage between conductors does not exceed 300 volts and the roof has a slope of 100 mm in 300 mm (4 in. in 12 in.) or greater, a reduction in clearance to 900 mm (3 ft) is permitted. This exception applies to steeply pitched residential roofs that service conductors must pass over."},
{id:86,mod:3,cat:"Services & Feeders",diff:"Medium",q:"What is the maximum number of disconnecting means permitted for a single service?",opts:["Two","No limit with AHJ approval","One only","Six"],ans:3,ref:"NEC 230.71(A)",exp:"The service disconnecting means for each service permitted by 230.2 shall consist of not more than six switches or sets of circuit breakers, or a combination of not more than six switches and sets of circuit breakers, mounted in a single enclosure, in a group of separate enclosures, or in or on a switchboard or switchgear. A single main disconnect is required where all six are not in the same enclosure."},
{id:87,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Service entrance conductors must be kept as short as practical. What is permitted on the supply side of the service disconnect?",opts:["Any wiring method","Nothing — supply side is utility property","Only metering equipment, service entrance conductors, grounding electrode conductors, and specific listed items","Only fused disconnect switches"],ans:2,ref:"NEC 230.82",exp:"230.82 lists what is permitted to be connected to the supply side of the service disconnecting means: cable limiters/connectors, meters/metering equipment, main bonding jumpers, ground-fault protection, taps for legally required standby systems, surge-protective devices, and connection points for load management equipment. Nothing else shall be connected supply-side."},
{id:88,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Service entrance conductors installed between the service head and the service disconnect must be installed in which types of wiring methods?",opts:["Specific methods listed in Article 230, including SE cable, RMC, IMC, EMT, PVC, and others","Only in Schedule 80 PVC conduit","Rigid metal conduit only","Any approved wiring method"],ans:0,ref:"NEC 230.43",exp:"Service entrance conductors shall be installed using wiring methods listed in 230.43, which includes: open wiring on insulators, RMC, IMC, EMT, service entrance cable (SE), wireways, PVC conduit, FMC/LFMC not over 6 ft, LFNC, HDPE, NUCC, RTRC, Type MC cable, and Type TC-ER cable. This list is more restrictive than general building wiring."},
{id:89,mod:3,cat:"Services & Feeders",diff:"Medium",q:"A grounded conductor (neutral) in a service or feeder must be identified or grouped with its associated ungrounded conductors when more than one neutral from different circuits occupies the same enclosure. Where must this identification be made?",opts:["No identification required if white insulation is used","At every junction box and device","Only at the panel","At least at one location within the enclosure"],ans:3,ref:"NEC 200.4(B)",exp:"Where more than one neutral conductor from different circuits is in the same enclosure, grounded circuit conductors shall be identified or grouped with the ungrounded conductors using wire markers, cable ties, or similar means at least at one location within the enclosure. This prevents cross-connection of neutrals during service or modification work."},
{id:90,mod:3,cat:"Services & Feeders",diff:"Medium",q:"When a transformer supplying a building service is located outside the building, what additional grounding connection is required?",opts:["At least one additional grounding connection shall be made from the grounded service conductor to a grounding electrode at the transformer or elsewhere outside the building","The utility is responsible for all outdoor grounding","Only required for transformers larger than 167 kVA","None — the service grounding at the panel is sufficient"],ans:0,ref:"NEC 250.24(A)(2)",exp:"If the transformer supplying the service is located outside the building, at least one additional grounding connection shall be made from the grounded service conductor to a grounding electrode — either at the transformer or elsewhere outside the building. This establishes a path for lightning-induced transients before they enter the building."},
{id:91,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Service conductors supplying buildings or structures other than dwellings require what rating of service disconnect when a single disconnect is used?",opts:["Rated for the calculated load only","Shall have a rating not less than the calculated load","Equal to or greater than the available fault current","Sufficient ampacity for the load but not less than 60 amperes"],ans:1,ref:"NEC 230.79(A)",exp:"The service disconnecting means shall have a rating not less than the calculated load in accordance with Parts III, IV, or V of Article 220. For single-family dwellings, the minimum is 100A. The disconnect must be rated for both the continuous and non-continuous load requirements."},
{id:92,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Outside branch circuits and feeders run between buildings on the same premises are covered under which article?",opts:["Article 230","Article 210","Article 215","Article 225"],ans:3,ref:"NEC 225.1",exp:"Article 225 covers requirements for outside branch circuits and feeders run on or between buildings, structures, or poles on the same premises. Article 230 covers services — the conductors from the utility to the first disconnect. Article 225 governs building-to-building wiring that is not a service."},
{id:93,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Conductors of an outside branch circuit or feeder running within 3 meters (10 feet) of a building must meet what insulation requirement?",opts:["No special insulation required","Bare conductors are permitted","Must be enclosed in conduit only","Conductors must be insulated for the nominal voltage"],ans:3,ref:"NEC 225.4",exp:"Where outside conductors are within 3.0 m (10 ft) of any building or structure, open individual (aerial) overhead conductors shall be insulated for the nominal voltage. Conductors in cables or raceways in wet locations shall comply with 310.10(C). This prevents shock hazard from accidental contact near buildings."},
{id:94,mod:3,cat:"Services & Feeders",diff:"Medium",q:"A new single-family dwelling receives a service. The 2023 NEC requires an emergency disconnecting means. What type of disconnect can satisfy this requirement?",opts:["Any externally mounted shutoff regardless of listing","Only the main service panel breaker","Only a separate meter disconnect","A service disconnect, a listed meter disconnect, or another listed disconnect switch or circuit breaker marked suitable for use as service equipment"],ans:3,ref:"NEC 230.85(B)",exp:"Per 230.85(B), each emergency disconnect shall be one of: (1) a service disconnect, (2) a meter disconnect integral to meter mounting equipment not marked for service equipment use only, or (3) another listed disconnect switch or circuit breaker marked suitable for use as service equipment (but not solely for service use) installed on the supply side of each service disconnect."},
{id:95,mod:3,cat:"Services & Feeders",diff:"Medium",q:"Where must service entrance cables be sealed where they enter a service equipment enclosure?",opts:["No sealing required for cable assemblies","At the point the cable sheath enters the enclosure, with an approved fitting","Only if buried underground","Only for aluminum conductors"],ans:1,ref:"NEC 230.54(G)",exp:"Service-entrance cables shall be held securely in place, and the insulated conductors shall be arranged to drain moisture away from the service equipment. The cable sheath shall be continuous from the weatherhead or termination to the service equipment. Fittings shall be used to secure and protect the cable at the point of entry."},
{id:96,mod:3,cat:"Services & Feeders",diff:"Hard",q:"Using the optional dwelling unit load calculation for a 1,800 sq ft home with an all-electric kitchen, the general loads total 18 kVA. What is the calculated demand?",opts:["18,000 VA","7,200 VA","14,200 VA","13,200 VA"],ans:2,ref:"NEC 220.82(B)",exp:"Optional method: 100% of first 10 kVA = 10,000 VA; remainder = 18,000 – 10,000 = 8,000 VA × 40% = 3,200 VA; total demand = 10,000 + 3,200 = 13,200 VA. This demonstrates how the optional method reduces calculated service demand compared to calculating each load individually at its full value."},
{id:97,mod:3,cat:"Services & Feeders",diff:"Hard",q:"Service drop conductors passing over a public street or alley subject to truck traffic require a minimum clearance of how many feet above the road surface?",opts:["12 feet","15 feet","25 feet","18 feet"],ans:3,ref:"NEC 230.24(B)(4)",exp:"Overhead service conductors over public streets, alleys, roads, and driveways subject to truck traffic shall have a minimum clearance of 5.5 m (18 ft) above the road or driveway surface. This is greater than the 12 ft required over residential driveways (passenger vehicles only) to account for the height of commercial vehicles."},
{id:98,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A 400A, 120/240V, single-phase service uses two parallel sets of conductors. What must be true about each parallel conductor set?",opts:["Each set can be different sizes as long as total ampacity is met","Each set must carry exactly 200A continuously","Each parallel conductor set must have the same conductor size, insulation type, and approximate length, and be installed in separate raceways","One set can be copper and the other aluminum if ampacities are matched"],ans:2,ref:"NEC 310.10(G)",exp:"Conductors connected in parallel must: (1) be the same length, (2) consist of the same conductor material, (3) be the same circular mil area, (4) have the same insulation type, and (5) be terminated in the same manner. Each parallel conduit must contain all phase conductors and, where used, the neutral. These requirements ensure equal current sharing between parallel sets."},
{id:99,mod:3,cat:"Services & Feeders",diff:"Hard",q:"When service conductors pass over a rooftop and the overhead pass is limited to not more than 1.8 m (6 ft) of conductors passing 1.2 m (4 ft) horizontally over the roof overhang, and they terminate at a through-the-roof raceway, what reduced clearance is permitted?",opts:["18 inches","8 feet 6 inches","3 feet","6 feet"],ans:0,ref:"NEC 230.24(A) Exception No. 3",exp:"Exception No. 3 to 230.24(A): where the voltage between conductors does not exceed 300V, a reduction in clearance above only the overhanging portion of the roof to not less than 450 mm (18 in.) is permitted if (1) not more than 1.8 m (6 ft) of overhead service conductors, 1.2 m (4 ft) horizontally, pass above the roof overhang, and (2) they are terminated at a through-the-roof raceway or approved support."},
{id:100,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A two-family dwelling requires what minimum service size under the NEC?",opts:["100 amperes for the building, 60 amperes per unit","200 amperes minimum","100 amperes per dwelling unit","No NEC minimum — sized by load calculation only"],ans:3,ref:"NEC 230.79(C)",exp:"The NEC minimum service for a one-family dwelling is 100A. For multi-family dwellings, the service is sized by load calculation. Each dwelling unit would individually require 100A minimum per 230.79(C), but the total service is calculated per Article 220 demand methods. Practically, a two-family dwelling rarely exceeds a single 200A service sized by calculation."},
{id:101,mod:3,cat:"Services & Feeders",diff:"Hard",q:"What is the maximum length permitted for service entrance conductors inside a building before reaching the service disconnect?",opts:["As short as practicable — no defined maximum","30 feet","10 feet","No limit — conductors may run throughout the building"],ans:0,ref:"NEC 230.70(A)(1)",exp:"The NEC does not specify a maximum length for interior service conductors in feet, but requires the service disconnect to be installed 'nearest the point of entrance' and that conductors be 'kept as short as practicable.' Many AHJs interpret 'nearest the point of entrance' to limit interior service conductors to approximately 10–15 feet. Always verify with the local AHJ."},
{id:102,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A service must have all services supplying a dwelling unit equipped with a surge-protective device. What happens to this requirement when the service equipment is replaced?",opts:["The SPD requirement only applies to new construction","Existing SPDs may remain","A new SPD is required only if the existing one is damaged","The SPD requirement applies — when service equipment is replaced, all requirements of 230.67 apply"],ans:3,ref:"NEC 230.67(D)",exp:"230.67(D) explicitly states: 'Where service equipment is replaced, all of the requirements of this section shall apply.' Replacing a service entrance panel requires installation of a new listed Type 1 or Type 2 surge-protective device with a minimum 10 kA nominal discharge current rating."},
{id:103,mod:3,cat:"Services & Feeders",diff:"Hard",q:"What is the minimum burial depth for rigid metal conduit (RMC) used as an underground service lateral?",opts:["18 inches","24 inches","12 inches","6 inches"],ans:3,ref:"NEC Table 300.5",exp:"RMC and IMC may be buried with a minimum cover of only 150 mm (6 in.) because their heavy steel construction provides equivalent protection at shallower depth. PVC conduit requires 450 mm (18 in.) cover for residential, and direct burial cables require 600 mm (24 in.) cover. The reduced depth for RMC is one practical advantage that justifies its higher material cost."},
{id:104,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A demand load calculation results in a service ampacity requirement of 175 amperes. What minimum standard conductor size in copper at 75°C and standard overcurrent device would be selected?",opts:["3/0 AWG copper (200A), 200A OCPD","2/0 AWG copper (175A) — exact match available","1/0 AWG copper (150A) with 175A OCPD","4/0 AWG copper (230A), 200A OCPD"],ans:0,ref:"NEC Table 310.16 & 240.6(A)",exp:"From Table 310.16 at 75°C: 3/0 AWG copper = 200A ampacity. No 175A standard OCPD size exists (standard sizes jump from 150A to 175A to 200A). 175A is actually a standard size per 240.6(A) — so 2/0 AWG (175A at 75°C) would match exactly. However, in practice the service would typically be sized up to a 200A service with 3/0 AWG."},
{id:105,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A feeder to a detached garage on the same premises must include an equipment grounding conductor (EGC) in most cases. Under which specific conditions may the EGC be omitted?",opts:["When the feeder is run in metallic conduit","EGC is never required for detached garages","When the feeder is in PVC conduit","When no existing EGC is in the feeder, there are no grounding-type receptacles in the structure, and no metallic path exists back to the supplying building"],ans:3,ref:"NEC 250.32(B) Exception",exp:"250.32(B) normally requires an EGC in feeders to separate buildings. The exception allows omitting the EGC only for existing installations where: (1) no EGC was in the original feeder, (2) no grounding-type receptacles or equipment requiring EGC grounding are installed in the separate building, and (3) no metallic paths exist between buildings. New installations always require an EGC."},
{id:106,mod:3,cat:"Services & Feeders",diff:"Hard",q:"Under what conditions is the grounding electrode conductor (GEC) for a ground rod electrode capped at 6 AWG copper regardless of service size?",opts:["Never — GEC must match service conductor size","Only for services under 100A","Only when the rod is copper-clad","When only rod, pipe, and plate electrodes (or concrete-encased electrodes) are the grounding electrodes, the GEC need not be larger than 6 AWG copper"],ans:3,ref:"NEC 250.66(A)",exp:"Table 250.66 footnote and 250.66(A): where the only grounding electrodes are rod, pipe, or plate type — or concrete-encased electrodes — the GEC connecting to these electrodes need not be larger than 6 AWG copper or 4 AWG aluminum. The rod's limited current-handling ability means a larger GEC provides no benefit. This applies regardless of service size — even a 1,200A service uses a 6 AWG GEC to its ground rods."},
{id:107,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A service has multiple sets of parallel service entrance conductors in separate raceways. What is required in each parallel raceway?",opts:["One complete phase set per raceway — phases may be split between raceways","One conductor per raceway to prevent heating","All phases and the neutral in separate parallel raceways with a separate EGC or bond in each raceway","Each raceway must contain all ungrounded conductors, the neutral, and the EGC/bond"],ans:3,ref:"NEC 310.10(G)(1)",exp:"Each parallel raceway must contain an equal portion of all ungrounded conductors, the neutral (if any), and the equipment grounding conductor or bonding conductor. Running all phases in one raceway prevents the inductive effects of unbalanced magnetic fields that cause heating of metal conduits. Each raceway must form a complete balanced conductor set."},
{id:108,mod:3,cat:"Services & Feeders",diff:"Hard",q:"Demand factors from Table 220.54 for electric clothes dryers: what percentage applies when calculating 5 dryers?",opts:["100 percent","70 percent","90 percent","80 percent"],ans:3,ref:"NEC Table 220.54",exp:"Table 220.54 demand factors for electric clothes dryers: 1–4 dryers = 100%; 5 dryers = 80%; 6–7 dryers = 70%; 8–11 dryers = 65%; and so on. The minimum load per dryer is 5,000 VA or the nameplate rating, whichever is larger. Demand factors account for the statistical improbability that all dryers in a multi-unit building operate simultaneously at full load."},
{id:109,mod:3,cat:"Services & Feeders",diff:"Hard",q:"Service conductors may not be supported by vegetation such as trees. What does this prohibition cover?",opts:["Only trees in the public right-of-way","Only trees if they could fall on the conductors","Trees used as support for both overhead service conductors and service equipment","Only applies to commercial properties"],ans:2,ref:"NEC 230.10",exp:"230.10 states: 'Vegetation such as trees shall not be used for support of overhead service conductors or service equipment.' This prohibition covers both conductors and equipment — a service drop cannot be attached to a tree for support, and a meter socket cannot be mounted on a tree trunk. Trees grow and shift, creating unpredictable tension and mechanical failure."},
{id:110,mod:3,cat:"Services & Feeders",diff:"Hard",q:"A service lateral (underground service conductors) may be installed using which methods?",opts:["SE cable only — laterals must use service entrance cable","Direct burial cables or conductors in conduit — subject to applicable burial depth requirements","Only Type USE cable for underground service laterals","Any wiring method listed for use underground"],ans:2,ref:"NEC 230.30 & 230.32",exp:"Underground service-lateral conductors shall be insulated, and the grounded conductor shall be identified. They may be run as direct burial cables or conductors enclosed in a raceway. Burial depth requirements from Table 300.5 apply. Many utilities have their own specific requirements for underground service laterals — always coordinate with the serving utility."},
// MODULE 4: GROUNDING & BONDING (40)
{id:111,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"What is the primary purpose of grounding an electrical system, as stated in Article 250?",opts:["Provide a path for normal operating current","Limit voltage imposed by lightning, line surges, or contact with higher-voltage lines, and stabilize voltage to earth during normal operation","Reduce electricity costs by providing a return path","Protect equipment from voltage spikes only"],ans:1,ref:"NEC 250.4(A)(1)",exp:"Article 250 states that electrical systems that are grounded shall be connected to earth in a manner that will limit the voltage imposed by lightning, line surges, or unintentional contact with higher-voltage lines, and that will stabilize the voltage to earth during normal operation. Grounding is not a path for normal operating current — that is the neutral conductor's role."},
{id:112,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"What is the purpose of bonding electrical equipment?",opts:["Connect normally non-current-carrying conductive materials together and to the supply source to establish an effective ground-fault current path","Reduce resistance to earth for lightning protection","Ensure the neutral conductor is properly sized","Prevent voltage imbalance between phases"],ans:0,ref:"NEC 250.4(A)(3)",exp:"Bonding connects normally non-current-carrying conductive materials — conduit, boxes, equipment enclosures — together and to the electrical supply source in a manner that establishes an effective ground-fault current path. This low-impedance path allows sufficient fault current to flow to operate the overcurrent device and clear the fault quickly."},
{id:113,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"Equipment grounding conductors (EGCs) of 6 AWG or smaller must be identified. What identification is required?",opts:["White or gray insulation","Red insulation for EGC conductors","Green insulation, green with yellow stripe, or bare","Blue insulation or any color with green tape"],ans:2,ref:"NEC 250.119",exp:"Equipment grounding conductors shall be bare, covered, or insulated. Covered or insulated EGCs shall have a continuous outer finish that is either green or green with one or more yellow stripes. EGCs larger than 6 AWG may be identified at terminations only. Never use green insulated wire as an ungrounded (hot) conductor."},
{id:114,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"Can the earth serve as the effective ground-fault current path required by Article 250?",opts:["Yes — current through the earth returns to the source and operates overcurrent devices","Yes — earth provides a low-resistance return path","No — the earth is too resistive to carry enough fault current to operate overcurrent devices in a timely manner","Only for outdoor equipment directly in contact with soil"],ans:2,ref:"NEC 250.4(A)(5)",exp:"250.4(A)(5) explicitly states: 'The earth shall not be considered as an effective ground-fault current path.' Earth resistance is too high and variable to allow sufficient fault current to operate standard overcurrent devices quickly. A proper ground-fault current path must be a low-impedance metallic conductor — an EGC or bonding conductor back to the source."},
{id:115,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"What is the main bonding jumper?",opts:["The conductor connecting the grounding electrode to the earth","The conductor connecting the grounded conductor (neutral) to the equipment grounding conductor at the service disconnecting means","The largest conductor in the service","Any conductor used for grounding purposes at the service"],ans:1,ref:"NEC Article 100 & 250.24(C)",exp:"Main bonding jumper = the connection at the service disconnecting means between the grounded conductor (neutral) and the equipment grounding conductor (and service disconnect enclosure). There is only one main bonding jumper at the service — it must not be replicated at subpanels. This single connection is what bonds the neutral to the equipment grounding system."},
{id:116,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"At a subpanel (load-side panelboard), how must the neutral bus be installed?",opts:["Isolated from the equipment grounding conductor — not bonded to ground","Connected only to the green screw on the panel enclosure","Bonded to the equipment ground bus, same as the main panel","Connected to the grounding electrode system"],ans:0,ref:"NEC 408.40",exp:"At any panelboard that is not service equipment, the neutral (grounded conductor) bus shall be isolated from the equipment grounding conductor. The neutral and EGC buses are only bonded together at the service. Bonding neutral to EGC in a subpanel creates objectionable current on the EGC and metal parts of the system."},
{id:117,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"What are the two requirements that define an effective ground-fault current path?",opts:["Low impedance and rated for fault current; capable of operating the overcurrent device","High resistance and low reactance","At least 6 AWG copper and copper material only","Continuous metal path and proper labeling"],ans:0,ref:"NEC 250.4(A)(5)",exp:"An effective ground-fault current path must: (1) be low-impedance to allow sufficient fault current to flow, and (2) be capable of safely carrying the maximum ground-fault current likely to be imposed on it. This path facilitates operation of the overcurrent device or ground detector to clear the fault. Both characteristics are required."},
{id:118,mod:4,cat:"Grounding & Bonding",diff:"Easy",q:"A concrete-encased grounding electrode (Ufer ground) must consist of at least how many feet of rebar or bare copper conductor encased in concrete?",opts:["10 feet","50 feet","30 feet","20 feet"],ans:3,ref:"NEC 250.52(A)(3)",exp:"A concrete-encased electrode shall consist of at least 6.0 m (20 ft) of either: (1) one or more bare or zinc-galvanized rebar at least 13 mm (1/2 in.) in diameter, or (2) bare copper conductor not smaller than 4 AWG. The rebar or conductor must be encased by at least 50 mm (2 in.) of concrete in direct contact with earth."},
{id:119,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"What are ALL available grounding electrodes at a building required to do under the 2023 NEC?",opts:["Only the best electrode need be connected to the grounding electrode system","Each electrode may be used independently","All grounding electrodes at a building or structure must be bonded together into a single grounding electrode system","Only two electrodes need be bonded together"],ans:2,ref:"NEC 250.50",exp:"250.50 requires that ALL grounding electrodes described in 250.52 that are present at a building or structure shall be bonded together to form the grounding electrode system. If any of the listed electrodes are present (water pipe, building steel, concrete-encased electrode, ground ring, rods), they must all be bonded together — not used as separate independent grounding points."},
{id:120,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A new building has a concrete foundation. Which grounding electrode takes precedence as the preferred electrode for this installation?",opts:["Ground rod — it is always required","Any electrode — all are equivalent","Metal underground water pipe — it must be first if present","Concrete-encased electrode — where available in footings in direct contact with earth"],ans:3,ref:"NEC 250.52(A)(3) & 250.50",exp:"The concrete-encased electrode (Ufer ground) is strongly preferred when available because it provides a very low-impedance path to earth due to the large surface area of the foundation in direct contact with earth. New construction should always include a concrete-encased electrode in the foundation. All other available electrodes must still be bonded to form the complete grounding electrode system."},
{id:121,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A ground rod must be at least how long and at least how large in diameter?",opts:["6 feet long, 3/8 inch diameter","10 feet long, 3/4 inch diameter","5 feet long, 1/2 inch diameter","8 feet long, 5/8 inch diameter"],ans:3,ref:"NEC 250.52(A)(5)",exp:"Rod-type grounding electrodes shall be at least 2.44 m (8 ft) in length. Rod-type electrodes of stainless steel, copper, or zinc-coated steel shall be at least 15.87 mm (5/8 in.) in diameter, unless listed. The 8 ft minimum length ensures adequate contact with moist earth below the frost line."},
{id:122,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A ground ring used as a grounding electrode must meet what minimum requirements?",opts:["At least 10 feet of 6 AWG bare copper, at least 18 inches deep","At least 20 feet of 2 AWG bare copper, in direct contact with earth","At least 50 feet of 4 AWG bare copper, at any depth","At least 30 feet of 4 AWG bare copper, at least 12 inches deep"],ans:1,ref:"NEC 250.52(A)(4)",exp:"A ground ring encircling the building or structure, in direct contact with the earth, shall consist of at least 6.0 m (20 ft) of bare copper conductor not smaller than 2 AWG. The ring must encircle the building and be in direct contact with earth — not simply buried near the building."},
{id:123,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A single ground rod is installed and its resistance to earth exceeds 25 ohms. What is required?",opts:["A second rod must be installed not less than 1.8 m (6 ft) from the first","The rod must be driven deeper or a supplemental electrode added at the AHJ's discretion","It is permitted as a single electrode — 25 ohm resistance is acceptable","The rod must be replaced with a concrete-encased electrode"],ans:0,ref:"NEC 250.53(A)(2)",exp:"A single rod electrode with a resistance to earth exceeding 25 ohms shall be augmented by one additional electrode. The additional electrode shall be installed not less than 1.8 m (6 ft) from the first electrode. No resistance measurement or test is required if two rods are installed — the two-rod installation satisfies the requirement regardless of actual resistance."},
{id:124,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"Where must the grounding electrode conductor (GEC) connect the grounding electrode system to the service?",opts:["At the main breaker terminal only","At the neutral bus — must not connect to the equipment ground","At the main bonding jumper, the grounded service conductor, or the neutral bus at the service disconnecting means","At any convenient point in the service equipment"],ans:2,ref:"NEC 250.24(A)",exp:"The grounding electrode conductor shall be connected to the grounded service conductor, the service-disconnect enclosure, or the equipment grounding conductor, at any accessible point from the load end of the overhead service conductors, service drop, underground service conductors, or service lateral to the service disconnect terminal. The connection point is flexible but must be on the supply side of the service disconnect."},
{id:125,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A separate structure with its own disconnecting means is supplied by a feeder. The structure has its own grounding electrode. How must the structure's wiring system be grounded?",opts:["No grounding required for structures on the same property","Using only the feeder's EGC — no local ground connection needed","Connect the grounded conductor (neutral) to the local grounding electrode system","Connect the EGC to the local grounding electrode system; do not bond the grounded conductor to the local electrode (unless the EGC was not included in the feeder)"],ans:3,ref:"NEC 250.32(B)",exp:"250.32(B): for a feeder to a separate structure, the EGC shall be connected to the grounding electrode at the separate building. The grounded conductor (neutral) shall not be reconnected to ground on the load side of the service disconnecting means — doing so creates parallel neutral current paths. The local grounding electrode must still be installed and bonded to the EGC."},
{id:126,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"What is 'objectionable current' in the context of Article 250 grounding?",opts:["Current above 30 milliamperes flowing in any conductor","Normal load current exceeding conductor ampacity","Current flowing on grounding conductors or metal enclosures under normal operating conditions — caused by improper multiple ground connections","Short-circuit fault current in equipment enclosures"],ans:2,ref:"NEC 250.6",exp:"Objectionable current is current that flows on grounding conductors, metal enclosures, or conductive structural members during normal system operation — caused by improper multiple ground connections that create parallel neutral current paths. 250.6 requires the grounding system to be arranged to prevent objectionable current. Ground fault current and required bonding connections do NOT constitute objectionable current."},
{id:127,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"A transformer secondary (separately derived system) requires which grounding element that directly bonds the grounded conductor to the equipment enclosure?",opts:["Grounding electrode conductor","Main bonding jumper","Supply-side bonding jumper","Equipment grounding conductor"],ans:1,ref:"NEC 250.30(A)(1)",exp:"A separately derived system requires a system bonding jumper — equivalent to the main bonding jumper at a service. This unspliced conductor connects the grounded conductor of the separately derived system to the equipment grounding conductor and the source enclosure. It must be installed at the source of the separately derived system or at the first disconnecting means."},
{id:128,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"What is the minimum size copper grounding electrode conductor for a service with 2/0 AWG copper ungrounded service-entrance conductors?",opts:["8 AWG","6 AWG","4 AWG","2 AWG"],ans:2,ref:"NEC Table 250.66",exp:"Table 250.66: for service conductors of 2/0 AWG copper, the minimum GEC size is 4 AWG copper. The GEC is sized from this table based on the largest service-entrance conductor or equivalent area of conductors in parallel. Larger service = larger GEC, up to a maximum of 3/0 AWG copper for very large services (except rods and plates cap at 6 AWG per 250.66(A))."},
{id:129,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"What types of metallic piping systems require bonding to the grounding electrode system?",opts:["Only water pipes bonded to the service","Only pipes carrying flammable gases","All metallic piping systems including water pipes, gas piping, and other interior metallic water piping likely to become energized","Only pipes within 6 feet of electrical equipment"],ans:2,ref:"NEC 250.104",exp:"250.104 requires bonding of: (1) metal water piping systems — including interior piping connected to 10 ft or more of metal water pipe in direct contact with earth, (2) other metal piping systems (gas, compressed air, etc.) likely to become energized, and (3) structural metal that is interconnected and exposed to contact with electricity. All must be bonded to the service equipment or separately derived system."},
{id:130,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"An equipment grounding conductor (EGC) must be sized to safely carry the maximum ground-fault current. From which NEC table is the minimum EGC size determined?",opts:["Table 310.16","Table 250.66","Table 250.122","Table 300.5"],ans:2,ref:"NEC Table 250.122",exp:"Table 250.122 establishes minimum EGC sizes based on the rating of the overcurrent device protecting the circuit. For example: 15A OCPD = 14 AWG copper minimum EGC; 20A = 12 AWG; 30A = 10 AWG; 60A = 10 AWG; 100A = 8 AWG; 200A = 6 AWG copper. EGCs may always be larger than the minimum required."},
{id:131,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"Plate electrodes used as grounding electrodes must expose at least how much surface area to exterior soil?",opts:["1 square foot","4 square feet","6 square feet","2 square feet"],ans:3,ref:"NEC 250.52(A)(7)",exp:"Each plate electrode shall expose not less than 0.186 m² (2 ft²) of surface to exterior soil. Bare or electrically conductive coated iron or steel plates must be at least 6.4 mm (1/4 in.) thick. Solid uncoated electrodes of nonferrous metal (copper) need only be 1.5 mm (0.06 in.) thick. Plate electrodes are less common than rods but are listed in 250.52 as acceptable grounding electrodes."},
{id:132,mod:4,cat:"Grounding & Bonding",diff:"Medium",q:"What additional grounding connection is required when a transformer supplying a service is located outside the building?",opts:["The utility is responsible for all outdoor grounding","Only required for transformers over 75 kVA","None — inside panel grounding is sufficient","A grounding connection from the grounded service conductor to a grounding electrode at the transformer or elsewhere outside the building"],ans:3,ref:"NEC 250.24(A)(2)",exp:"When the transformer is outside, at least one additional grounding connection must be made from the grounded service conductor to a grounding electrode — either at the transformer or elsewhere outside the building. This provides a local low-impedance path to earth for lightning and surge energy before it enters the building through the service conductors."},
{id:133,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"What does Article 250 require to be true about the grounding electrode system's connection to a metal underground water pipe that is the only electrode used?",opts:["The metal underground water pipe may serve as the sole grounding electrode if at least 10 feet are in contact with earth","If a metal underground water pipe is the only grounding electrode, it shall be supplemented by an additional electrode","Metal underground water pipe is not permitted as a grounding electrode","At least 5 feet of the water pipe must be in contact with earth"],ans:1,ref:"NEC 250.53(D)(2)",exp:"250.53(D)(2): a metal underground water pipe shall be supplemented by an additional grounding electrode where the water pipe is the only available grounding electrode. A single water pipe is not sufficient — it must be supplemented by one of the other electrodes listed in 250.52 (typically a ground rod). The supplemental electrode must also be part of the grounding electrode system."},
{id:134,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"A 200A service has 3/0 AWG copper service-entrance conductors. What is the minimum GEC size to the grounding electrode, and how does this change if only ground rod electrodes are present?",opts:["4 AWG copper for any electrode type","2 AWG copper for water pipe; 4 AWG for ground rods","For 3/0 AWG copper SE conductors: 4 AWG copper GEC minimum; but where only rods, plates, or concrete-encased electrodes are used, the GEC to those electrodes need not exceed 6 AWG copper","Always 6 AWG copper regardless of service size"],ans:2,ref:"NEC Table 250.66 & 250.66(A)",exp:"Table 250.66 specifies 4 AWG copper minimum GEC for 3/0 AWG service conductors. However, 250.66(A) limits the GEC to rod, pipe, and plate electrodes and concrete-encased electrodes to a maximum of 6 AWG copper — regardless of service size. This is a code trap: you might calculate 4 AWG from the table, but if only ground rods are present, 6 AWG is the maximum required."},
{id:135,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"An EGC is run with a 20-ampere branch circuit in conduit. Later, the overcurrent device is upgraded to 60 amperes with larger conductors. What must happen to the EGC?",opts:["The existing EGC is acceptable — it was correctly sized for the original circuit","The EGC must be replaced with a conductor sized for the 60A overcurrent device per Table 250.122","Only the phase conductors need replacing, not the EGC","EGC sizing is not related to overcurrent device rating"],ans:1,ref:"NEC Table 250.122",exp:"EGC sizing from Table 250.122 is based on the rating of the overcurrent device protecting the circuit. Upgrading the OCPD from 20A to 60A changes the minimum EGC requirement: 20A = 12 AWG minimum; 60A = 10 AWG minimum. When upgrading a circuit's overcurrent device and conductors, the EGC must also be evaluated and upgraded if the new OCPD requires a larger minimum EGC."},
{id:136,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"What makes a concrete-encased electrode preferred over a simple ground rod?",opts:["It provides a lower-impedance, more stable connection to earth due to the large surface area of the concrete foundation in direct contact with moist earth, and is required to be installed where a concrete footing is available","It is the only electrode listed in 250.52 for residential construction","It requires no supplemental electrode","Less expensive to install"],ans:0,ref:"NEC 250.52(A)(3)",exp:"Concrete encased electrodes (Ufer grounds) provide excellent grounding due to the large surface area of reinforced concrete in contact with moist earth — concrete has higher moisture content than surrounding soil. The electrode is protected from corrosion and mechanical damage. The 2023 NEC requires using the concrete-encased electrode when available. Multiple concrete-encased electrodes need only have one bonded into the GES."},
{id:137,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"An isolated equipment grounding conductor (isolated EGC) is installed for sensitive electronic equipment. What is required?",opts:["No special requirements — standard EGC installation","Isolated EGCs must be installed in nonmetallic conduit only","An isolated EGC is not permitted — all EGCs must bond together","The isolated EGC must be run back to the service or transformer without connection to intermediate boxes or raceways"],ans:3,ref:"NEC 250.146(D)",exp:"250.146(D) permits receptacles with an isolated EGC for the reduction of electrical noise. The isolated EGC must be run to the service equipment or source of the separately derived system — it must not be connected to intermediate equipment grounding conductors or enclosures. The conduit/raceway equipment ground provides fault protection; the isolated EGC provides a clean, noise-free ground for sensitive electronics."},
{id:138,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"Which of the following is specifically listed as NOT permitted for use as a grounding electrode?",opts:["Metal underground water pipe in direct contact with earth","Concrete-encased rebar","Ground ring of 2 AWG bare copper","Underground gas piping system"],ans:3,ref:"NEC 250.52(B)",exp:"250.52(B) explicitly states that underground gas piping systems shall not be used as a grounding electrode. Other items in 250.52(B) that are not permitted as grounding electrodes include aluminum, underground conductors in the supply side wiring of the utility, and metal underground structures installed as sacrificial anodes. Gas piping systems may require bonding but may not serve as the grounding electrode."},
{id:139,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"A supply-side bonding jumper is required between a transformer enclosure and the first disconnecting means when they are in separate enclosures. How is it sized?",opts:["Same size as the grounding electrode conductor","Same size as the grounded (neutral) conductor of the separately derived system","Based on 250.102(C) — the same table used for service-entrance conductor bonding","Equal to the largest ungrounded conductor of the derived system, not to exceed 3/0 AWG copper"],ans:2,ref:"NEC 250.30(A)(2)",exp:"The supply-side bonding jumper for a separately derived system in separate enclosures shall be sized using 250.102(C) — based on the size of the derived ungrounded conductors. The supply-side bonding jumper shall not be required to be larger than the derived ungrounded conductors. This jumper provides the bonding path between the transformer and the first disconnect."},
{id:140,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"When an EGC is installed in a metallic raceway, which of the following is true about the raceway itself?",opts:["The raceway serves as the EGC — no wire EGC is required","The raceway bonds to the box, but a separate wire EGC must always be run","A metallic raceway is a listed equipment grounding conductor per 250.118 and provides fault current path","The raceway cannot serve as an EGC — metal raceways are not listed for EGC use"],ans:2,ref:"NEC 250.118(2)",exp:"250.118 lists the types of equipment grounding conductors recognized by the NEC. Listed metallic raceways — including RMC, IMC, and EMT — are listed as EGCs. When properly connected with fittings rated for grounding, the raceway itself serves as the EGC, and a separate wire EGC is not required (though one may always be added). The raceway's continuous metal path provides the ground-fault current return path."},
{id:141,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"Which of the following statements about the grounding electrode conductor (GEC) installation is correct?",opts:["GECs are not required to be protected from physical damage","GECs installed in metal enclosures shall be bonded to the enclosure at each end of the raceway","GECs must always be run in conduit regardless of size","GECs larger than 4 AWG may be in any wiring method without protection"],ans:1,ref:"NEC 250.64(E)",exp:"250.64(E): grounding electrode conductors installed in metal enclosures shall be made electrically continuous with the metal enclosure from the point of attachment of the GEC to the grounding electrode to the service or transformer. The conductor shall be bonded to the enclosure at each end. This prevents the enclosure from acting as an air-core transformer and inductively impeding the flow of fault current through the GEC during a fault."},
{id:142,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"What does the NEC require when the grounding electrode conductor must be spliced?",opts:["Splicing is never permitted in a GEC","Splices are permitted using irreversible compression connectors or exothermic welding only","Splices are permitted using listed connectors, irreversible compression connectors, or exothermic welding at accessible locations","Wire nuts are acceptable for GEC splices"],ans:2,ref:"NEC 250.64(C)",exp:"GECs shall not be spliced except: (1) irreversible compression-type connectors listed as grounding and bonding equipment, (2) exothermic welding, or (3) connections to busbars at panelboards or service equipment. Listed wire connectors used in junction boxes are not permitted. GEC continuity is critical — improper splices create high-impedance points that defeat the electrode's effectiveness."},
{id:143,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"Structural metal that is interconnected to form a building frame and exposed to contact with electricity shall be bonded. What connection satisfies this requirement for a high-rise building?",opts:["Ground rods at the foundation connect structural steel automatically","Structural steel must be explicitly connected to the grounding electrode system with a GEC","Structural metal meeting the requirements of 250.52(A)(2) for a metal frame building electrode also satisfies the bonding requirement","Only metal within 6 feet of electrical equipment needs bonding"],ans:2,ref:"NEC 250.52(A)(2) & 250.104(C)",exp:"The metal frame of a building or structure connected to earth by the structural foundation or grounding electrodes described in 250.52 is both a grounding electrode and satisfies the structural metal bonding requirement of 250.104(C). In steel-framed buildings, the structural steel itself is the grounding electrode system — the GEC connects directly to it, and it forms a continuous bonded system throughout the building."},
{id:144,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"Gas piping entering a building that is likely to become energized shall be bonded. Where must this bonding connection be made?",opts:["At the point where the gas pipe exits the ground","At the first union inside the building","To the service equipment or to the same terminal or conductor where the building's bonding electrode conductor is connected","At the gas meter only — the utility bonds downstream"],ans:2,ref:"NEC 250.104(B)",exp:"Exposed interior metal gas piping shall be bonded to the service equipment enclosure, the grounded conductor at the service, the grounding electrode conductor where of sufficient size, or to one of the grounding electrodes. The bonding jumper must be sized per Table 250.122 based on the overcurrent device rating protecting the branch circuit supplying the area where the gas piping is located."},
{id:145,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"An equipment grounding conductor must carry what level of fault current without failure?",opts:["No more than 30 milliamperes","The maximum ground fault current likely to be imposed on it from any point on the wiring system to the electrical supply source","Only the current required to trip the overcurrent device","10% of the circuit's normal operating current"],ans:1,ref:"NEC 250.4(A)(5)",exp:"The effective ground-fault current path must be capable of safely carrying the maximum ground-fault current likely to be imposed on it from any point on the wiring system where a ground fault occurs to the electrical supply source. This is why Table 250.122 sizes EGCs based on the overcurrent device rating — a larger OCPD means higher potential fault current, requiring a larger EGC."},
{id:146,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"What is the minimum burial depth for a ground rod electrode?",opts:["4 feet","3 feet","6 feet","8 feet, or as deep as practical if rock prevents full depth"],ans:3,ref:"NEC 250.53(G)",exp:"Ground rods shall be driven to the full length of the rod (8 ft minimum) into the earth. If rock bottom prevents full depth, the rod shall be driven at an angle not to exceed 45 degrees from vertical, or buried in a trench at least 750 mm (30 in.) deep. The rod must be below permanent moisture level to be effective — deep enough for good soil contact throughout the year."},
{id:147,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"When must a separate structure's disconnecting means enclosure be grounded to the grounding electrode at that structure?",opts:["Never — only the service equipment needs a grounding electrode","Only when the structure is more than 100 feet from the main building","Always — whenever a separate structure with its own disconnecting means is present, the disconnecting means enclosure must be connected to the grounding electrode system at that structure","Only when the feeder does not include an EGC"],ans:2,ref:"NEC 250.32(A)",exp:"For each separate building or structure supplied by a feeder or branch circuit, the disconnecting means enclosure shall be connected to a grounding electrode at that structure. The EGC from the feeder bonds the equipment at the separate structure to the source's grounding system. The local grounding electrode bonds the equipment to the earth at the local site — two separate but required grounding connections."},
{id:148,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"Why is it critical that the main bonding jumper not be installed in a subpanel (load-side panelboard)?",opts:["It would make the neutral too large","It would violate the single grounding point rule — allowed only at service","Installing a neutral-to-EGC bond at a subpanel creates parallel neutral current paths where normal neutral current flows on EGC conductors and metal enclosures, creating shock hazard and interference","The main bonding jumper is not related to panel neutral connections"],ans:2,ref:"NEC 250.24(B)",exp:"A grounded conductor shall not be connected to equipment grounding conductors or metal enclosures on the load side of the service disconnecting means. If bonded in a subpanel, neutral current would have two parallel paths back to the source: the neutral conductor AND the EGC/metallic enclosures. This creates current on metal parts that could shock someone touching equipment, and creates electromagnetic interference. Strict prohibition."},
{id:149,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"What is the minimum size bonding conductor required to bond the service equipment enclosure to the grounded conductor for a 400-ampere service with 500 kcmil copper service-entrance conductors?",opts:["4 AWG copper","2 AWG copper","1/0 AWG copper","3/0 AWG copper"],ans:2,ref:"NEC Table 250.102(C)(1)",exp:"Table 250.102(C)(1) sizes the supply-side bonding jumper (and main bonding jumper) based on service-entrance conductor size. For 500 kcmil copper service-entrance conductors: 1/0 AWG copper minimum bonding jumper. This table is the same reference used for GEC sizing (Table 250.66 references Table 250.102(C)(1) for parallel conductors)."},
{id:150,mod:4,cat:"Grounding & Bonding",diff:"Hard",q:"A listed metallic conduit used as an EGC is connected to a metal box using a locknut. Is this an acceptable EGC connection?",opts:["Yes — locknuts are acceptable for EGC connections on standard raceways","No — only threaded connections are acceptable for EGC continuity","Depends on the conduit type — acceptable for RMC but not EMT","No — a separate wire EGC must always be added when using locknuts"],ans:0,ref:"NEC 250.118(2) & 250.148",exp:"Metal raceways listed as EGCs per 250.118 provide the grounding path through their continuous metal structure. Standard fittings — including locknuts and set-screw connectors for EMT — maintain the metallic continuity required. The key is that fittings must be made tight and the raceway continuously and properly connected. For RMC, threaded connections are standard. For EMT, compression or set-screw fittings with tight connections suffice."},
// MODULE 5: WIRING METHODS (55)
  {id:163,mod:5,cat:"Wiring Methods",diff:"Easy",q:"Type NM cable is restricted to what maximum ampacity rating, even when 90°C-rated conductors are used inside?",opts:["40°C rated conductor ampacity","60°C rated conductor ampacity","75°C rated conductor ampacity","90°C rated conductor ampacity"],ans:1,ref:"NEC 334.80",exp:"The ampacity of Types NM and NMC cable shall not exceed that of a 60°C (140°F) rated conductor. The 90°C rating may be used for ampacity adjustment and correction calculations only, provided the final result does not exceed the 60°C ampacity. This limits NM cable to the 60°C column of Table 310.16."},
  {id:164,mod:5,cat:"Wiring Methods",diff:"Easy",q:"Flexible metal conduit (FMC) is specifically prohibited from installation in which of the following locations?",opts:["Exposed dry interior locations","Concealed spaces inside finished walls","Wet locations","Accessible ceiling spaces above suspended ceilings"],ans:2,ref:"NEC 348.12(1)",exp:"FMC shall not be used in wet locations. Additional prohibited uses include hoistways (except per 620.21(A)(1)), storage battery rooms, hazardous locations except as permitted by Chapter 5, locations with deteriorating materials such as oil or gasoline, underground or embedded in concrete, and where subject to physical damage."},
  {id:165,mod:5,cat:"Wiring Methods",diff:"Easy",q:"What component inside Type AC cable provides the fault-current path to qualify the cable assembly as an equipment grounding conductor?",opts:["The internal bonding strip","The paper wrap surrounding the conductors","The THHN-rated conductors inside the cable","The bare aluminum outer armor alone"],ans:0,ref:"NEC 320.108",exp:"Type AC cable shall provide an adequate path for fault current as required by 250.4(A)(5) or (B)(4) to act as an equipment grounding conductor. The internal bonding strip of copper or aluminum in intimate contact with the armor for its entire length provides this fault-current path along with the armor itself."},
  {id:166,mod:5,cat:"Wiring Methods",diff:"Easy",q:"Rigid metal conduit (RMC) may be constructed from which set of materials?",opts:["Steel or PVC only","Steel, aluminum, or PVC","Steel, aluminum, red brass, or stainless steel","Aluminum, galvanized steel, or copper"],ans:2,ref:"NEC 344.100",exp:"RMC shall be made of one of the following: (1) Steel with protective coatings, (2) Aluminum, (3) Red brass, or (4) Stainless steel. PVC conduit is a separate wiring method covered under Article 352. The material choice affects corrosion resistance for specific environments."},
  {id:167,mod:5,cat:"Wiring Methods",diff:"Easy",q:"Where rigid metal conduit (RMC) enters a box or fitting, what fitting must be installed to protect conductors from abrasion?",opts:["A locknut only","A threadless coupling","A bushing","A bonding jumper"],ans:2,ref:"NEC 344.46",exp:"Where a conduit enters a box, fitting, or other enclosure, a bushing shall be provided to protect the wires from abrasion unless the box, fitting, or enclosure is designed to provide such protection. See 300.4(G) for additional protection requirements for conductors 4 AWG and larger at bushings."},
  {id:168,mod:5,cat:"Wiring Methods",diff:"Easy",q:"Liquidtight flexible metal conduit (LFMC) is specifically permitted where installations require protection from which hazard?",opts:["Machine oils, liquids, vapors, or solids","Extreme cold temperatures","High-voltage transient surges","Physical impact and crushing forces"],ans:0,ref:"NEC 350.10(1)",exp:"LFMC is permitted where conditions of installation, operation, or maintenance require flexibility or protection from machine oils, liquids, vapors, or solids. It is also permitted in hazardous locations per Chapter 5, for direct burial when listed and marked for the purpose, and where conductors are rated higher than the LFMC temperature rating."},
  {id:169,mod:5,cat:"Wiring Methods",diff:"Easy",q:"The general rule requires a box or conduit body to be installed at each splice, junction, switch, and outlet point in a wiring system. Which Code article establishes this requirement?",opts:["Article 312","Article 408","Article 250","Article 300"],ans:3,ref:"NEC 300.15",exp:"Section 300.15 requires a box or conduit body at each outlet point, switch point, conductor splice, conductor junction, conductor termination, and pull point in the wiring system. Subsections (A) through (L) list specific exceptions for certain wiring methods where a box is not required."},
  {id:170,mod:5,cat:"Wiring Methods",diff:"Easy",q:"A 2023 NEC addition created a new derating requirement when more than how many Type NM cables are bundled through the same sealed opening in wood framing?",opts:["1 cable","2 cables","3 cables","4 cables"],ans:1,ref:"NEC 335.3",exp:"New in the 2023 NEC (335.3): Where more than two NM cables containing two or more current-carrying conductors are installed without maintaining spacing through the same opening in wood framing sealed with thermal insulation, caulk, or sealing foam, the ampacity of each conductor shall be adjusted per Table 310.15(C)(1). The same rule applies when cables are in contact with thermal insulation without spacing."},
  {id:171,mod:5,cat:"Wiring Methods",diff:"Easy",q:"The interior of enclosures and raceways installed underground is automatically classified as what type of location?",opts:["Damp location","Wet location","Dry location","Classified hazardous location"],ans:1,ref:"NEC 300.5(B)",exp:"The interior of enclosures or raceways installed underground shall be considered to be a wet location. Insulated conductors and cables installed in these underground enclosures or raceways must comply with 310.10(C), which requires conductors rated for use in wet locations."},
  {id:172,mod:5,cat:"Wiring Methods",diff:"Easy",q:"A listed outlet box installed on a vertical surface may support a luminaire up to what default maximum weight without a special marking on the box?",opts:["50 lb (23 kg)","70 lb (32 kg)","15 lb (7 kg)","35 lb (16 kg)"],ans:0,ref:"NEC 314.27(A)(1)",exp:"Boxes used at luminaire or lampholder outlets on vertical surfaces shall be identified and marked on the interior of the box to indicate the maximum weight of the luminaire permitted if other than 23 kg (50 lb). If no weight marking appears on the box, the default assumed maximum is 50 lb."},
  {id:173,mod:5,cat:"Wiring Methods",diff:"Easy",q:"What is the maximum interval between supports for Type NM cable in a horizontal run through bored holes in framing members?",opts:["Every 2 ft (0.6 m)","Every 3 ft (0.9 m)","Every 4½ ft (1.4 m)","Every 6 ft (1.8 m)"],ans:2,ref:"NEC 334.30(A)",exp:"Type NM cable shall be supported and secured at intervals not exceeding 1.4 m (4½ ft). In horizontal runs through holes and notches in framing, cables are considered supported and secured where support does not exceed 4½ ft intervals. Additionally, the cable must be secured within 300 mm (12 in.) of each box or termination."},
  {id:174,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Type NM cable is permitted in multi-family dwellings only when the building is of which construction types?",opts:["Types III, IV, and V","All construction types regardless of height","Types I and II only","Types II and III only"],ans:0,ref:"NEC 334.10(2)",exp:"NM cable is permitted in multi-family dwellings and their detached garages that are permitted to be of Types III, IV, and V construction. It is NOT permitted in multi-family dwellings required to be of Type I or II (fire-resistive) construction, which are typically high-rise or other large buildings."},
  {id:175,mod:5,cat:"Wiring Methods",diff:"Medium",q:"When Type NM cable is installed in a structure other than a 1-, 2-, or multi-family dwelling (such as a small commercial building), it must be concealed within assemblies providing a thermal barrier with at least what finish rating?",opts:["15-minute finish rating","30-minute finish rating","5-minute finish rating","10-minute finish rating"],ans:0,ref:"NEC 334.10(3)",exp:"In other structures permitted to be of Types III, IV, and V construction, NM cables shall be concealed within walls, floors, or ceilings that provide a thermal barrier of material having at least a 15-minute finish rating as identified in listings of fire-rated assemblies. This prevents premature failure of the cable in a fire scenario."},
  {id:176,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Under the 2023 NEC, when more than two NM cables are bundled without spacing through a sealed framing opening, the ampacity must be adjusted using which table?",opts:["Table 310.15(C)(1) — conductor bundling adjustment factors","Table 310.16 — conductor ampacity at 60°C","Table 250.122 — equipment grounding conductor sizing","Table 310.15(B)(1) — ambient temperature correction factors"],ans:0,ref:"NEC 335.3",exp:"Per 2023 NEC 335.3: where more than two NM cables with two or more current-carrying conductors are installed without maintaining spacing through the same sealed opening or in contact with thermal insulation, each conductor's ampacity shall be adjusted per Table 310.15(C)(1). Importantly, the exception that normally permits no adjustment for short bundled runs does not apply here."},
  {id:177,mod:5,cat:"Wiring Methods",diff:"Medium",q:"The 90°C ampacity column in Table 310.16 may be applied to NM cable conductors under which limited circumstance?",opts:["Only when installed in metal raceways with ventilation","Only when the circuit voltage exceeds 240 volts","Only for ampacity adjustment and correction calculations, where the final result must not exceed the 60°C value","Only in commercial buildings where ambient temperature exceeds 30°C"],ans:2,ref:"NEC 334.80",exp:"The 90°C rating shall be permitted to be used for ampacity adjustment and correction calculations only, provided the final calculated ampacity does not exceed that of a 60°C rated conductor. For example, if derating is required for bundling, you may start with the 90°C ampacity and derate, but the final answer cannot exceed the 60°C column value."},
  {id:178,mod:5,cat:"Wiring Methods",diff:"Medium",q:"In addition to flexible metal tape armor, Type AC cable must contain what other component for its entire length?",opts:["An outer PVC weatherproof jacket","A metallic foil shield over the conductors","An internal bonding strip of copper or aluminum","A separate bare equipment grounding conductor"],ans:2,ref:"NEC 320.100",exp:"Type AC cable shall have an armor of flexible metal tape AND shall have an internal bonding strip of copper or aluminum in intimate contact with the armor for its entire length. This bonding strip, combined with the armor, provides the fault-current path required to serve as an equipment grounding conductor per 250.4(A)(5) or (B)(4)."},
  {id:179,mod:5,cat:"Wiring Methods",diff:"Medium",q:"FMC smaller than trade size ½ is generally not permitted, but trade size ⅜ is allowed as an exception for which application?",opts:["Concealed installations in finished walls of dwellings","Enclosing motor leads per 430.245(B) and in lengths not exceeding 6 ft for specific uses","High-temperature applications above 90°C in industrial locations","Direct burial in dry soil at a depth of 24 inches"],ans:1,ref:"NEC 348.20(A)(1)–(2)",exp:"FMC smaller than trade size ½ (metric designator 16) shall not be used except for metric designator 12 (trade size ⅜), which is permitted: (1) for enclosing the leads of motors per 430.245(B), and (2) in lengths not exceeding 1.8 m (6 ft) for specific uses such as connecting luminaires, equipment requiring flexibility, and tap connections to equipment in accessible ceilings."},
  {id:180,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Liquidtight flexible metal conduit (LFMC) may be installed for direct burial only when which condition is met?",opts:["It is installed at a minimum depth of 24 inches per Table 300.5(A)","It is protected by a concrete-encased outer sleeve","It is listed and marked for the purpose of direct burial","It is used with grounding bushings at each termination end"],ans:2,ref:"NEC 350.10(3)",exp:"LFMC shall be permitted for direct burial where listed and marked for the purpose. Not all LFMC is suitable for direct burial — the installer must verify that the specific product bears a listing and marking for direct burial applications. General-purpose LFMC without this marking cannot be used underground."},
  {id:181,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Rigid metal conduit (RMC) installed with listed fittings is recognized as serving what grounding function without requiring a separate wire?",opts:["Grounding electrode","Equipment bonding jumper","Equipment grounding conductor","System grounding conductor"],ans:2,ref:"NEC 344.60",exp:"RMC shall be permitted as an equipment grounding conductor. When installed with proper listed fittings and maintained continuity throughout, RMC itself satisfies the equipment grounding conductor requirement of 250.118. This is a key advantage over nonmetallic raceways, which require a separate EGC wire."},
  {id:182,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Cables and conductors routed underground and passing beneath a building must generally be installed in what?",opts:["Concrete-encased ductwork","A raceway","LFMC or LFNC only","Directly buried Type MC cable without additional requirements"],ans:1,ref:"NEC 300.5(C)",exp:"Underground cable and conductors installed under a building shall be in a raceway. Exceptions permit Type MI cable embedded in concrete or masonry per 332.10(6) and Type MC cable listed for direct burial or concrete encasement per 330.10(A)(5). The raceway requirement protects conductors from shifting or settlement damage under the structure."},
  {id:183,mod:5,cat:"Wiring Methods",diff:"Medium",q:"The number and size of conductors installed in any raceway must not exceed what general limitation?",opts:["What will permit heat dissipation and ready installation or withdrawal without damage to conductors","More than 10 current-carrying conductors without derating","The conduit body volume per Chapter 9, Table 4","40% of the cross-sectional area of the raceway"],ans:0,ref:"NEC 300.17",exp:"The number and size of conductors and cables in any raceway shall not be more than will permit dissipation of the heat and ready installation or withdrawal of the conductors or cables without damage to the conductors, cables, or their insulation. The specific fill percentages (40% for 3 or more conductors) are defined in Chapter 9, Table 1, referenced by each raceway article."},
  {id:184,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Which of these is a location where FMC is specifically NOT permitted?",opts:["Storage battery rooms","Between motor starters and motor terminal boxes","Exposed runs in a dry commercial kitchen","Concealed above a suspended ceiling in an office"],ans:0,ref:"NEC 348.12(3)",exp:"FMC shall not be used in storage battery rooms. Other prohibited locations include wet locations, hoistways (except per 620.21(A)(1)), hazardous locations except as permitted by Chapter 5, where deteriorating materials are present, underground or embedded in concrete, and where subject to physical damage. Dry exposed and concealed locations are generally permitted per 348.10."},
  {id:185,mod:5,cat:"Wiring Methods",diff:"Medium",q:"In a pull or junction box containing conductors 4 AWG and larger, what is the minimum length required in the box for a straight pull?",opts:["8 times the largest conduit trade size","10 times the largest conduit trade size","12 times the largest conduit trade size","6 times the largest conduit trade size"],ans:0,ref:"NEC 314.28(A)(1)",exp:"For straight pulls, the length of the box shall not be less than 8 times the trade size diameter of the largest raceway. For example, with a 2-inch conduit, the minimum box length is 8 × 2 = 16 inches. This ensures enough straight-line distance to pull conductors without excessive bending stress at the conduit entry."},
  {id:186,mod:5,cat:"Wiring Methods",diff:"Medium",q:"For angle or U-pulls in a junction box, the distance between each raceway entry and the opposite wall must be at least how many times the largest conduit trade size?",opts:["6 times","8 times","10 times","4 times"],ans:0,ref:"NEC 314.28(A)(2)",exp:"For angle or U-pulls, the distance between each raceway entry inside the box and the opposite wall shall not be less than 6 times the trade size of the largest raceway. This minimum is further increased by adding the trade sizes of any additional raceways entering on the same wall as the raceway being calculated."},
  {id:187,mod:5,cat:"Wiring Methods",diff:"Medium",q:"The total cross-sectional area of conductors in a metal wireway (auxiliary gutter) at any cross-section must not exceed what percentage of the wireway interior area?",opts:["10%","20%","40%","50%"],ans:1,ref:"NEC 376.22",exp:"The sum of the cross-sectional areas of all contained conductors at any cross section of a metal wireway shall not exceed 20% of the interior cross-sectional area of the wireway. This same 20% fill limit applies to nonmetallic wireways per 378.22. The 40% fill commonly thought of applies to raceways under Chapter 9 — wireways have the more restrictive 20% limit."},
  {id:188,mod:5,cat:"Wiring Methods",diff:"Medium",q:"In a box fill calculation, each wiring device (switch or receptacle) mounted on a single yoke counts as how many conductor volume allowances?",opts:["1 conductor allowance","2 conductor allowances (double volume)","3 conductor allowances","4 conductor allowances"],ans:1,ref:"NEC 314.16(B)(4)",exp:"For each yoke or strap containing one or more devices, a double volume allowance shall be made based on the largest conductor connected to the device. This means each switch or receptacle yoke = 2 conductor volume allowances from Table 314.16(B). A multi-gang device that occupies a single yoke still counts as just one double allowance."},
  {id:189,mod:5,cat:"Wiring Methods",diff:"Medium",q:"All cable clamps or cable connectors inside a wiring box — regardless of how many are present — together count as how many conductor fill allowances?",opts:["One allowance per individual clamp","Two allowances for all clamps combined","No allowance — clamps are not counted","One allowance for all clamps combined"],ans:3,ref:"NEC 314.16(B)(2)",exp:"Where one or more cable clamps or connectors are present in the box, a single volume allowance in accordance with Table 314.16(B) shall be made based on the largest conductor present in the box. Regardless of whether there are one, two, or five clamps, all cable clamps together count as a total of only 1 conductor volume."},
  {id:190,mod:5,cat:"Wiring Methods",diff:"Medium",q:"A wiring box installed flush in a noncombustible surface (tile, plaster, or gypsum) may be set back from the finished surface by no more than how much?",opts:["The box must be exactly flush — no setback is allowed","¼ inch (6 mm)","½ inch (12 mm)","1 inch (25 mm)"],ans:1,ref:"NEC 314.20",exp:"In noncombustible surfaces such as concrete, tile, gypsum, or plaster, flush-type boxes may be set back no more than 6 mm (¼ in.) from the finished surface. For combustible surfaces, the box must be flush with the finished surface or project beyond it. Gaps greater than ⅛ in. from a box edge to combustible surface material must be repaired."},
  {id:191,mod:5,cat:"Wiring Methods",diff:"Medium",q:"LFMC is specifically prohibited in which of the following situations?",opts:["Concealed runs in dry wall cavities","Hazardous classified locations as permitted by Chapter 5","Where subject to physical damage","Direct burial installations where the product is listed for the purpose"],ans:2,ref:"NEC 350.12",exp:"LFMC shall not be used where subject to physical damage. It is permitted in exposed or concealed dry locations, in hazardous locations where specifically permitted by Chapter 5, for direct burial where listed and marked, where flexibility is required by operating conditions, and where protection from oil or liquids is needed per 350.10(1)."},
  {id:192,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Type NM cable must be secured to a support within what maximum distance of each box, cabinet, or termination fitting?",opts:["6 inches (150 mm)","12 inches (300 mm)","18 inches (450 mm)","24 inches (600 mm)"],ans:1,ref:"NEC 334.30(A)",exp:"Nonmetallic-sheathed cable shall be supported at intervals not exceeding 4½ ft and shall be secured within 300 mm (12 in.) of each box, cabinet, conduit body, or other NM cable termination. This 12-inch rule ensures the cable is mechanically secured close to connection points, preventing strain on the conductor terminations."},
  {id:193,mod:5,cat:"Wiring Methods",diff:"Medium",q:"All equipment grounding conductors entering a box — regardless of how many there are — count as how many conductor fill allowances in box fill calculations?",opts:["One allowance for each EGC present","Two allowances for each EGC present","A single allowance for all EGCs combined, sized to the largest EGC","No allowance — EGCs are excluded from box fill"],ans:2,ref:"NEC 314.16(B)(5)",exp:"Where one or more equipment grounding conductors or equipment bonding jumpers enter a box, a single volume allowance shall be made based on the largest EGC present in the box. Whether there are two EGCs or ten, they all together count as only 1 conductor volume in the box fill calculation."},
  {id:194,mod:5,cat:"Wiring Methods",diff:"Medium",q:"When 4 to 6 current-carrying conductors are in the same raceway or cable, the ampacity from Table 310.16 must be multiplied by what adjustment factor?",opts:["50%","70%","80%","90%"],ans:2,ref:"NEC 310.15(C)(1), Table 310.15(C)(1)",exp:"Table 310.15(C)(1) requires ampacity adjustment when more than 3 current-carrying conductors occupy the same raceway or cable. For 4–6 conductors: multiply by 80%. For 7–9 conductors: multiply by 70%. For 10–20 conductors: multiply by 50%. Equipment grounding conductors and neutral conductors carrying only unbalanced current are not counted."},
  {id:195,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Type MC cable may be used for direct burial only when it meets what requirement?",opts:["Installed at a minimum depth per Table 300.5(A) in all cases","Listed and identified for direct burial or concrete encasement","Wrapped with an additional PVC jacket applied in the field","Protected by an outer metal conduit as a sleeve"],ans:1,ref:"NEC 330.10(A)(5)",exp:"Type MC cable listed for direct burial shall be permitted for use in direct burial or concrete-encasement applications. The cable must carry a specific listing for direct burial — standard armored MC cable without this listing cannot be buried directly. Only MC cable marked and listed for direct burial or concrete encasement qualifies."},
  {id:196,mod:5,cat:"Wiring Methods",diff:"Medium",q:"In a multiwire branch circuit, the continuity of the grounded (neutral) conductor must not depend on the connection of a device such as a receptacle. What installation method satisfies this requirement?",opts:["Connect the neutral to only one receptacle per circuit","Use a split-wired receptacle with separate overcurrent protection","Install a neutral disconnect link at each outlet","Use pigtail connections so the neutral is continuous regardless of device removal"],ans:3,ref:"NEC 300.13(B)",exp:"The continuity of a grounded conductor shall not depend on the connection of a device. In multiwire branch circuits, the grounded conductor must be connected via a pigtail from the circuit conductors to the device, so removing a receptacle or switch does not interrupt the neutral path and create overvoltage on the remaining circuit."},
  {id:197,mod:5,cat:"Wiring Methods",diff:"Medium",q:"The percentage fill limit for more than 2 conductors in electrical metallic tubing (EMT) per Chapter 9, Table 1 is what?",opts:["40% of cross-sectional area","53% of cross-sectional area","60% of cross-sectional area","31% of cross-sectional area"],ans:0,ref:"NEC 358.22, Chapter 9 Table 1",exp:"Per Chapter 9, Table 1, for raceways including EMT: for 1 conductor the fill limit is 53%; for 2 conductors it is 31%; for 3 or more conductors it is 40% of the raceway cross-sectional area. The 40% limit for 3 or more conductors applies to all raceway types including RMC, IMC, FMC, PVC, and EMT."},
  {id:198,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Where Type NM cable enters a nonmetallic box, the cable's outer sheath must extend how far inside the box beyond the cable entry fitting?",opts:["At least ¼ inch (6 mm)","At least ½ inch (12 mm)","At least 1 inch (25 mm)","It must be flush — no extension required"],ans:0,ref:"NEC 314.17(B)(1)",exp:"Where nonmetallic-sheathed cable enters a nonmetallic box, the sheath shall extend not less than 6 mm (¼ in.) inside the box and beyond any cable clamp. This ensures the sheath — not just the individual insulated conductors — passes through the knock-out opening, protecting the conductors from abrasion at the box wall edge."},
  {id:199,mod:5,cat:"Wiring Methods",diff:"Medium",q:"Although a 12 AWG THHN conductor has a 90°C ampacity of 30 A in Table 310.16, what is the practical overcurrent device maximum for a 12 AWG circuit conductor due to termination temperature limits?",opts:["15 amperes","20 amperes","25 amperes","30 amperes"],ans:1,ref:"NEC 310.15(A)(3), 240.4(D)",exp:"Most standard equipment is listed with 60°C or 75°C terminations. Under 310.15(A)(3), conductor ampacity shall not exceed the temperature rating of connected terminations. The 75°C value for 12 AWG is 25 A, but 240.4(D) further caps overcurrent protection for 12 AWG copper at 20 A. The 90°C ampacity is only used for derating calculations, not to determine the breaker size."},
  {id:200,mod:5,cat:"Wiring Methods",diff:"Hard",q:"The 2023 NEC added Art. 335.3 with two distinct triggers for NM cable ampacity derating. Which pair of scenarios correctly identifies both?",opts:["More than 3 NM cables in any one conduit, OR more than 3 cables run in a cable tray","More than 2 NM cables through the same sealed opening in framing, OR more than 2 NM cables in contact with thermal insulation without maintained spacing","More than 2 NM cables in a metal raceway, OR more than 2 NM cables passing within 12 inches of a heat source","More than 4 NM cables through any single stud hole, OR cables touching each other in accessible attic runs"],ans:1,ref:"NEC 335.3",exp:"The 2023 NEC added 335.3 with two derating triggers: (1) more than two NM cables containing two or more current-carrying conductors installed without spacing through the same opening in wood framing sealed with thermal insulation, caulk, or sealing foam; and (2) more than two such NM cables installed in contact with thermal insulation without maintaining spacing. In both cases, use Table 310.15(C)(1) to adjust ampacity."},
  {id:201,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Type AC cable requires an internal bonding strip in intimate contact with the armor for its entire length. The NEC permits only which two materials for this bonding strip?",opts:["Copper or aluminum","Steel or copper","Aluminum or galvanized steel","Copper or stainless steel"],ans:0,ref:"NEC 320.100",exp:"Type AC cable shall have an armor of flexible metal tape and shall have an internal bonding strip of copper or aluminum in intimate contact with the armor for its entire length. The copper or aluminum bonding strip, together with the armor, provides the fault-current path to serve as an equipment grounding conductor as required by 250.4(A)(5) or (B)(4)."},
  {id:202,mod:5,cat:"Wiring Methods",diff:"Hard",q:"LFMC permits the use of conductors rated at a temperature higher than the conduit's listed temperature rating, but under what key restriction?",opts:["The circuit must be protected by a GFCI device at the panel","The LFMC must be replaced with LFNC in any ambient exceeding 40°C","The conductors must be enclosed in an additional approved thermal sleeve","The conductors must not be operated at a temperature exceeding the listed temperature rating of the LFMC"],ans:3,ref:"NEC 350.10(4)",exp:"Conductors or cables rated at a temperature higher than the listed temperature rating of LFMC shall be permitted to be installed in LFMC, provided the conductors or cables are not operated at a temperature higher than the listed temperature rating of the LFMC. The LFMC's temperature rating is the ceiling for operating temperature, regardless of the conductor's own rating."},
  {id:203,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A pull box has two 2-inch conduits entering on the same wall for angle pulls. Using the NEC formula for angle pulls, what is the minimum box dimension on that wall?",opts:["14 inches","16 inches","20 inches","12 inches"],ans:0,ref:"NEC 314.28(A)(2)",exp:"For angle pulls: minimum dimension = 6 × (largest conduit trade size) + sum of all other conduit trade sizes on the same wall. With two 2-inch conduits on the same wall: (6 × 2) + 2 = 14 inches minimum. The 6× multiplier applies to the largest conduit, and each additional conduit's trade size is added to the total."},
  {id:204,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A device box contains three 14 AWG conductors, one single-pole switch on a yoke, one cable clamp assembly, and two EGCs. At 2.0 cu in per 14 AWG conductor, what minimum box volume is required?",opts:["12 cu in","14 cu in","16 cu in","18 cu in"],ans:2,ref:"NEC 314.16(B)",exp:"Box fill per 314.16(B) at 2.0 cu in per 14 AWG: (1) Conductors — 3 × 2.0 = 6.0 cu in; (2) Switch yoke — double volume = 2 × 2.0 = 4.0 cu in; (3) Cable clamp — 1 × 2.0 = 2.0 cu in (all clamps count as 1); (4) EGCs — 1 × 2.0 = 2.0 cu in (all EGCs count as 1). Total = 6.0 + 4.0 + 2.0 + 2.0 = 14.0 cu in. The box marked '14 cu in' is the minimum; a standard 18 cu in box is commonly used."},
  {id:205,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Under the 2023 NEC bundling derating rule for NM cables through sealed openings, the exception that normally allows no derating for short bundled runs is specifically disallowed. What is the practical consequence of this?",opts:["Only cables exceeding 24 inches in the sealed opening must be derated","Derating applies only when the ambient temperature exceeds 30°C","Even a single NM cable through a sealed hole requires derating","The full derating factor from Table 310.15(C)(1) applies to each conductor even if the sealed section is only a few inches long"],ans:3,ref:"NEC 335.3",exp:"Section 335.3 states that the exception in 310.14(A)(2) — which normally exempts short bundled runs from derating — shall not apply when more than two NM cables pass through a sealed framing opening or are in contact with insulation. This means the full Table 310.15(C)(1) derating factor applies to each conductor even if the sealed section is only an inch or two long."},
  {id:206,mod:5,cat:"Wiring Methods",diff:"Hard",q:"RMC is permitted to be made of red brass. In what installation environment would a red brass RMC typically be selected over steel?",opts:["Highly corrosive environments where steel would corrode despite coatings","Concealed installations in residential construction","High-temperature locations near furnaces or boilers","High-voltage distribution systems above 600 volts"],ans:0,ref:"NEC 344.100",exp:"Red brass and stainless steel RMC are selected for highly corrosive environments — such as certain chemical plants, marine applications, or industrial facilities with aggressive chemicals — where steel conduit with standard protective coatings would degrade. The four permitted materials (steel with coatings, aluminum, red brass, stainless steel) provide options for varying corrosion-resistance needs."},
  {id:207,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A Type NM cable installation uses 12 AWG conductors (90°C rating). Six cables are bundled together through a sealed framing opening per 335.3, with 4 current-carrying conductors per cable. The derating factor from Table 310.15(C)(1) for this bundling scenario is 80%. What is the final permitted ampacity for each 12 AWG conductor?",opts:["20 amperes","24 amperes","25 amperes","30 amperes"],ans:0,ref:"NEC 334.80, 335.3, 310.15(C)(1)",exp:"Step 1: NM cable ampacity is limited to the 60°C rating (334.80). For 12 AWG copper at 60°C per Table 310.16 = 25 A. Step 2: Apply the 335.3 derating per Table 310.15(C)(1). Six cables × 4 current-carrying conductors = 24 total current-carrying conductors; the derating factor for 19–24 conductors is 70%... wait, for 4-6 current-carrying conductors in the same raceway it is 80%. With 6 bundles of NM, treating each cable as a group: the 80% factor for 4-6 CCC applies if we count per cable. 25 A × 80% = 20 A. The final permitted ampacity is 20 amperes."},
  {id:208,mod:5,cat:"Wiring Methods",diff:"Hard",q:"LFMC installed in a hazardous (classified) location is permitted only under what condition?",opts:["When it is the only available wiring method in that location","When specifically permitted by the applicable article in Chapter 5 for that hazard classification","When the circuit is rated at 120 volts or less","When the LFMC is listed for extra-heavy-duty use"],ans:1,ref:"NEC 350.10(2)",exp:"LFMC is permitted in hazardous (classified) locations where specifically permitted by Chapter 5. Chapter 5 articles covering Class I, Class II, and Class III locations, as well as specific occupancies, contain detailed requirements for which wiring methods are permitted and under what conditions. LFMC cannot be used in a classified location simply by choosing it — the applicable Chapter 5 article must explicitly permit it."},
  {id:209,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A straight pull box serves three parallel 4-inch conduits entering from one end. What is the minimum length of the pull box?",opts:["16 inches","24 inches","32 inches","48 inches"],ans:2,ref:"NEC 314.28(A)(1)",exp:"For straight pulls, the minimum length = 8 × the trade size of the largest conduit. With three 4-inch conduits on the same end wall, the minimum length is 8 × 4 = 32 inches. Note that for straight pulls, the number of conduits does not increase the minimum — only the largest conduit trade size matters for the 8× calculation."},
  {id:210,mod:5,cat:"Wiring Methods",diff:"Hard",q:"All equipment grounding conductors entering a box — no matter how many — count as a single volume allowance based on the largest one. However, if an equipment bonding jumper also enters the box, how is it treated in the fill calculation?",opts:["It adds an entirely new double-volume allowance","It is included in the same single EGC volume allowance","It requires a separate single-volume allowance in addition to the EGC allowance","Bonding jumpers are exempt from all box fill calculations"],ans:1,ref:"NEC 314.16(B)(5)",exp:"Where one or more equipment grounding conductors or equipment bonding jumpers enter a box, a single volume allowance shall be made based on the largest conductor present. Equipment bonding jumpers are included in this same calculation — together with all EGCs, they all count as just one conductor volume allowance based on the largest wire among all of them."},
  {id:211,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A wireway contains 15 conductors of varying sizes. The wireway's interior cross-section is 4 in × 4 in = 16 sq in. What is the maximum total cross-sectional area of all conductors permitted?",opts:["3.2 sq in (20% of 16)","6.4 sq in (40% of 16)","8.0 sq in (50% of 16)","16 sq in (100% fill)"],ans:0,ref:"NEC 376.22",exp:"Metal wireways are limited to 20% fill of the cross-sectional area. For a 4-inch × 4-inch wireway: interior area = 16 sq in × 20% = 3.2 sq in maximum total conductor cross-sectional area. This 20% limit (much more restrictive than the 40% conduit fill) allows heat dissipation and easy conductor access in wireways."},
  {id:212,mod:5,cat:"Wiring Methods",diff:"Hard",q:"When conductors of 4 AWG or larger are installed in a junction box as angle pulls, and there are two different conduit sizes entering on the same wall, what is added to the 6× calculation to determine the minimum box dimension?",opts:["Nothing — only the largest conduit size matters for angle pulls","The trade size of each additional conduit on the same wall is added to the 6× result","The sum of all conduits on all walls is added","The next larger standard conduit size is substituted in the calculation"],ans:1,ref:"NEC 314.28(A)(2)",exp:"For angle or U-pulls, the minimum dimension = 6 × (largest conduit trade size on that wall) + (sum of the trade sizes of all other conduits on that same wall). For example, if a 3-inch and a 2-inch conduit enter on the same side, the minimum is (6 × 3) + 2 = 20 inches. Each additional conduit trade size is added to the base 6× calculation."},
  {id:213,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Type NM cable ampacity is limited to 60°C values. If an installer dereates 14 AWG NM cable by 80% (for bundling per Table 310.15(C)(1)), what is the final permitted ampacity per conductor?",opts:["10 amperes","12 amperes","15 amperes","20 amperes"],ans:1,ref:"NEC 334.80, Table 310.16",exp:"14 AWG copper in Table 310.16 at 60°C = 15 A (this is also the NM cable limit per 334.80). Applying the 80% bundling derating factor: 15 A × 0.80 = 12 A. The overcurrent device protecting this circuit could not exceed 12 A, which is not a standard size — the next lower standard size of 10 A (per 240.6) would be required. This illustrates why heavy bundling of NM cable in sealed openings significantly reduces usable capacity."},
  {id:214,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Where conductors 4 AWG or larger are pulled through a nonmetallic wireway used as a pull box, the distance between entries enclosing the same conductor must comply with which pull box sizing rules?",opts:["The wireway manufacturer specifications only","A minimum 24-inch separation regardless of conduit size","No specific rule — wireway fill limits apply only","The same 8× straight-pull and 6× angle-pull rules as required for standard pull boxes per 314.28(A)"],ans:3,ref:"NEC 378.11(B)",exp:"Where conductors 4 AWG or larger are pulled through a nonmetallic wireway used as a pull box, the distance between raceway and cable entries enclosing the same conductor shall not be less than required in 314.28(A)(1) for straight pulls (8×) and 314.28(A)(2) for angle pulls (6× plus sum of others). Nonmetallic wireways used as pull boxes are held to the same dimensional standards as standard junction boxes."},
  {id:215,mod:5,cat:"Wiring Methods",diff:"Hard",q:"A listed box installed in a combustible wall (wood paneling) must be flush with or project beyond the finished surface. If a gap exists between the box edge and a combustible surface, the NEC requires that the gap be repaired if it exceeds what dimension?",opts:["⅛ inch (3 mm)","¼ inch (6 mm)","½ inch (12 mm)","1 inch (25 mm)"],ans:0,ref:"NEC 314.20",exp:"In combustible surfaces, the box must be flush with the finished surface or project beyond it. Any gap between the box and the combustible material (wood, paneling) that is greater than ⅛ in. (3 mm) must be repaired. This prevents fire from traveling through the gap and into the wall cavity from the box interior, which may be exposed to arc-producing devices."},
  {id:216,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Type SE (service-entrance) cable with 10 AWG and smaller ungrounded conductors installed in contact with thermal insulation must use what temperature rating for ampacity — similar to the NM cable limitation?",opts:["40°C rating from Table 310.16","60°C rating from Table 310.16","75°C rating from Table 310.16","90°C rating from Table 310.16"],ans:1,ref:"NEC 310.15(C)(1), Table 310.15(C)(1)",exp:"Per the informational references in 310.15(C)(1): for Type SE cable with ungrounded conductors 10 AWG and smaller installed in contact with thermal insulation, the ampacity shall be based on the 60°C (140°F) conductor temperature rating. The maximum conductor temperature rating may be used for ampacity adjustment and correction purposes, provided the final ampacity does not exceed the 60°C value. This parallels the 334.80 requirement for NM cable."},
  {id:217,mod:5,cat:"Wiring Methods",diff:"Hard",q:"Under 300.5, underground cables beneath a building must be in a raceway, but an exception applies to Type MC cable. What specific condition must Type MC cable meet to qualify for this exception?",opts:["It must be installed in PVC conduit inside the building footprint only","It must use conductors rated at 600 volts or higher","It must be buried at least 36 inches deep","It must be listed for direct burial or concrete encasement per 330.10(A)(5)"],ans:3,ref:"NEC 300.5(C), Exception No. 2",exp:"Exception No. 2 to 300.5(C) allows Type MC cable to be installed under a building without a raceway where the cable is listed for direct burial or concrete encasement in accordance with 330.10(A)(5) and 330.10(A)(11) for wet locations. The cable must carry a specific listing for those conditions — standard MC cable without that listing must be in a raceway under a building."},
// MODULE 6: EQUIPMENT GENERAL USE (35)
  {id:218,mod:6,cat:"Equipment",diff:"Easy",q:"The 2023 NEC added a prohibition that specifically bans the use of which type of lighting equipment that has been previously used and refurbished?",opts:["Reconditioned luminaires, lampholders, ballasts, LED drivers, lamps, and retrofit kits","Any luminaire manufactured before 2020","Fluorescent tube luminaires","LED retrofit kits installed per instructions"],ans:0,ref:"NEC 410.2",exp:"Reconditioned luminaires, lampholders, ballasts, LED drivers, lamps, and retrofit kits shall not be permitted in the 2023 NEC. This prohibition was added to address concerns about the integrity of critical electrical components that have been disassembled and rebuilt. Note: a retrofit kit installed per its installation instructions in a luminaire is not considered reconditioned."},
  {id:219,mod:6,cat:"Equipment",diff:"Easy",q:"All luminaires, lampholders, and retrofit kits used in electrical installations must meet what mandatory requirement?",opts:["Be listed","Be rated for the ambient temperature","Be installed only by a licensed electrician","Be approved by the authority having jurisdiction before installation"],ans:0,ref:"NEC 410.6",exp:"All luminaires, lampholders, and retrofit kits shall be listed. This listing requirement ensures that the equipment has been evaluated by a nationally recognized testing laboratory (NRTL) and meets applicable safety standards for the intended use."},
  {id:220,mod:6,cat:"Equipment",diff:"Easy",q:"Receptacles installed on 15- and 20-ampere branch circuits must be of what type?",opts:["GFCI type in all locations","Tamper-resistant type in all locations","Non-grounding type is acceptable if an EGC is not present","Grounding type"],ans:3,ref:"NEC 406.4(A)",exp:"Except as provided in 406.4(D), receptacles installed on 15- and 20-ampere branch circuits shall be of the grounding type. Grounding-type receptacles shall be installed only on circuits of the voltage class and current for which they are rated, except for specific conditions in 210.21(B)."},
  {id:221,mod:6,cat:"Equipment",diff:"Easy",q:"Tamper-resistant receptacles are required in all of the following locations EXCEPT which?",opts:["All dwelling units and their attached/detached garages","Hotel and motel guest rooms","Industrial manufacturing floor areas","Child care facilities"],ans:2,ref:"NEC 406.12",exp:"Tamper-resistant receptacles are required in: dwelling units (all), boathouses, mobile homes, hotels/motels (guest rooms and common areas), child care facilities, preschools, clinics and medical offices, transportation waiting areas, gymnasiums, dormitories, residential care/ALF facilities, foster care, nursing homes, and agricultural buildings open to the public. Industrial manufacturing floors are not in this list."},
  {id:222,mod:6,cat:"Equipment",diff:"Easy",q:"What is the minimum ampacity required for branch-circuit conductors supplying a single continuous-duty motor?",opts:["100% of the motor full-load current","115% of the motor full-load current","125% of the motor full-load current","150% of the motor full-load current"],ans:2,ref:"NEC 430.22",exp:"The ampacity of conductors for a single motor used in a continuous-duty application shall not be less than 125% of the motor full-load current rating, as determined by 430.6(A)(1). The 125% factor accounts for the fact that motors are continuous loads and provides a safety margin above the nameplate rating."},
  {id:223,mod:6,cat:"Equipment",diff:"Easy",q:"For a transformer with a primary current of 9 amperes or more and 1000 volts or less, where only primary overcurrent protection is provided, what is the maximum rating of the primary overcurrent device?",opts:["125%","150%","100%","110%"],ans:0,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B), for transformers 1000 volts or less where only primary protection is provided and the primary current is 9 amperes or more, the maximum overcurrent device rating is 125% of the transformer's rated primary current. Where 125% doesn't correspond to a standard size, the next higher standard rating is permitted."},
  {id:224,mod:6,cat:"Equipment",diff:"Easy",q:"Every circuit and circuit modification in a panelboard must have what at the panelboard door?",opts:["A legible and permanent circuit description or directory","A current rating label approved by the manufacturer","An arc-flash hazard label only","A red tag indicating the circuit is in service"],ans:0,ref:"NEC 408.4(A)",exp:"Every circuit and circuit modification shall be provided with a legible and permanent description. For panelboards, this shall be in a circuit directory located on the face of, inside of, or in an approved location adjacent to the panel door. The description must be clear, evident, specific to the purpose or use of each circuit, and not dependent on transient occupancy conditions."},
  {id:225,mod:6,cat:"Equipment",diff:"Medium",q:"A receptacle installed outdoors under a covered porch (protected from beating rain but still exposed to weather) must meet what specific requirement?",opts:["It must be a GFCI receptacle only","It must have an enclosure that is weatherproof when the receptacle is covered, and must be a listed weather-resistant type","It must be in a cast-metal box with a locking cover","It must be rated for 30 amperes minimum"],ans:1,ref:"NEC 406.9(A)",exp:"A receptacle installed outdoors in a location protected from the weather (damp location) shall have an enclosure that is weatherproof when the receptacle is covered (cap not inserted, covers closed). Additionally, all 125- and 250-volt nonlocking receptacles in these damp outdoor locations shall be listed weather-resistant type. An installation suitable for wet locations also qualifies for damp locations."},
  {id:226,mod:6,cat:"Equipment",diff:"Medium",q:"The 2023 NEC requires a grounded conductor to be installed at switch locations that control lighting in certain rooms. Which of the following is NOT one of the required room types?",opts:["Bathrooms","Hallways","Stairways","Utility rooms"],ans:3,ref:"NEC 404.2(C)",exp:"A grounded circuit conductor is required at switch locations controlling lighting supplied by a grounded general-purpose branch circuit serving: bathrooms, hallways, stairways, and habitable rooms or occupiable spaces as defined in the applicable building code. Utility rooms (unfinished) are not specifically listed — the requirement applies to occupied living spaces."},
  {id:227,mod:6,cat:"Equipment",diff:"Medium",q:"What is the minimum clearance required between a surface-mounted LED luminaire with a completely enclosed light source and the nearest clothes-storage space in a clothes closet?",opts:["12 inches (300 mm)","18 inches (450 mm)","24 inches (600 mm)","6 inches (150 mm)"],ans:0,ref:"NEC 410.16(D)(1)",exp:"The minimum clearance between luminaires installed in clothes closets and the nearest point of the clothes closet storage space is: 300 mm (12 in.) for surface-mounted incandescent or LED luminaires with a completely enclosed light source. Surface-mounted fluorescent and recessed luminaires (all types) require only 150 mm (6 in.) of clearance."},
  {id:228,mod:6,cat:"Equipment",diff:"Medium",q:"What is the minimum clearance required between a surface-mounted fluorescent luminaire and the clothes storage space in a clothes closet?",opts:["6 inches (150 mm)","12 inches (300 mm)","18 inches (450 mm)","24 inches (600 mm)"],ans:0,ref:"NEC 410.16(D)(2)",exp:"The minimum clearance for surface-mounted fluorescent luminaires in clothes closets is 150 mm (6 in.) from the nearest point of the clothes closet storage space. The same 6-inch clearance applies to recessed incandescent or LED luminaires (completely enclosed), recessed fluorescent luminaires, and surface-mounted LED luminaires not completely enclosed. Only surface-mounted incandescent or LED with completely enclosed sources require the larger 12-inch clearance."},
  {id:229,mod:6,cat:"Equipment",diff:"Medium",q:"For motors, the NEC requires that current values from the ampacity tables (Table 430.247/248/249/250) be used instead of the motor nameplate horsepower to determine conductor sizing and protective device ratings. What is the main exception to this rule?",opts:["When the motor is less than 1 HP","When the motor is marked in amperes rather than horsepower","When the motor nameplate FLC is higher than the table value","When the motor is used in a residential application"],ans:1,ref:"NEC 430.6(A)(1)",exp:"The values given in Table 430.247 through 430.250 shall be used to determine conductor ampacity, switch ratings, and OCP ratings — not the actual nameplate current. Where a motor is marked in amperes but not horsepower, the table value is used to interpolate the HP rating. The nameplate current rating is used only for separate motor overload protection sizing (430.6(A)(2))."},
  {id:230,mod:6,cat:"Equipment",diff:"Medium",q:"For a single-phase induction motor rated at 10 amperes FLC, what is the maximum rating of an inverse-time circuit breaker used for branch-circuit short-circuit and ground-fault protection?",opts:["115%","125%","175%","250%"],ans:3,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1), for a single-phase AC motor, the maximum rating of an inverse-time circuit breaker for branch-circuit SC/GF protection is 250% of the motor FLC. For a 10-ampere motor: 10 × 2.50 = 25 amperes. If 25A is not a standard size, the next lower standard size is required (or next higher if the motor won't start). Separate overload protection is still required at a much lower percentage."},
  {id:231,mod:6,cat:"Equipment",diff:"Medium",q:"For an air-conditioning hermetic refrigerant motor-compressor, the maximum rating of the branch-circuit short-circuit and ground-fault protective device shall not exceed what percentage of the rated-load current?",opts:["125%","150%","175%","225%"],ans:2,ref:"NEC 440.22(A)",exp:"The maximum rating or setting of the branch-circuit short-circuit and ground-fault protective device for a hermetic refrigerant motor-compressor shall not exceed 175% of the motor-compressor rated-load current (or branch-circuit selection current, whichever is greater). If 175% doesn't correspond to a standard device size, the next higher standard rating is permitted as long as it allows the equipment to start."},
  {id:232,mod:6,cat:"Equipment",diff:"Medium",q:"When a transformer with a primary current of 9 amperes or more has BOTH primary and secondary overcurrent protection, what is the maximum rating permitted for the primary overcurrent device?",opts:["125%","167%","250%","300%"],ans:2,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B), when both primary and secondary overcurrent protection are provided for a transformer with primary current ≥9 amperes, the primary overcurrent device may be rated up to 250% of the transformer's rated primary current. The higher 250% allowance is permitted because the secondary overcurrent device provides additional protection at a lower threshold."},
  {id:233,mod:6,cat:"Equipment",diff:"Medium",q:"Transformer ventilation openings must not be blocked by walls or other obstructions. Additionally, horizontal top surfaces that are readily accessible must be marked to do what?",opts:["Display the transformer serial number","Show the primary and secondary voltage ratings","Indicate the transformer kVA rating","Prohibit storage on the transformer top surface"],ans:3,ref:"NEC 450.9",exp:"Transformers with ventilating openings shall be installed so that the openings are not blocked by walls or other obstructions; required clearances shall be clearly marked on the transformer. Additionally, transformer top surfaces that are horizontal and readily accessible shall be marked to prohibit storage, preventing materials placed on top from blocking ventilation and causing overheating."},
  {id:234,mod:6,cat:"Equipment",diff:"Medium",q:"A transformer (other than a Class 2 or 3 transformer) must have a disconnecting means that is either in sight of the transformer or, if remote, must comply with what requirement?",opts:["It must be lockable open in accordance with 110.25, and its location must be field marked on the transformer","It must be no more than 50 feet from the transformer","It must be rated for the full transformer kVA","It must be a key-operated disconnect"],ans:0,ref:"NEC 450.14",exp:"Transformers, other than Class 2 or Class 3 transformers, shall have a disconnecting means either in sight of the transformer or in a remote location. Where located in a remote location, the disconnecting means shall be lockable open in accordance with 110.25, and its location shall be field marked on the transformer. This ensures safety for maintenance personnel."},
  {id:235,mod:6,cat:"Equipment",diff:"Medium",q:"A panelboard must have physical means to prevent the installation of more overcurrent devices than the number for which the panelboard was designed. For this purpose, how many overcurrent devices does a 2-pole circuit breaker count as?",opts:["2 overcurrent devices","3 overcurrent devices","4 overcurrent devices","1 overcurrent device"],ans:0,ref:"NEC 408.54",exp:"A panelboard shall be provided with physical means to prevent installation of more overcurrent devices than that number for which it was designed, rated, and listed. For this section, a 2-pole circuit breaker or fusible switch counts as 2 overcurrent devices; a 3-pole circuit breaker counts as 3 overcurrent devices. This prevents overcrowding that could create unsafe conditions."},
  {id:236,mod:6,cat:"Equipment",diff:"Medium",q:"A 20-ampere T-slot receptacle is installed on a branch circuit. Which plug configuration is permitted to be inserted into it?",opts:["Either 15-ampere or 20-ampere plugs of the same voltage rating","Any plug regardless of ampere rating","Only twist-lock style plugs of any ampere rating","Only 20-ampere plugs — no 15-ampere plugs allowed"],ans:0,ref:"NEC 406.8",exp:"Receptacles, cord connectors, and attachment plugs shall be constructed such that receptacles or cord connectors do not accept a plug with a different voltage or current rating. However, a 20-ampere T-slot receptacle or cord connector shall be permitted to accept a 15-ampere attachment plug of the same voltage rating. This allows backward compatibility with 15-ampere plugs in 20-ampere circuits."},
  {id:237,mod:6,cat:"Equipment",diff:"Medium",q:"An isolated equipment grounding conductor receptacle, intended to reduce electromagnetic noise, is identified by what marking on its face?",opts:["An orange triangle on the face","A green stripe on the yoke","An 'IG' label on the mounting yoke","A blue dot on the face"],ans:0,ref:"NEC 406.4(E)",exp:"Receptacles incorporating an isolated equipment grounding conductor connection (for reduction of electromagnetic interference per 250.146(D)) shall be identified by an orange triangle located on the face of the receptacle. These isolated ground receptacles shall only be used with EGCs that are isolated per 250.146(D) — they require a separate EGC run back to the service equipment."},
  {id:238,mod:6,cat:"Equipment",diff:"Medium",q:"A hand-operable circuit breaker equipped with a lever or handle may serve as a switch if it meets what condition?",opts:["It must be rated for more than 150% of the load current","It must have the required number of poles","It must be installed in a separate enclosure from the panelboard","It must have an SWD rating marked on its face"],ans:1,ref:"NEC 404.11",exp:"A hand-operable circuit breaker equipped with a lever or handle, or a power-operated circuit breaker capable of being opened by hand in the event of a power failure, shall be permitted to serve as a switch if it has the required number of poles. For example, a 2-pole breaker can serve as a switch for a 240V circuit, and a 3-pole breaker can serve as a switch for a 3-phase circuit."},
  {id:239,mod:6,cat:"Equipment",diff:"Medium",q:"Screwless push-in terminal receptacles may be used on branch circuits not greater than what ampere rating, and with what conductor requirement unless listed otherwise?",opts:["20-ampere circuits with 12 AWG solid copper only","15-ampere circuits with 14 AWG solid copper only","20-ampere circuits with 12 AWG stranded copper only","30-ampere circuits with 10 AWG aluminum only"],ans:1,ref:"NEC 406.4(C)(3)",exp:"Receptacles installed using screwless terminals of the conductor push-in type construction (push-in terminals) shall be installed on not greater than 15-ampere branch circuits and shall be connected with 14 AWG solid copper wire only, unless listed and marked for other types of conductors. Push-in terminals are not suitable for stranded conductors or larger conductors unless specifically listed."},
  {id:240,mod:6,cat:"Equipment",diff:"Hard",q:"Under the 2023 NEC, the prohibition on reconditioned luminaires in Art. 410.2 explicitly addresses retrofit kits. Under what specific condition is a retrofitted luminaire NOT considered reconditioned?",opts:["When the retrofit uses an LED driver with the same lumen output","When it is installed in a listed luminaire of any type","When a retrofit kit is installed in a luminaire in accordance with the kit's installation instructions","When the retrofit kit was manufactured by the same company as the luminaire"],ans:2,ref:"NEC 410.2",exp:"Per 410.2, reconditioned luminaires, lampholders, ballasts, LED drivers, lamps, and retrofit kits shall not be permitted. However, if a retrofit kit is installed in a luminaire in accordance with the installation instructions, the retrofitted luminaire shall not be considered reconditioned. This allows legitimate LED retrofit upgrades to existing luminaires when done per the manufacturer's instructions."},
  {id:241,mod:6,cat:"Equipment",diff:"Hard",q:"The 2023 NEC requires a grounded conductor at lighting switch locations but provides several exceptions. Which exception allows omitting the neutral if the switch controls automatic lighting?",opts:["Exception (1) — raceway large enough to include the grounded conductor","Exception (2) — snap switches with integral enclosures per 300.15(E)","Exception (3) — lighting in the area is controlled by automatic means","Exception (4) — switch controls a receptacle load rather than a lighting load"],ans:2,ref:"NEC 404.2(C)",exp:"A grounded conductor is NOT required at lighting switch locations under any of the following conditions: (1) conductors enter through a raceway sized to accommodate an additional conductor; (2) snap switches with integral enclosures comply with 300.15(E); (3) lighting in the area is controlled by automatic means; (4) the switch controls a receptacle load rather than a luminaire. Exception (3) acknowledges that occupancy sensors and timers eliminate the need for a manual neutral at those points."},
  {id:242,mod:6,cat:"Equipment",diff:"Hard",q:"For motor branch-circuit short-circuit and ground-fault protection using a dual-element (time-delay) fuse, the maximum rating per Table 430.52(C)(1) is what percentage of the motor full-load current?",opts:["175%","250%","125%","150%"],ans:0,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1): for a single-phase or polyphase AC induction motor, the maximum ratings for branch-circuit SC/GF protection are: non-time delay fuse = 300%, dual-element (time-delay) fuse = 175%, instantaneous-trip CB = 800% (1100% for Design B energy-efficient), and inverse-time CB = 250%. Dual-element fuses are preferred because their time-delay characteristic accommodates motor starting current while still providing short-circuit protection."},
  {id:243,mod:6,cat:"Equipment",diff:"Hard",q:"For a wye-start, delta-run motor, the conductors between the motor controller and the motor must have an ampacity of at least what percentage of motor FLC?",opts:["58 percent","72 percent","100 percent","125 percent"],ans:1,ref:"NEC 430.22(C)",exp:"For a wye-start, delta-run connected motor: the ampacity of branch-circuit conductors on the line side of the controller shall not be less than 125% of motor FLC. However, the conductors between the controller and the motor shall not be less than 72% of motor FLC. The 72% factor accounts for the wye-connected winding during starting, where each winding carries only 1/√3 (approximately 58%) of the line current — the code requires 72% for the conductors inside the motor terminal box."},
  {id:244,mod:6,cat:"Equipment",diff:"Hard",q:"A 3-phase transformer bank has a primary current of 8 amperes per phase. Using only primary overcurrent protection (no secondary OCP), what is the maximum primary overcurrent device rating under Table 450.3(B)?",opts:["100% (8 amperes)","125% (10 amperes)","167% (13.36 amperes)","250% (20 amperes)"],ans:2,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B), when primary current is less than 9 amperes (8A here) and only primary protection is used, the maximum rating is 167% of the transformer's rated primary current. For 8 amperes: 8 × 1.67 = 13.36 amperes. The next standard OCP size not exceeding 13.36 amperes would be selected. For primary currents ≥9 amperes with primary only protection, the limit is 125%."},
  {id:245,mod:6,cat:"Equipment",diff:"Hard",q:"The circuit directory requirement for panelboards specifies that descriptions must NOT be dependent on what condition?",opts:["The circuit breaker ampere rating","Transient conditions of occupancy","The wire gauge used in the circuit","The color of the insulation on the conductors"],ans:1,ref:"NEC 408.4(A)(5)",exp:"Circuit descriptions in panelboards must comply with 408.4(A)(1)-(6), including: (5) Not dependent on transient conditions of occupancy. This means a label such as 'current tenant bedroom' is unacceptable — it must clearly identify the circuit regardless of who occupies the space. Descriptions like 'north bedroom' or 'master bedroom south wall outlets' are appropriate permanent descriptions."},
  {id:246,mod:6,cat:"Equipment",diff:"Hard",q:"An air-conditioning system has a hermetic refrigerant motor-compressor with a rated-load current of 20 amperes and a branch-circuit selection current of 24 amperes. What is the maximum branch-circuit OCP device rating?",opts:["35 amperes (175% of 20A)","42 amperes (175% of 24A)","50 amperes (250% of 20A)","60 amperes (250% of 24A)"],ans:1,ref:"NEC 440.22(A)",exp:"The maximum OCP for an A/C hermetic compressor is 175% of the motor-compressor rated-load current OR the branch-circuit selection current, whichever is greater. Here, the branch-circuit selection current (24A) is greater than rated-load current (20A), so: 24 × 1.75 = 42 amperes. The next standard size not exceeding 42 amperes (which would be 40A) may be used, or the next higher standard size if needed to allow starting."},
  {id:247,mod:6,cat:"Equipment",diff:"Hard",q:"A dry-type transformer installed in a building with combustible construction cannot exceed what total kVA capacity in one location without being installed in a transformer vault?",opts:["10 kVA","25 kVA","50 kVA","75 kVA"],ans:0,ref:"NEC 450.21(A)",exp:"Per 450.21(A) and its exceptions: dry-type transformers in buildings with combustible construction shall not exceed 10 kVA in a section classified as combustible. The NEC allows up to 75 kVA where the surrounding structure is fire-resistant construction. Electric furnace transformers not exceeding 75 kVA may be installed without a vault in fire-resistant construction with suitable fire protection arrangements."},
  {id:248,mod:6,cat:"Equipment",diff:"Hard",q:"The NEC requires that the grounded conductor be connected via a pigtail at receptacle outlets in multiwire branch circuits to prevent what hazard?",opts:["Overvoltage caused by neutral conductor interruption","Shared EGC becoming a current-carrying conductor","Conductor insulation failure at the device terminals","Ground fault at the receptacle outlet"],ans:0,ref:"NEC 300.13(B)",exp:"In multiwire branch circuits, the continuity of the grounded conductor shall not depend on device connections. If the neutral were wired straight through the receptacle's neutral terminal (without a pigtail), removing the receptacle would break the neutral for the remaining loads on that circuit, causing the circuit to open under normal load conditions and potentially creating overvoltage on the other ungrounded conductors sharing the same neutral."},
  {id:249,mod:6,cat:"Equipment",diff:"Hard",q:"The 2023 NEC added a new requirement for replacement panelboards installed in existing enclosures. If the replacement panelboard is NOT listed for the specific existing enclosure and the available fault current exceeds what level, the completed work must be field labeled?",opts:["10,000 amperes","22,000 amperes","42,000 amperes","5,000 amperes"],ans:0,ref:"NEC 408.9(B)",exp:"A new 2023 NEC provision: replacement panelboards not listed for the specific existing enclosure require field labeling when the available fault current exceeds 10,000 amperes. Where the available fault current is 10,000 amperes or less, a field label is not required. This addresses safety concerns about short-circuit current ratings when replacement panelboards are installed in enclosures not specifically listed for them."},
  {id:250,mod:6,cat:"Equipment",diff:"Hard",q:"For a non-time delay fuse used for motor branch-circuit short-circuit and ground-fault protection per Table 430.52(C)(1), what is the maximum permitted percentage of motor full-load current?",opts:["300%","800%","175%","250%"],ans:0,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1): for a non-time delay fuse (standard cartridge fuse), the maximum rating is 300% of motor full-load current. The higher 300% value (vs. 175% for dual-element fuses) is necessary because standard fuses have no time delay and would blow during the high inrush current of motor starting. Dual-element time-delay fuses allow closer protection at 175%, and inverse-time circuit breakers allow up to 250%."},
  {id:251,mod:6,cat:"Equipment",diff:"Hard",q:"A surface-mounted LED luminaire without a completely enclosed light source is installed in a clothes closet. What minimum clearance from the storage space is required?",opts:["6 inches (150 mm)","12 inches (300 mm)","18 inches (450 mm)","24 inches (600 mm)"],ans:0,ref:"NEC 410.16(D)",exp:"The 12-inch clearance requirement applies only to surface-mounted incandescent or LED luminaires with a completely enclosed light source. An LED luminaire without a completely enclosed source falls into the category requiring the smaller clearance: 150 mm (6 in.) as required for recessed fluorescent, recessed incandescent/LED, and surface-mounted fluorescent. The key distinction is whether the light source is completely enclosed, which affects the proximity of any heat or potential ignition source to stored clothing."},
  {id:252,mod:6,cat:"Equipment",diff:"Hard",q:"Under the 2023 NEC, the new Art. 408.9 allows replacement panelboards in existing enclosures. If a replacement panelboard IS listed for the specific enclosure, what benefit does this provide?",opts:["The installer is exempt from all labeling requirements","The panelboard is permitted to maintain its short-circuit current rating","The installer may use any overcurrent device regardless of panelboard rating","The available fault current does not need to be calculated"],ans:1,ref:"NEC 408.9(A)",exp:"Per 408.9(A): if the replacement panelboard is listed for the specific enclosure (identified by catalog number or dimensional information), the panelboard shall be permitted to maintain its short-circuit current rating. This is the key advantage — a listed panelboard-enclosure combination retains its tested and rated short-circuit current rating without needing a field label or separate fault-current analysis."},
// MODULE 7: SPECIAL OCCUPANCIES (30)
  {id:253,mod:7,cat:"Special Occupancies",diff:"Easy",q:"Class I hazardous locations are defined by the presence of which type of hazardous material?",opts:["Flammable gases, flammable liquid-produced vapors, or combustible liquid-produced vapors","Ignitable fibers or flyings that could be present","Radioactive materials requiring special shielding","Combustible dusts in quantities sufficient to produce explosive mixtures"],ans:0,ref:"NEC 500.5(B)",exp:"Class I locations are those in which flammable gases, flammable liquid-produced vapors, or combustible liquid-produced vapors are or may be present in the air in quantities sufficient to produce explosive or ignitable mixtures. Class II locations involve combustible dusts, and Class III locations involve ignitable fibers/flyings."},
  {id:254,mod:7,cat:"Special Occupancies",diff:"Easy",q:"Class I, Group A material is which specific gas — considered most dangerous due to extreme explosion characteristics?",opts:["Hydrogen","Propane","Acetylene","Ethylene"],ans:2,ref:"NEC 500.6(A)(1)",exp:"Class I, Group A is acetylene. Acetylene is classified in the most hazardous group because of its extremely wide flammable range and its tendency to decompose explosively under certain conditions. Its unique explosion characteristics require the most stringent equipment design standards of all the Class I groups."},
  {id:255,mod:7,cat:"Special Occupancies",diff:"Easy",q:"In a Class I, Division 1 location, which two raceway systems are the primary permitted wiring methods?",opts:["Liquidtight flexible metal conduit and EMT","Threaded rigid metal conduit (RMC) or threaded intermediate metal conduit (IMC)","PVC conduit and HDPE conduit","Type MC cable and Type AC cable"],ans:1,ref:"NEC 501.10(A)(1)",exp:"In Class I, Division 1 locations, the primary permitted wiring methods are threaded rigid metal conduit (RMC) or threaded intermediate metal conduit (IMC), including conduit systems with supplemental corrosion protection coatings. These conduit systems must use threaded fittings, made wrench-tight to prevent sparking from fault current and to maintain explosionproof integrity."},
  {id:256,mod:7,cat:"Special Occupancies",diff:"Easy",q:"Ground-fault circuit-interrupter protection for personnel is required for all 125-volt, 15-, 20-, and 30-ampere receptacles during which type of operations?",opts:["On all circuits at all times as a new 2023 NEC requirement","Only in commercial and industrial occupancies","Only when receptacles are installed outdoors in the rain","During construction, remodeling, maintenance, repair, or demolition activities only"],ans:3,ref:"NEC 590.6(A)",exp:"GFCI protection for personnel is required for all temporary wiring installations used to supply temporary power to equipment used by personnel during construction, remodeling, maintenance, repair, or demolition of buildings, structures, or equipment. All 125-volt, single-phase, 15-, 20-, and 30-ampere receptacle outlets not part of permanent wiring that are in use by personnel must have GFCI protection."},
  {id:257,mod:7,cat:"Special Occupancies",diff:"Easy",q:"In a temporary wiring installation, all lamps used for general illumination must be protected from accidental contact or breakage by what means?",opts:["By a suitable luminaire or lampholder with a guard","By wrapping with polyethylene tape","By installing them inside metal conduit","Only by installing them above 8 ft from the floor"],ans:0,ref:"NEC 590.6(F)",exp:"All lamps for general illumination in temporary installations shall be protected from accidental contact or breakage by a suitable luminaire or lampholder with a guard. Metal guarded sockets shall not be used unless the metal guard is connected to the circuit equipment grounding conductor. This protects workers from burns and prevents fires from broken lamps igniting combustible materials on construction sites."},
  {id:258,mod:7,cat:"Special Occupancies",diff:"Easy",q:"Class III locations involve which type of hazardous material, and how are they further grouped?",opts:["Combustible dusts, further grouped as E, F, and G","Flammable gases, further grouped as A, B, C, and D","Ignitable fibers or flyings, and they are NOT further grouped","Explosive chemicals, grouped by flash point temperature"],ans:2,ref:"NEC 500.5(D), 500.6(D)",exp:"Class III locations are those that are hazardous because of the presence of easily ignitable fibers or flyings. Unlike Class I and Class II materials, Class III ignitible fibers/flyings are not further grouped. Examples include cotton linters, rayon, hemp, jute, sisal, wood shavings, and other textile fibers or similar combustible material."},
  {id:259,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Which Class I group represents gases and vapors with a maximum experimental safe gap (MESG) greater than 0.75 mm, and a typical representative material of propane?",opts:["Group A","Group B","Group C","Group D"],ans:3,ref:"NEC 500.6(A)(4)",exp:"Class I, Group D includes flammable gases or vapors with a maximum experimental safe gap (MESG) greater than 0.75 mm or a minimum igniting current (MIC) ratio greater than 0.80. A typical Class I, Group D material is propane. Other Group D materials include methane (natural gas), gasoline vapors, and acetone."},
  {id:260,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Class I, Group B materials are characterized by a maximum experimental safe gap (MESG) of 0.45 mm or less, or a MIC ratio of 0.40 or less. What is the typical Group B gas?",opts:["Hydrogen","Ethylene","Propane","Acetylene"],ans:0,ref:"NEC 500.6(A)(2)",exp:"Class I, Group B includes flammable gases or vapors with a MESG value less than or equal to 0.45 mm or a MIC ratio less than or equal to 0.40. The typical Class I, Group B material is hydrogen. Group B also includes flammable liquid-produced vapors such as butadiene and ethylene oxide. Note: Group A (acetylene) is more restrictive than Group B."},
  {id:261,mod:7,cat:"Special Occupancies",diff:"Medium",q:"A Class I, Division 1 location is defined as one where ignitable concentrations of flammable gases or vapors can exist under which conditions?",opts:["Under normal operating conditions, or frequently due to repair/maintenance, or where breakdown could simultaneously release gas and fail electrical equipment","Only when containers are being filled or transferred","When the space has inadequate ventilation during winter months only","Only during abnormal operations such as equipment breakdown or accidental leakage"],ans:0,ref:"NEC 500.5(B)(1)",exp:"A Class I, Division 1 location exists where: (1) ignitable concentrations can exist under normal operating conditions, or (2) ignitable concentrations might frequently exist because of repair or maintenance operations or leakage, or (3) equipment breakdown might release ignitable concentrations AND simultaneously cause the electrical equipment to become an ignition source. The key is that Division 1 involves normal or frequent conditions."},
  {id:262,mod:7,cat:"Special Occupancies",diff:"Medium",q:"A Class I, Division 2 location differs from Division 1 primarily because ignitable concentrations are present only under which circumstances?",opts:["Only under abnormal conditions — accidental rupture, breakdown, or unusual operating conditions","When atmospheric pressure drops below standard conditions","Under normal operating conditions daily","Only during equipment startup procedures"],ans:0,ref:"NEC 500.5(B)(2)",exp:"A Class I, Division 2 location is one where: (1) volatile flammable liquids or gases are handled, processed, or used but are normally confined within closed containers or systems and are released only in case of accidental rupture or breakdown; (2) ignitable concentrations are normally prevented by positive mechanical ventilation and might become hazardous only through failure of ventilation systems; or (3) the area is adjacent to a Class I, Division 1 location. The key distinction: Division 2 = abnormal conditions only."},
  {id:263,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Class II locations involve combustible dusts. Which group includes metal dusts such as aluminum and magnesium?",opts:["Group E","Group F","Group G","Group H"],ans:0,ref:"NEC 500.6(B)(1)",exp:"Class II, Group E includes atmospheres containing combustible metal dusts, including aluminum, magnesium, and their commercial alloys, or other combustible dusts with particle size, abrasiveness, and conductivity that present similar hazards. Group E is the most hazardous of the Class II groups. Group F includes carbonaceous dusts (coal, carbon black), and Group G includes flour, grain, wood, plastic, and chemical dusts."},
  {id:264,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Class II, Group G combustible dust locations include atmospheres containing which types of dusts?",opts:["Flour, grain, wood, plastic, and chemical dusts","Metallic salts and semiconductor materials","Aluminum and magnesium metal dust","Carbonaceous dusts such as coal and carbon black"],ans:0,ref:"NEC 500.6(B)(3)",exp:"Class II, Group G includes atmospheres containing combustible dusts not included in Groups E or F, such as flour, grain, wood, plastic, and chemicals. Group E covers metal dusts (aluminum, magnesium). Group F covers carbonaceous dusts (coal, carbon black, charcoal, coke). Group G is the least hazardous of the Class II groups and is the most common in agricultural and food processing environments."},
  {id:265,mod:7,cat:"Special Occupancies",diff:"Medium",q:"In a commercial garage, the space within an unventilated pit or subfloor work area is classified as what?",opts:["Unclassified if the garage only does minor repairs","Class I, Division 1 (or Zone 1) for the entire space within the pit","Class I, Division 2 up to 18 inches above the floor only","Class II, Group G due to oil and grease accumulation"],ans:1,ref:"NEC 511.3(C)",exp:"In commercial garages (both major and minor repair), the entire space within any pit, below-grade work area, or subfloor work area that is NOT ventilated is classified as Class I, Division 1 (or Zone 1, Group IIA). Unventilated pits are Div 1 because heavier-than-air fuel vapors accumulate at the lowest points. Ventilated pits with ≥0.3 m³/min/m² suction from within 12 in of floor level are Div 2."},
  {id:266,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Category 1 spaces in health care facilities (the highest patient care level, such as operating rooms) must be served by which type of essential electrical system?",opts:["A Type 2 Essential Electrical System","A Type 1 Essential Electrical System only","Any essential electrical system with 10-second transfer time","A standby generator with automatic transfer switch only"],ans:1,ref:"NEC 517.30(B)(1)",exp:"Category 1 spaces (such as operating rooms, intensive care units, and similar critical care areas) shall be served by a Type 1 Essential Electrical System (EES). Category 1 spaces shall not be served by a Type 2 EES. Type 1 EES must have two or more independent power sources, with one on-site source sized to supply the entire EES."},
  {id:267,mod:7,cat:"Special Occupancies",diff:"Medium",q:"In temporary wiring installations, a multiwire branch circuit must be provided with a means to disconnect how many conductors at the panelboard or power outlet?",opts:["Only the grounded conductor","Only the ungrounded conductors one at a time","Simultaneously all ungrounded conductors","All conductors including the EGC simultaneously"],ans:2,ref:"NEC 590.6(E)",exp:"Multiwire branch circuits in temporary wiring installations shall be provided with a means to disconnect simultaneously all ungrounded conductors at the power outlet or panelboard where the branch circuit originated. Identified handle ties shall be permitted for this purpose. This prevents the hazard of having one energized ungrounded conductor remaining in a multiwire circuit when the other has been de-energized."},
  {id:268,mod:7,cat:"Special Occupancies",diff:"Medium",q:"In a temporary wiring installation, when is a box, conduit body, or enclosure with a cover required for splices?",opts:["For all splices, with limited exceptions on construction sites for cord assemblies and metal-sheathed cable in listed fittings","Only when the circuit voltage exceeds 120 volts","Only when the splice contains more than 3 conductors","Never — temporary wiring splices are exempt from box requirements"],ans:0,ref:"NEC 590.6(G)",exp:"A box, conduit body, or other enclosure with a cover shall be required for all splices in temporary wiring. Two exceptions apply on construction sites: (1) all conductors being spliced are from nonmetallic multiconductor cord/cable assemblies (EGC continuity maintained), or (2) all conductors being spliced are from metal-sheathed cable assemblies in listed fittings that mechanically secure the cable sheath for electrical continuity."},
  {id:269,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Motor fuel dispensing facilities are required to follow which primary code document for supplementary requirements, referenced in the NEC?",opts:["NFPA 1, Fire Code","NFPA 30A, Code for Motor Fuel Dispensing Facilities and Repair Garages","NFPA 72, National Fire Alarm Code","NFPA 13, Standard for the Installation of Sprinkler Systems"],ans:1,ref:"NEC 514.1 Informational Note",exp:"The NEC references NFPA 30A-2021, Code for Motor Fuel Dispensing Facilities and Repair Garages, for information regarding safeguards for motor fuel dispensing facilities. The classified location extents around dispensers and underground tanks are defined in NFPA 30A and incorporated into NEC Table 514.3(B)(1) and Figure 514.3. Motor fuel dispensing facilities (gas stations) must comply with NEC Article 514 and NFPA 30A."},
  {id:270,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Fixed stage switchboards in theaters must be listed and must contain what for all branch circuits supplied by that switchboard?",opts:["Only a main circuit breaker for the entire switchboard","Overcurrent protective devices for all branch circuits","Ground-fault circuit-interrupter protection for all circuits","Arc-fault protection on all circuits supplying dimmers"],ans:1,ref:"NEC 520.21(1)(3)",exp:"Fixed stage switchboards shall be: (1) listed; (2) readily accessible but not required to be located on or adjacent to the stage; (3) contain overcurrent protective devices for all branch circuits supplied by that switchboard; (4) permitted to supply both stage and nonstage equipment. The OCP requirement in each switchboard ensures protection for all stage circuits, including lighting dimmer circuits."},
  {id:271,mod:7,cat:"Special Occupancies",diff:"Medium",q:"Trees and other vegetation shall NOT be used to support overhead spans of branch-circuit conductors or cables in temporary wiring installations. What limited exception applies?",opts:["Trees may be used in all temporary residential holiday lighting situations","Trees may be used for holiday lighting where conductors have strain relief or tension take-up devices to avoid damage from vegetation movement","Trees are always permitted for spans less than 15 feet","Trees may be used if the circuit is GFCI-protected"],ans:1,ref:"NEC 590.4(J)",exp:"Per 590.4(J): vegetation shall not be used for support of overhead spans of branch circuits or feeders. Exception: For holiday lighting per 590.3(B), where the conductors or cables are arranged with strain relief devices, tension take-up devices, or other approved means to avoid damage from the movement of live vegetation, trees shall be permitted to be used for support of overhead spans."},
  {id:272,mod:7,cat:"Special Occupancies",diff:"Medium",q:"A refrigerant machinery room using ammonia refrigeration may be classified as 'unclassified' if it has adequate mechanical ventilation operating continuously or triggered at what maximum concentration?",opts:["50 ppm ammonia","100 ppm ammonia","150 ppm ammonia","300 ppm ammonia"],ans:2,ref:"NEC 500.5(A)(2)",exp:"Refrigerant machinery rooms containing ammonia refrigeration systems and equipped with adequate mechanical ventilation that operates continuously or is initiated by a detection system at a concentration not exceeding 150 ppm shall be permitted to be classified as 'unclassified' locations. This 2023 NEC provision was added to acknowledge modern detection and ventilation systems that effectively prevent hazardous accumulations."},
  {id:273,mod:7,cat:"Special Occupancies",diff:"Hard",q:"In Class I, Division 1 locations, PVC conduit, RTRC conduit, or HDPE conduit is permitted under what specific condition?",opts:["Where the conduit is sealed with listed sealing fittings at both ends","Where encased in a concrete envelope a minimum of 50 mm (2 in.) thick","Where installed inside metal armor for mechanical protection","Where the circuit voltage does not exceed 120 volts"],ans:1,ref:"NEC 501.10(A)(1)(2)",exp:"In Class I, Division 1 locations, PVC conduit, RTRC conduit, or HDPE conduit is permitted where encased in a concrete envelope a minimum of 50 mm (2 in.) thick. The concrete encasement provides the structural integrity and containment properties necessary for Division 1 locations when these nonmetallic conduits cannot provide the explosionproof integrity of threaded RMC or IMC on their own."},
  {id:274,mod:7,cat:"Special Occupancies",diff:"Hard",q:"Threaded NPT conduit entries into explosionproof equipment must have at least how many threads fully engaged? What is the exception for listed explosionproof equipment with factory-threaded NPT entries?",opts:["3 threads; exception allows 2.5 threads for factory entries","5 threads fully engaged; exception allows at least 4.5 threads for listed factory-threaded NPT entries","8 threads fully engaged; no exception applies","6 threads; exception permits 5 threads for listed equipment"],ans:1,ref:"NEC 500.8(E)(1)",exp:"NPT-threaded entries into explosionproof equipment shall be made up with at least five threads fully engaged. Exception: For listed explosionproof equipment, joints with factory-threaded NPT entries shall be made up with at least four and one-half threads fully engaged. The thread engagement requirement ensures the threaded joint maintains the explosionproof integrity needed to contain an internal explosion without propagating it to the surrounding hazardous atmosphere."},
  {id:275,mod:7,cat:"Special Occupancies",diff:"Hard",q:"Class I, Group C includes gases with a MESG greater than 0.45 mm but not more than 0.75 mm. Which gas is the typical representative of Group C?",opts:["Propane","Acetylene","Hydrogen","Ethylene"],ans:3,ref:"NEC 500.6(A)(3)",exp:"Class I, Group C includes flammable gases or vapors with a MESG value greater than 0.45 mm and less than or equal to 0.75 mm, or a MIC ratio greater than 0.40 and less than or equal to 0.80. The typical Class I, Group C material is ethylene. Other Group C materials include cyclopropane, diethyl ether, and ethylene. The MESG and MIC ratio determine how easily a spark or flame can propagate through a flameproof joint."},
  {id:276,mod:7,cat:"Special Occupancies",diff:"Hard",q:"In Class II, Division 2 locations, which wiring method is permitted that is NOT permitted in Class II, Division 1 locations for the same application?",opts:["Type MC cable with listed terminations","Threaded RMC or IMC","Electrical metallic tubing (EMT) with listed compression-type connectors or couplings","PVC conduit encased in concrete"],ans:2,ref:"NEC 502.10(B)(1)(3)",exp:"In Class II, Division 2 locations, dusttight wireways or electrical metallic tubing (EMT) with listed compression-type connectors or couplings are permitted. EMT with compression fittings provides the dusttight seal needed to exclude dust from enclosures in Division 2. In Class II, Division 1 locations, the more stringent dust-ignitionproof requirements generally exclude EMT, which is permitted only in Division 2 where ignitable concentrations are not expected during normal operations."},
  {id:277,mod:7,cat:"Special Occupancies",diff:"Hard",q:"In health care facilities, isolated power systems are permitted for use in Category 1 spaces. If an isolated power system is used, the system equipment must be listed as what?",opts:["Listed for use in wet locations per 406.9","Listed isolated power equipment; the isolated power system must comply with 517.160","Listed for patient care vicinities per NFPA 99","Listed industrial control equipment per UL 508"],ans:1,ref:"NEC 517.30(F)",exp:"Isolated power systems shall be permitted to be used for Category 1 spaces. If used, the isolated power system equipment shall be listed as isolated power equipment, and the isolated power system shall be designed and installed in accordance with 517.160. Isolated power systems limit the magnitude of first-fault current, which is especially important in environments where patients may be in direct electrical contact with medical equipment and unable to withdraw from contact."},
  {id:278,mod:7,cat:"Special Occupancies",diff:"Hard",q:"In a major repair garage where Class I liquids or gaseous fuels are transferred or dispensed, the entire floor area of the room is classified as Class I Division 2 up to what height above the floor?",opts:["6 inches (150 mm)","12 inches (300 mm)","18 inches (450 mm)","36 inches (915 mm)"],ans:2,ref:"NEC 511.3(C), Table 511.3(C)",exp:"In major repair garages where Class I liquids or gaseous fuels are transferred or dispensed, the area up to 450 mm (18 in.) above the floor level of the room is classified as Class I, Division 2 (or Zone 2) for the entire floor area, except as noted. Heavier-than-air fuel vapors (such as gasoline) accumulate at floor level, making the 18-inch zone particularly hazardous. Where the room has ventilation of at least 0.3 m³/min/m² with suction from within 12 in. of floor level, this same extent is the Division 2 zone."},
  {id:279,mod:7,cat:"Special Occupancies",diff:"Hard",q:"The essential electrical system for a health care facility requires two or more independent sources of power. What specific requirement applies to the on-site power source?",opts:["The on-site source must be capable of starting within 60 seconds","The on-site source (or sets of sources) must be sized to supply the entire essential electrical system","The on-site source must use natural gas as its primary fuel","The on-site source must be located in a separate building from the main service"],ans:1,ref:"NEC 517.30(A)",exp:"Essential electrical systems shall have two or more independent sources (or sets of sources). One on-site source (or sets of sources) shall be sized to supply the entire EES. The other independent source can be the utility. Having an on-site source (typically a generator) sized for the entire EES ensures that critical life-safety and critical systems remain operational even when utility power fails, which is essential for patient care continuity in Category 1 spaces."},
  {id:280,mod:7,cat:"Special Occupancies",diff:"Hard",q:"When receptacles that are part of the permanent wiring of a building are used for temporary electric power during construction, what GFCI requirement applies?",opts:["The GFCI protection may be waived if the circuit is protected by an AFCI breaker","Only GFCI protection is required if the permanent receptacle is within 6 feet of a sink","No GFCI is required since the permanent wiring already complies with the code at the time of installation","GFCI protection for personnel shall be provided, using listed cord sets or devices incorporating listed GFCI protection for portable use"],ans:3,ref:"NEC 590.6(A)(2)",exp:"Ground-fault circuit-interrupter protection for personnel shall be provided for all 125-volt, single-phase, 15-, 20-, and 30-ampere receptacle outlets installed or existing as part of the permanent wiring of the building or structure when used for temporary electric power. Listed cord sets or devices incorporating listed GFCI protection for personnel identified for portable use shall be permitted. Simply because a permanent receptacle already exists does not exempt it from the GFCI requirement during construction use."},
  {id:281,mod:7,cat:"Special Occupancies",diff:"Hard",q:"In a commercial garage, what specific ventilation rate must a pit have before its classification can be downgraded from Class I, Division 1 to Class I, Division 2?",opts:["At least 0.3 m³/min/m² (1 ft³/min/ft²) of floor area with suction taken from within 300 mm (12 in.) of floor level","At least 4 complete air changes per hour regardless of intake location","Positive pressure ventilation at 0.5 in. water column above atmospheric pressure","Any mechanical ventilation with exhaust from the ceiling"],ans:0,ref:"NEC 511.3(C), Table 511.3(C)",exp:"A pit in a commercial garage is Class I, Division 2 (not Division 1) only when provided with ventilation of at least 0.3 m³/min/m² (1 ft³/min/ft²) of floor area, with suction taken from a point within 300 mm (12 in.) of floor level. The suction point near floor level is critical because fuel vapors are heavier than air and accumulate at the lowest point. Without this specific ventilation meeting this rate and inlet location, the pit remains Class I, Division 1."},
  {id:282,mod:7,cat:"Special Occupancies",diff:"Hard",q:"The GFCI requirement for construction site receptacles contains an exception for industrial establishments. What alternative program may be used instead of GFCI, and under what conditions?",opts:["Anti-corrosion program if the site is in a coastal environment","Assured equipment grounding conductor (AEGCP) program, only where conditions of maintenance and supervision ensure qualified personnel are involved, and only for equipment that would create greater hazard if power were interrupted","Arc-fault circuit-interrupter (AFCI) protection in lieu of GFCI for heavy industrial equipment","No alternative is permitted — GFCI is mandatory without exception on all construction sites"],ans:1,ref:"NEC 590.6(A) Exception",exp:"In industrial establishments only, where conditions of maintenance and supervision ensure that only qualified personnel are involved, an assured equipment grounding conductor program (AEGCP) as specified in 590.6(B)(2) shall be permitted as an alternative to GFCI, but only for those receptacle outlets used to supply equipment that: (1) would create a greater hazard if power were interrupted (e.g., life safety equipment), or (2) has a design not compatible with GFCI protection. The AEGCP requires daily testing and documentation."},
// MODULE 8: MOTORS & TRANSFORMERS (40)
  {id:283,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"What minimum ampacity is required for branch-circuit conductors supplying a single continuous-duty AC motor?",opts:["100% of motor full-load current","115% of motor full-load current","125% of motor full-load current","150% of motor full-load current"],ans:2,ref:"NEC 430.22",exp:"The ampacity of conductors supplying a single motor used in a continuous-duty application shall not be less than 125% of the motor's full-load current rating, as determined by 430.6(A)(1). This 25% margin above FLC is required because motors are treated as continuous loads and the conductor must safely carry the current without excessive temperature rise during normal operation."},
  {id:284,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"When sizing conductors and selecting protective devices for a motor (other than certain special cases), which current values must be used instead of the actual motor nameplate horsepower?",opts:["The values from Tables 430.247, 430.248, 430.249, and 430.250 based on motor horsepower","The locked-rotor current from the motor nameplate","The motor nameplate current divided by 1.25 for a correction factor","The motor nameplate full-load current in all cases"],ans:0,ref:"NEC 430.6(A)(1)",exp:"The values from Table 430.247 (DC motors), Table 430.248 (single-phase AC), Table 430.249 (2-phase AC), and Table 430.250 (3-phase AC) shall be used to determine conductor ampacity, switch current ratings, and branch-circuit SC/GF protective device ratings — not the actual HP or current marked on the nameplate. The exception applies when the motor nameplate current is used for separate overload protection sizing (430.6(A)(2))."},
  {id:285,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"A motor controller (other than an inverse-time circuit breaker or molded-case switch) must have a horsepower rating that is at least what relative to the motor it controls?",opts:["50% of the motor's horsepower rating","Equal to or greater than the horsepower rating of the motor at the application voltage","Twice the motor's horsepower rating","Equal to the locked-rotor horsepower of the motor"],ans:1,ref:"NEC 430.83(A)(1)",exp:"Motor controllers, other than inverse-time circuit breakers and molded-case switches, shall have horsepower ratings at the application voltage not lower than the horsepower rating of the motor. This ensures the controller is rated for the motor's mechanical demands. An exception applies for small motors and for stationary motors of 2 HP or less under certain conditions."},
  {id:286,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"The disconnecting means for a motor must indicate its status in what way?",opts:["By a color-coded indicator light on the controller","Plainly indicate whether it is in the open (off) or closed (on) position","By an audible alarm when opened","By a digital display showing current flow"],ans:1,ref:"NEC 430.104",exp:"The disconnecting means for a motor shall plainly indicate whether it is in the open (off) or closed (on) position. This requirement allows personnel to visually confirm the open/closed status of the disconnect without needing to test the circuit. This is critical for lockout/tagout safety procedures during motor maintenance."},
  {id:287,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"For a transformer with a primary current of 9 amperes or more at 1000 volts or less, where only primary overcurrent protection is provided, the maximum primary OCP rating is what percentage of the transformer-rated primary current?",opts:["100%","115%","125%","150%"],ans:2,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B), for transformers 1000V or less with primary current ≥9 amperes and only primary overcurrent protection, the maximum OCP rating is 125% of the transformer's rated primary current. Where 125% doesn't correspond to a standard fuse or nonadjustable breaker size, the next higher standard rating is permitted per 240.6."},
  {id:288,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"For a hermetic refrigerant motor-compressor, the branch-circuit short-circuit and ground-fault protective device rating must not exceed what percentage of the rated-load current?",opts:["125%","150%","175%","250%"],ans:2,ref:"NEC 440.22(A)",exp:"The branch-circuit SC/GF protective device for an A/C hermetic refrigerant motor-compressor shall not exceed 175% of the motor-compressor rated-load current, or the branch-circuit selection current, whichever is greater. If 175% doesn't match a standard device size, the next higher standard rating is permitted. If still insufficient for starting current, see the 225% exception."},
  {id:289,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"A transformer (other than Class 2 or 3) must have a disconnecting means either in sight of the transformer, or if remotely located, what two requirements must that remote disconnect meet?",opts:["It must be 3-phase rated and within 100 feet of the transformer","It must be lockable open per 110.25, and its location must be field marked on the transformer","It must be a circuit breaker rated for 125% of the transformer primary current","It must be accessible without tools and clearly labeled with voltage rating"],ans:1,ref:"NEC 450.14",exp:"Transformers, other than Class 2 or Class 3 transformers, shall have a disconnecting means either in sight of the transformer or in a remote location. Where remote, the disconnect must be: (1) lockable open in accordance with 110.25, and (2) its location shall be field marked on the transformer. This ensures maintenance personnel can safely de-energize the transformer and verify the disconnect location."},
  {id:290,mod:8,cat:"Motors & Transformers",diff:"Easy",q:"Motor nameplate current values (as opposed to table values) must be used when sizing what type of motor protection?",opts:["Branch-circuit short-circuit and ground-fault protection","Separate motor overload protection","Motor feeder overcurrent protection","Motor control circuit overcurrent protection"],ans:1,ref:"NEC 430.6(A)(2)",exp:"Motor nameplate current ratings shall be used to determine values for separate motor overload protection (430.6(A)(2)), not the Table 430.247-250 values. The table values are used for conductor sizing, switch ratings, and branch-circuit SC/GF protection. Using the actual nameplate current for overload protection provides the most accurate protection specifically tailored to the individual motor's thermal characteristics."},
  {id:291,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For motor branch-circuit short-circuit and ground-fault protection, what is the maximum rating of an inverse-time circuit breaker expressed as a percentage of motor full-load current?",opts:["125%","175%","200%","250%"],ans:3,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1), for a single-phase or polyphase AC induction motor, the maximum rating of an inverse-time circuit breaker for branch-circuit SC/GF protection is 250% of motor FLC. Comparison: non-time delay fuse = 300%, dual-element (time-delay) fuse = 175%, instantaneous-trip CB = 800% (or 1100% for Design B energy-efficient motors)."},
  {id:292,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For motor branch-circuit short-circuit and ground-fault protection using a dual-element (time-delay) fuse, the maximum rating is what percentage of motor full-load current?",opts:["125%","150%","175%","250%"],ans:2,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1), for a dual-element (time-delay) fuse, the maximum rating for motor branch-circuit SC/GF protection is 175% of motor FLC. The time-delay feature allows the fuse to ride through motor starting inrush current while still providing short-circuit protection. This makes dual-element fuses a preferred choice for motor circuits due to their closer thermal protection compared to the 300% non-time delay fuse or 250% inverse-time CB limits."},
  {id:293,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For motor branch-circuit short-circuit and ground-fault protection, a standard (non-time delay) fuse may be rated up to what maximum percentage of motor full-load current?",opts:["175%","200%","250%","300%"],ans:3,ref:"NEC 430.52(C)(1), Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1), for a non-time delay fuse (standard one-time or Class CC fuse), the maximum rating for motor branch-circuit SC/GF protection is 300% of motor FLC. Standard fuses have no time delay, so the higher 300% limit is needed to accommodate motor starting inrush without nuisance blowing. However, this means the fuse provides less precise protection, which is why dual-element time-delay fuses (175%) are preferred."},
  {id:294,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"An inverse-time circuit breaker rated in amperes is permitted to serve as a motor controller for which motors?",opts:["Only motors rated at ½ HP or less","Only motors in residential applications","All motors, without any horsepower restriction","Only motors rated at 2 HP or less"],ans:2,ref:"NEC 430.83(A)(2)",exp:"A branch-circuit inverse time circuit breaker rated in amperes shall be permitted as a motor controller for ALL motors. Where this circuit breaker is also used for overload protection, it shall conform to the appropriate provisions governing overload protection. An inverse-time CB has operating characteristics similar to motor starting curves and can therefore serve as both controller and overcurrent protection."},
  {id:295,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"The disconnecting means for a motor must be capable of interrupting what current level to ensure safe disconnection?",opts:["The full-load current of the motor only","The running current at maximum load","The locked-rotor current of the motor","The starting inrush current only during the first 3 seconds"],ans:2,ref:"NEC 430.110",exp:"The motor disconnecting means shall be capable of interrupting the locked-rotor current of the motor. Locked-rotor current is the maximum current drawn when the motor is energized but the shaft is not rotating — this can be 6 to 7 times the full-load current. The disconnect must be able to safely interrupt this high current to prevent arcing and fire hazards during emergency disconnection."},
  {id:296,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"The disconnecting means for a motor must generally be located in sight of the motor controller. What is the definition of 'within sight' in the NEC?",opts:["Within 100 feet if the disconnect is visible","Within the same electrical enclosure","Within the same room, regardless of distance","Within 50 feet and visible from the controller or motor"],ans:3,ref:"NEC 430.102, Art. 100 Definition",exp:"'Within sight' means visible and not more than 15 m (50 ft) distant from the object referred to. The disconnecting means for a motor must be located within sight of the controller and within sight of the motor (or the disconnecting means must be lockable in the open position). This ensures the person working on the equipment can visually confirm the disconnect is open from where they are working."},
  {id:297,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For a wye-start, delta-run motor, the conductors between the controller and the motor must have an ampacity of at least what percentage of motor full-load current?",opts:["58%","72%","100%","125%"],ans:1,ref:"NEC 430.22(C)",exp:"For wye-start, delta-run motors: the line-side conductors shall have ampacity ≥125% of motor FLC. The conductors between the controller and the motor shall have ampacity ≥72% of motor FLC. The 72% factor accounts for the wye-delta winding configuration where individual motor branch conductors carry approximately 58% of line current (1/√3). The 58% × 1.25 = 72% to account for the continuous duty factor."},
  {id:298,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"The ampacity of conductors for an A/C hermetic refrigerant motor-compressor shall not be less than what percentage of the motor-compressor rated-load current (or branch-circuit selection current, whichever is greater)?",opts:["100%","115%","125%","175%"],ans:2,ref:"NEC 440.32",exp:"Conductors supplying a single hermetic refrigerant motor-compressor shall have an ampacity of not less than 125% of either the motor-compressor rated-load current or the branch-circuit selection current, whichever is greater. This mirrors the 430.22 requirement for conventional motors. If the equipment has a branch-circuit selection current marked on the nameplate, that value is used when it is greater than the rated-load current."},
  {id:299,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"If the 175% maximum A/C compressor branch-circuit OCP does not correspond to a standard device size and still isn't sufficient for motor starting, what is the maximum the protective device may be increased to?",opts:["200% of rated-load current","225% of rated-load current","250% of rated-load current","300% of rated-load current"],ans:1,ref:"NEC 440.22 Exception No. 2",exp:"Per 440.22 Exception No. 2: if the 175% value (or the next higher standard size per Exception No. 1) is still not sufficient for starting current of the motor, the protective device may be increased but shall not exceed 225% of the motor-compressor rated-load current or branch-circuit selection current, whichever is greater. The 225% absolute ceiling prevents excessive overcurrent protection that would fail to protect the branch-circuit conductors."},
  {id:300,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"When both primary and secondary overcurrent protection are provided for a transformer with primary current of 9 amperes or more, the primary overcurrent device may be rated up to what percentage?",opts:["250%","300%","125%","167%"],ans:0,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B): when both primary and secondary OCP are provided for a transformer with primary current ≥9 amperes, the primary OCP device may be rated up to 250% of the transformer's rated primary current. The secondary OCP (for ≥9A secondary current) remains limited to 125%. The higher 250% primary limit is permitted because the secondary OCP provides the primary protection for short-circuits in the secondary winding and conductors."},
  {id:301,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"An autotransformer rated 1000 volts or less must have overcurrent protection in series with each ungrounded input conductor. What is the maximum rating of this OCP device relative to the autotransformer rated full-load input current?",opts:["100%","110%","115%","125%"],ans:3,ref:"NEC 450.4(A)",exp:"Each autotransformer 1000 volts or less shall be protected by an individual overcurrent device installed in series with each ungrounded input conductor, rated or set at not more than 125% of the rated full-load input current of the autotransformer. Where 125% doesn't correspond to a standard size and the rated input current is ≥9 amperes, the next higher standard rating per 240.6 is permitted. The OCP shall not be installed in series with the shunt winding."},
  {id:302,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For a motor with a service factor of 1.15 or marked with a temperature rise not over 40°C, the maximum setting for separate overload protection is what percentage of the motor's full-load current?",opts:["125%","140%","100%","115%"],ans:0,ref:"NEC 430.32(A)(1)",exp:"For a motor with a service factor of not less than 1.15 or with a temperature rise not over 40°C, the separate overload protection shall be selected to trip or shall be rated at no more than 125% of the motor's full-load current rating. For motors that do not meet either of those criteria, the 115% limit applies. The service factor and temperature rise indicate the motor can handle sustained loads above nameplate rating, hence the higher 125% allowance."},
  {id:303,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For a standard motor with a service factor less than 1.15 and a temperature rise exceeding 40°C, what is the maximum permitted setting for separate overload protection?",opts:["115%","125%","100%","110%"],ans:0,ref:"NEC 430.32(A)(1)",exp:"For motors with service factor less than 1.15 or temperature rise exceeding 40°C, the separate overload protection shall be selected to trip or be rated at no more than 115% of the motor's full-load current rating. These motors have less thermal margin than the higher-rated motors, so a tighter (115%) overload protection limit is required to prevent premature winding damage from sustained overloads."},
  {id:304,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"Transformer ventilation openings must not be blocked. Additionally, transformer top surfaces that are readily accessible and horizontal must be marked to do what?",opts:["Display the kVA rating","Prohibit storage on the top surface","Indicate the direction of cooling airflow","Show the primary and secondary conductor sizes"],ans:1,ref:"NEC 450.9",exp:"Transformers with ventilating openings shall be installed so ventilating openings are not blocked by walls or other obstructions; required clearances must be clearly marked on the transformer. Transformer top surfaces that are horizontal and readily accessible shall be marked to prohibit storage. Materials placed on top of transformers can block ventilation and cause dangerous overheating."},
  {id:305,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"The secondary overcurrent protection requirement for a transformer with secondary current ≥9A (when required) limits the maximum OCP to what percentage of the transformer's rated secondary current?",opts:["100%","115%","125%","167%"],ans:2,ref:"NEC 450.3(B), Table 450.3(B)",exp:"Per Table 450.3(B): when secondary overcurrent protection is required (or used to allow higher primary OCP), the secondary OCP for secondary currents of 9 amperes or more is limited to 125% of the transformer's rated secondary current. For secondary currents less than 9 amperes, the limit is 167%. These limits ensure the secondary conductors and equipment are protected from overcurrent conditions."},
  {id:306,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"Motor controllers and control circuit device terminals shall be connected with what type of conductors?",opts:["Copper conductors unless identified for use with a different conductor","Either copper or aluminum as appropriate for the circuit load","Copper-clad aluminum only for controllers rated above 100 amperes","Aluminum conductors unless otherwise marked"],ans:0,ref:"NEC 430.9(B)",exp:"Motor controllers and terminals of control circuit devices shall be connected with copper conductors unless identified for use with a different conductor. This is more restrictive than the general conductor rules because motor controllers involve frequent switching and may experience higher fault currents — copper connections provide more reliable contact at these points."},
  {id:307,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For a motor feeder supplying multiple motors, the feeder overcurrent protective device rating shall not exceed what value?",opts:["125% of the largest motor's FLC","The largest branch-circuit SC/GF device rating plus the sum of FLC of all other motors on the feeder","250% of the total connected motor load FLC","The rating of the largest motor's branch-circuit device only"],ans:1,ref:"NEC 430.62(A)",exp:"A feeder protective device for motor loads shall have a rating or setting not greater than the largest rating or setting of the branch-circuit SC/GF protective device for any motor supplied (based on maximum permitted per 430.52), plus the sum of the full-load currents of the other motors of the group. This ensures the feeder device provides backup protection while allowing each motor's branch-circuit device to operate first for branch faults."},
  {id:308,mod:8,cat:"Motors & Transformers",diff:"Medium",q:"For a multispeed motor, which full-load current value is used to select conductors on the line side of the controller?",opts:["The average of all speed ratings","The lowest FLC shown on the motor nameplate","The FLC for the speed being operated at any given time","The highest full-load current rating shown on the motor nameplate"],ans:3,ref:"NEC 430.22(B)",exp:"For a multispeed motor, the selection of branch-circuit conductors on the line side of the controller shall be based on the highest of the full-load current ratings shown on the motor nameplate. This ensures the line-side conductors can safely carry the maximum current the motor could demand at any speed setting. Conductors between the controller and each individual motor winding may be sized to 125% of that winding's FLC."},
  {id:309,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"For Design B energy-efficient motors, the maximum instantaneous-trip circuit breaker setting for branch-circuit SC/GF protection is what percentage of motor full-load current?",opts:["1100%","1300%","800%","1000%"],ans:0,ref:"NEC Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1): for Design B energy-efficient and Design B premium efficiency motors, the maximum instantaneous-trip circuit breaker setting is 1100% of motor FLC. Standard induction motors allow 800%. The higher setting for Design B motors is needed because their improved power factor and efficiency result in a lower apparent impedance during starting, causing higher starting current that could trip a standard instantaneous-trip CB set at 800%."},
  {id:310,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"For a wound-rotor induction motor, what percentage applies to ALL types of motor branch-circuit SC/GF protective devices in Table 430.52(C)(1)?",opts:["175%","250%","100%","150%"],ans:3,ref:"NEC Table 430.52(C)(1)",exp:"Per Table 430.52(C)(1): for wound-rotor (slip-ring) motors, ALL protective device types — non-time delay fuse, dual-element fuse, instantaneous-trip CB, and inverse-time CB — are limited to 150% of motor FLC. Wound-rotor motors have an external resistance in the rotor circuit that limits starting current to much lower values than squirrel-cage motors, so the lower 150% protection works for all device types."},
  {id:311,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"A transformer with coordinated thermal overload protection by the manufacturer, where the overload device interrupts primary current, may have primary OCP set at not more than how many times the rated primary current for a transformer with ≤6% impedance?",opts:["3 times","4 times","5 times","6 times"],ans:3,ref:"NEC 450.3(B), Table 450.3(B), Note 3",exp:"Per Table 450.3(B) Note 3: a transformer with coordinated thermal overload protection arranged to interrupt primary current may have primary OCP rated or set at a current value not more than six times the rated current for transformers with not more than 6% impedance, or not more than four times the rated current for transformers with more than 6% but not more than 10% impedance. The manufacturer's thermal protector effectively provides the close overcurrent protection normally provided by the primary OCP."},
  {id:312,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"Where secondary overcurrent protection for a transformer is required, it may consist of not more than how many circuit breakers or sets of fuses grouped in one location?",opts:["6 circuit breakers or 6 fuse sets","10 circuit breakers or 10 fuse sets","2 circuit breakers or 2 fuse sets","4 circuit breakers or 4 fuse sets"],ans:0,ref:"NEC 450.3(B), Table 450.3(B), Note 2",exp:"Per Table 450.3(B) Note 2: where secondary overcurrent protection is required, the secondary overcurrent device shall be permitted to consist of not more than six circuit breakers or six sets of fuses grouped in one location. Where multiple overcurrent devices are utilized, the total of all the device ratings shall not exceed the allowed value of a single overcurrent device. This permits multiple loads to be individually protected from the secondary while still meeting the transformer's OCP requirement."},
  {id:313,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"The 72% conductor ampacity rule for wye-start, delta-run motor conductors (between controller and motor) is derived from what calculation?",opts:["58% × 1.25 = 72%, where 58% (1/√3) is the winding current ratio and 1.25 accounts for continuous duty","65% × 1.1 = 72%, where 65% is the standard derating for three-conductor cables","72% directly from Table 430.250 for wye-connected motors","80% × 0.9 = 72%, where 0.9 is the power factor correction factor"],ans:0,ref:"NEC 440.32 Informational Note",exp:"The 72% factor is obtained by multiplying 58% by 1.25. The 58% value (1/√3 ≈ 0.577) is the ratio of individual motor circuit conductor current to line current in a wye-connected winding. The 1.25 factor is the standard multiplier for continuous-duty conductors (analogous to the 125% rule for motor conductors generally). Thus: 58% × 1.25 = 72.5%, rounded to 72%."},
  {id:314,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"For a motor installed as part of a group drive or multiple-motor installation, under what condition may a single disconnecting means serve more than one motor?",opts:["When all motors are rated at 2 HP or less","When served from a single branch circuit rated at 30 amperes or less","Where the installation is in a single motor control center","Under the conditions in 430.112(A)–(D), including where the entire group is within sight and conditions ensure qualified supervision"],ans:3,ref:"NEC 430.112",exp:"A single disconnecting means may serve more than one motor where the conditions of 430.112(A) through (D) are met. These include: the installation is in a single room not accessible to unqualified persons; the equipment is within sight; the motors are part of a single machine; or the disconnecting means is lockable in the open position. The single disconnect must be capable of disconnecting all motors it serves."},
  {id:315,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"A motor controller for a stationary motor rated 2 HP or less at 300 volts or less may use which simplified control device?",opts:["Only a horsepower-rated motor controller","A general-use switch with an ampere rating of at least twice the motor full-load current, for motors 1/8 HP or less","An inverse-time CB and a plug fuse","A snap switch as a controller if its ampere rating is not less than twice the full-load current of the motor"],ans:3,ref:"NEC 430.83(C)(1)",exp:"For stationary motors rated at 2 HP or less at 300 volts or less, a general-use snap switch is permitted as the motor controller if its ampere rating is not less than twice the full-load current rating of the motor. This exception simplifies the control of small motors in residential and light commercial applications, where a dedicated HP-rated controller would be impractical."},
  {id:316,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"For a 3-wire, 3-phase AC motor circuit with one conductor grounded, where fuses are used for motor overload protection, how many fuses must be installed?",opts:["One fuse in the ungrounded conductor only","Two fuses — one in each of the ungrounded conductors","Three fuses — one in each conductor including the grounded conductor","Two fuses in ungrounded conductors and one in the grounded conductor"],ans:2,ref:"NEC 430.36",exp:"Where fuses are used for motor overload protection, a fuse shall be inserted in each ungrounded conductor and also in the grounded conductor if the supply system is 3-wire, 3-phase AC with one conductor grounded. This means three fuses total — in each of the two ungrounded conductors AND in the grounded conductor. The fuse in the grounded conductor prevents a situation where the grounded phase has a fault that goes unprotected."},
  {id:317,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"A motor controller enclosure shall NOT be used as a junction box for conductors feeding through or tapping to other apparatus unless what condition is satisfied?",opts:["The enclosure is in a dry location only","The enclosure is rated for the available fault current","Designs are employed that provide adequate space for the purpose","The conductor fill does not exceed 25% of cross-sectional area"],ans:2,ref:"NEC 430.10(A)",exp:"Enclosures for motor controllers and disconnecting means shall not be used as junction boxes, auxiliary gutters, or raceways for conductors feeding through or tapping off to other apparatus unless designs are employed that provide adequate space for this purpose. See also 312.8 for specific fill percentages applicable to such wiring space within enclosures for switches or overcurrent devices used this way."},
  {id:318,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"An A/C hermetic refrigerant motor-compressor on its nameplate shows both a rated-load current (RLC) of 18A and a branch-circuit selection current (BCSC) of 22A. What ampacity must the branch-circuit conductors have?",opts:["18 A × 1.25 = 22.5 A minimum","22 A × 1.25 = 27.5 A minimum","18 A + 22 A = 40 A minimum","The larger of 18 A or 22 A with no additional multiplier required"],ans:1,ref:"NEC 440.32",exp:"Conductors for hermetic compressors must have ampacity ≥125% of the larger of the rated-load current or the branch-circuit selection current. Here, BCSC (22A) > RLC (18A), so: 22 × 1.25 = 27.5 amperes minimum. The BCSC is used when it is marked on the equipment and is greater than the RLC, because the equipment has a built-in protection system that allows continuous current exceeding the RLC."},
  {id:319,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"A motor disconnecting means for a motor over ½ HP must have an ampere rating of at least what percentage of the motor's full-load current to meet the disconnecting means rating requirement?",opts:["100%","115%","125%","150%"],ans:1,ref:"NEC 430.110(A)",exp:"The ampere rating of the motor branch-circuit disconnecting means shall not be less than 115% of the full-load current rating of the motor. This applies to motors over ½ HP. The 115% rating (versus the 125% for conductor sizing) accounts for the fact that the disconnect must safely carry and interrupt the motor's operational current, including some overload margin, while the motor is running."},
  {id:320,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"A transformer with coordinated thermal overload protection that interrupts primary current — and impedance greater than 6% but not more than 10% — may have primary OCP set at not more than how many times rated primary current?",opts:["2 times","3 times","4 times","6 times"],ans:2,ref:"NEC 450.3(B), Table 450.3(B), Note 3",exp:"Per Table 450.3(B) Note 3: a manufacturer-provided coordinated thermal overload protector that interrupts primary current permits the primary OCP to be rated at not more than six times the rated current for transformers with not more than 6% impedance, or not more than FOUR times the rated current for transformers with more than 6% but not more than 10% impedance. Higher impedance transformers have greater natural current-limiting ability, allowing slightly higher OCP with the thermal overload providing the fine protection."},
  {id:321,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"Hermetic refrigerant motor-compressor conductors between the controller and the motor in a wye-start, delta-run configuration may be based on what percentage of the larger of rated-load current or branch-circuit selection current?",opts:["58%","72%","100%","125%"],ans:1,ref:"NEC 440.32",exp:"For wye-start, delta-run connected motor-compressors, the conductors between the controller and the motor-compressor shall be permitted to be based on 72% of either the motor-compressor rated-load current or the branch-circuit selection current, whichever is greater. This 72% factor (derived from 58% × 1.25) applies the same logic as 430.22(C) for conventional wye-start, delta-run motors to A/C hermetic compressors."},
  {id:322,mod:8,cat:"Motors & Transformers",diff:"Hard",q:"When a motor overload protection device trips, and the motor has an automatic restart capability, what specific 2023 NEC requirement applies to prevent unsafe automatic restarts after a locked-rotor condition?",opts:["No automatic restart is permitted under any circumstances","Listed means must sense motor rotation and prevent shunting of overload protection if the motor fails to start; the overload shunt time must be less than the locked-rotor time rating","A 15-second time delay must be provided before any automatic restart attempt","The motor must be de-energized for at least 5 minutes before automatic restart is permitted"],ans:1,ref:"NEC 430.32 Exception",exp:"Motor overload protection may be shunted or cut out during the starting period on an automatically started motor only if: (1) the starting period exceeds the time delay of available OLP devices, and (2) listed means are provided to: (a) sense motor rotation and prevent the shunting if the motor fails to start; (b) limit the time of overload shunting to less than the locked-rotor time rating of the protected motor; and (c) provide for shutdown and manual restart if the motor running condition is not reached. This prevents catastrophic motor burnout from extended locked-rotor events."},
// MODULE 9: COMMUNICATIONS & EMERGENCY (25)
{id:323,mod:9,cat:"Communications & Emergency",diff:"Easy",q:"What is required of automatic transfer switches (ATSs) for emergency systems?",opts:["Must be manually operated","Must be electrically operated and mechanically held","Must be fused separately","Must be located in the main electrical room"],ans:1,ref:"NEC 700.5(C)",exp:"Per 700.5(C): automatic transfer switches shall be electrically operated and mechanically held. Electrically operated means they actuate on loss of normal power; mechanically held means they stay in position without continuous power."},
{id:324,mod:9,cat:"Communications & Emergency",diff:"Easy",q:"What is the primary purpose of transfer equipment in an emergency system?",opts:["Prevent the inadvertent interconnection of normal and emergency sources","Monitor the load on the emergency circuit","Supply optional standby loads first","Reduce generator startup time"],ans:0,ref:"NEC 700.5(A)",exp:"700.5(A): Transfer equipment shall be designed and installed to prevent the inadvertent interconnection of normal and emergency sources of supply in any operation of the transfer equipment. Prevents backfeed that could endanger utility workers."},
{id:325,mod:9,cat:"Communications & Emergency",diff:"Easy",q:"What color identification is required on the fire alarm circuit branch-circuit overcurrent protective device?",opts:["Green","Orange","Red","Yellow"],ans:2,ref:"NEC 760.41(B)",exp:"760.41(B): The circuit disconnecting means shall have red identification, shall be accessible only to qualified personnel, and shall be identified as 'FIRE ALARM CIRCUIT.' The red identification shall not damage the overcurrent protective devices or obscure the manufacturer's markings."},
{id:326,mod:9,cat:"Communications & Emergency",diff:"Easy",q:"Class 2 and Class 3 circuit cables shall not be placed in the same raceway with power conductors. What basic condition in 725.136(B) allows them to share a space?",opts:["Class 2 cables are insulated for 600V so sharing is always allowed","They are separated by a barrier","Class 2 circuits are limited power so no separation is needed","A licensed electrician approves the installation"],ans:1,ref:"NEC 725.136(B)",exp:"725.136(A) prohibits sharing; 725.136(B) permits Class 2 and Class 3 circuits to be installed together with power conductors where they are separated by a barrier. The physical separation prevents damage to low-voltage insulation from higher-voltage conductors."},
{id:327,mod:9,cat:"Communications & Emergency",diff:"Easy",q:"Which types of systems are permitted as stored-energy power supply systems (SEPSS) for emergency use under Article 700?",opts:["Only diesel generators","UPS, fuel cell system, energy storage system (ESS), storage battery, or other approved equivalent","Solar panels and wind generators only","Only utility-grade battery banks"],ans:1,ref:"NEC 700.12(E)(1)",exp:"700.12(E)(1) lists permitted SEPSS types: (1) uninterruptible power supply (UPS); (2) fuel cell system; (3) energy storage system (ESS); (4) storage battery; (5) other approved equivalent stored energy sources that comply with 700.12."},
{id:328,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"What type of transfer switch is specifically NOT permitted for emergency system use?",opts:["Bypass isolation transfer switches","Automatic transfer switches","Meter-mounted transfer switches","Manual transfer switches for small loads under 15A"],ans:2,ref:"NEC 700.5(A)",exp:"700.5(A) explicitly states: 'Meter-mounted transfer switches shall not be permitted for emergency system use.' This applies regardless of load size. ATSs and bypass isolation switches are permitted with proper requirements."},
{id:329,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"For emergency system feeder-circuit wiring in assembly occupancies with 1,000 or more persons, which is an acceptable protection method for the feeder cable or raceway?",opts:["Installed in spaces fully protected by an approved automatic fire protection system","Installed with 6-inch concrete cover","Standard NM cable is acceptable","Standard EMT conduit is sufficient"],ans:0,ref:"NEC 700.10(D)(2)(1)",exp:"700.10(D)(2) lists five options: (1) in spaces fully protected by approved automatic fire protection system; (2) listed electrical circuit protective system with 2-hour fire rating; (3) listed fire-resistive cable with 2-hour rating; (4) listed fire-rated assembly 2-hour rating, emergency circuits only; (5) encased in minimum 2 in. of concrete."},
{id:330,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"The fire alarm branch circuit supplying the fire alarm equipment shall supply _____ other loads.",opts:["No","Up to two","No more than three","Any number of"],ans:0,ref:"NEC 760.41(B)",exp:"760.41(B): 'The branch circuit supplying the fire alarm equipment(s) shall supply no other loads.' This dedicated circuit requirement ensures fire alarm operation is not compromised by faults or load changes on other circuits sharing the same branch circuit."},
{id:331,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"The fire alarm branch circuit shall NOT be supplied through which two types of protective devices?",opts:["Fuses or circuit breakers","Ground-fault circuit interrupters (GFCI) or arc-fault circuit interrupters (AFCI)","Surge-protective devices or voltage regulators","Main disconnects or transfer switches"],ans:1,ref:"NEC 760.41(B)",exp:"760.41(B): 'This branch circuit shall not be supplied through ground-fault circuit-interrupters or arc-fault circuit-interrupters.' GFCI/AFCI may nuisance-trip on characteristics of fire alarm systems, which could disable life-safety equipment at a critical time."},
{id:332,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"What is the maximum overcurrent protection for 18 AWG NPLFA (non-power-limited fire alarm) conductors?",opts:["15 amperes","10 amperes","7 amperes","20 amperes"],ans:2,ref:"NEC 760.43",exp:"760.43: Overcurrent protection shall not exceed 7 amperes for 18 AWG conductors and 10 amperes for 16 AWG conductors. For 14 AWG and larger, protection is based on conductor ampacity without applying ampacity adjustment and correction factors of 310.14."},
{id:333,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"Non-power-limited fire alarm cables installed in other spaces used for environmental air (plenums) shall be which cable type?",opts:["NPLF (general purpose)","NPLFR (riser)","NPLFP (plenum)","Any listed fire alarm cable in conduit is acceptable"],ans:2,ref:"NEC 760.53(B)(2)",exp:"760.53(B)(2): Cables installed in other spaces used for environmental air shall be Type NPLFP. The 'P' suffix indicates plenum-rated cable with adequate fire-resistant and low-smoke-producing characteristics. Non-plenum cable in plenum spaces can spread fire and toxic smoke through the air handling system."},
{id:334,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"What are the two classifications of fire alarm circuits under Article 760?",opts:["Class A and Class B circuits","Class 1 and Class 2 circuits","Power-limited fire alarm (PLFA) and non-power-limited fire alarm (NPLFA)","Emergency and non-emergency circuits"],ans:2,ref:"NEC 760.35",exp:"760.35: Fire alarm circuits are classified as NPLFA (Non-Power-Limited Fire Alarm) covered in Part II, or PLFA (Power-Limited Fire Alarm) covered in Part III. Classification determines permissible wiring methods, cable types, overcurrent protection requirements, and separation requirements."},
{id:335,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"Where an emergency alternate source also supplies legally required standby and optional standby loads, in what order must loads be picked up when using selective load management?",opts:["All loads simultaneously regardless of type","Legally required standby first since it is mandated by law","Optional standby first, then legally required, then emergency","Emergency circuits first, legally required standby second, optional standby third"],ans:3,ref:"NEC 700.4(B)",exp:"700.4(B): Where load management is provided, the alternate source picks up: (1) emergency circuits first, (2) legally required standby circuits second, (3) optional standby circuits third. Emergency systems always have the highest priority because they protect life safety."},
{id:336,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"Emergency system wiring in buildings over 23 m (75 ft) in height must comply with which additional feeder-circuit wiring requirements?",opts:["Standard wiring methods — no additional requirements for high-rise buildings","700.10(D)(2) through (D)(4) requiring fire-rated protection or equivalent","Only THWN conductors are permitted above 75 ft","All wiring must be in dedicated electrical rooms"],ans:1,ref:"NEC 700.10(D)(1)(2)",exp:"700.10(D)(1) applies additional feeder-circuit requirements to: assembly occupancies with not less than 1,000 persons; buildings above 23 m (75 ft) in height; and educational occupancies with more than 300 occupants. Feeder circuits in these locations must meet the fire protection requirements of 700.10(D)(2) through (D)(4)."},
{id:337,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"How must fire alarm circuits be identified at terminal and junction locations?",opts:["Blue color coding on all conductors","Identified in a manner that helps prevent unintentional signals during testing and servicing of other systems","Circuit breaker labeling only — no field marking required","Red conduit required for all fire alarm raceways"],ans:1,ref:"NEC 760.30",exp:"760.30: Fire alarm circuits shall be identified at terminal and junction locations in a manner that helps prevent unintentional signals on fire alarm system circuit(s) during testing and servicing of other systems. This identification prevents accidental activation of the fire alarm when workers are testing or servicing adjacent systems."},
{id:338,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"What is the scope of Article 701 (Legally Required Standby Systems)?",opts:["Life-safety systems required by the NEC for occupant evacuation","Systems required by law to supply required facilities for illumination or power when normal supply is interrupted","Optional systems for comfort and business continuity","Identical to emergency systems under Article 700"],ans:1,ref:"NEC 701.1",exp:"701.1: Article 701 applies to legally required standby systems that supply required facilities for illumination or power when normal supply is interrupted. These are mandated by law (other codes) but are less immediately life-critical than Article 700 emergency systems. Examples include refrigeration, heating, and communications required by local codes."},
{id:339,mod:9,cat:"Communications & Emergency",diff:"Medium",q:"Class 2 and Class 3 circuit conductors in enclosures shall be permitted to be installed with power conductors introduced solely to connect Class 2/3 equipment where what condition is met?",opts:["The conductors are in a listed low-voltage conduit","Power conductors maintain minimum 6 mm (0.25 in.) separation from Class 2/3 conductors, or the Class 2/3 conductors are in a raceway","The enclosure is listed for mixed-voltage circuits","All conductors in the enclosure are rated 600V minimum"],ans:1,ref:"NEC 725.136(D)(1)",exp:"725.136(D): In enclosures, Class 2 and Class 3 conductors are permitted with power conductors introduced solely to connect Class 2/3 equipment where: (1) power conductors maintain minimum 6 mm (0.25 in.) separation from Class 2/3 conductors, or (2) the Class 2/3 conductors are installed in a raceway within the enclosure per 725.136(C)."},
{id:340,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"Emergency system feeder-circuit wiring may be protected by a listed electrical circuit protective system. What is the minimum fire rating required for this system?",opts:["30 minutes","1 hour","2 hours","4 hours"],ans:2,ref:"NEC 700.10(D)(2)(2)",exp:"700.10(D)(2)(2): The cable or raceway shall be protected by a listed electrical circuit protective system with a minimum 2-hour fire rating. Similarly, 700.10(D)(2)(3) requires a listed fire-resistive cable system with a minimum 2-hour fire rating. The 2-hour rating ensures emergency circuits survive a fire long enough to permit safe evacuation."},
{id:341,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"When an emergency system is supplied by a single feeder, what must be provided to allow maintenance without interrupting emergency power?",opts:["Redundant transfer equipment or a bypass isolation transfer switch","A second utility service entrance","An uninterruptible power supply to bridge any interruption","A manual bypass switch is sufficient if a qualified person monitors it at all times"],ans:0,ref:"NEC 700.5(D)",exp:"700.5(D): If emergency loads are supplied by a single feeder, the emergency power system shall include redundant transfer equipment or a bypass isolation transfer switch to facilitate maintenance without jeopardizing continuity of power. If the redundant equipment is manual/nonautomatic, it shall be actively supervised by a qualified person when the primary automatic equipment is disabled."},
{id:342,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"Circuit integrity (CI) cables for fire alarm systems installed in free air must be supported at intervals not exceeding _____, and where located within 7 ft of the floor, shall be fastened at intervals not exceeding _____.",opts:["24 in. / 18 in.","36 in. / 24 in.","18 in. / 12 in.","48 in. / 24 in."],ans:0,ref:"NEC 760.24(B)",exp:"760.24(B): CI cables shall be supported at a distance not exceeding 610 mm (24 in.). Where located within 21 m (7 ft) of the floor, the cable shall be fastened at intervals not more than 450 mm (18 in.). Cable supports and fasteners shall be steel. Close spacing maintains circuit integrity under fire conditions. CI cables shall only be installed in free air unless specifically listed for raceway."},
{id:343,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"Emergency system overcurrent protective devices (OCPDs) must be selectively coordinated. Who must select the selective coordination and what documentation is required?",opts:["The AHJ selects coordination; manufacturer documents it","The equipment manufacturer determines coordination","Any licensed electrician; no documentation required","A licensed professional engineer or qualified persons engaged primarily in design, installation, or maintenance of electrical systems; selection shall be documented"],ans:3,ref:"NEC 700.32(A)",exp:"700.32(A): Emergency system OCPDs shall be selectively coordinated with all supply-side and load-side OCPDs. Selection shall be made by a licensed professional engineer or other qualified persons engaged primarily in the design, installation, or maintenance of electrical systems. The selection shall be documented and made available to those authorized to design, install, inspect, maintain, and operate the system."},
{id:344,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"When an emergency source operates in parallel with the normal source, what condition must be maintained at all times?",opts:["Emergency source runs at 50% capacity only during parallel operation","The capacity required to supply the emergency load must be maintained at all times","Emergency source supplies only lighting loads during parallel operation","Utility notification required before any parallel operation"],ans:1,ref:"NEC 700.4(C)(1)",exp:"700.4(C)(1): Emergency sources may operate in parallel with the normal source per Article 705 where the capacity required to supply the emergency load is maintained at all times. Any operating condition resulting in less than the required emergency source capacity shall initiate a system malfunction signal in accordance with 700.6(A)."},
{id:345,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"When an on-site emergency source is connected to a microgrid system and normal electric supply is interrupted, what must occur?",opts:["The emergency source must disconnect from the microgrid entirely","Emergency source output is automatically limited to its rated capacity","The microgrid may supply all loads without restriction","The system shall isolate the emergency system from all nonemergency loads, or meet the load management requirements of 700.4(B)"],ans:3,ref:"NEC 700.12(G)",exp:"700.12(G): On-site sources designated as emergency sources may connect to a microgrid system. When normal supply is interrupted, the system shall isolate the emergency system from all nonemergency loads — or shall meet the requirements of 700.4(B) selective load management. Ensures emergency capacity is not consumed by nonemergency loads during an outage."},
{id:346,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"NPLFA cables used in vertical runs penetrating one or more floors shall be which cable type?",opts:["NPLFR (riser)","Any listed fire alarm cable is acceptable for riser applications","NPLF (general purpose)","NPLFP (plenum)"],ans:0,ref:"NEC 760.53(B)(3)",exp:"760.53(B)(3): Cables installed in vertical runs penetrating one or more floors, or in vertical runs in a shaft, shall be Type NPLFR (riser). Floor penetrations requiring NPLFR shall contain only cables suitable for riser or plenum use. The 'R' suffix indicates fire-resistant characteristics that prevent the carrying of fire from floor to floor."},
{id:347,mod:9,cat:"Communications & Emergency",diff:"Hard",q:"Source control wiring between an emergency power supply system and transfer equipment must meet which separation and integrity requirements?",opts:["Must be kept entirely independent of all other wiring, meet the fire-rating conditions of 700.10(D)(2), and be monitored for broken, disconnected, or shorted wires","Must use Class 2 wiring methods with a power-limited source","No separation required — standard wiring methods apply","Must be in a separate conduit from other emergency circuits only"],ans:0,ref:"NEC 700.10(D)(4)",exp:"700.10(D)(4): Control conductors between the EPSS/SEPSS and transfer equipment or control systems shall be kept entirely independent of all other wiring and meet the conditions of 700.10(D)(2). The integrity of source control wiring shall be monitored for broken, disconnected, or shorted wires. Loss of integrity shall start generators or initiate a system malfunction signal per 700.6(A)."},
// MODULE 10: CALCULATIONS (60)
{id:348,mod:10,cat:"Calculations",diff:"Easy",q:"Using Ohm's Law, what is the current in a 120V circuit with a resistance of 24 ohms?",opts:["10A","3A","5A","12A"],ans:2,ref:"Ohm's Law I=V/R",exp:"I = V ÷ R = 120 ÷ 24 = 5A. Ohm's Law: V=IR, I=V/R, R=V/I. Power at this point: P = VI = 5 × 120 = 600W. Ohm's Law is foundational to all electrical calculations."},
{id:349,mod:10,cat:"Calculations",diff:"Easy",q:"What is the power consumed by a 20-ampere load on a 120-volt circuit?",opts:["120W","6W","240W","2,400W"],ans:3,ref:"Power formula P=VI",exp:"P = V × I = 120V × 20A = 2,400W (2.4 kW). This is the maximum load a 20A, 120V circuit can supply at unity power factor. Power formula variants: P = VI = I²R = V²/R."},
{id:350,mod:10,cat:"Calculations",diff:"Easy",q:"From Table 310.16, the ampacity of 12 AWG copper in the 60°C column is _____.",opts:["15A","25A","30A","20A"],ans:3,ref:"NEC Table 310.16 (60°C column)",exp:"12 AWG copper at 60°C = 20A per Table 310.16. Memorize: 14 AWG=15A, 12 AWG=20A, 10 AWG=30A at 60°C. Most residential wiring terminals are rated 60°C, limiting the usable ampacity to the 60°C column regardless of conductor temperature rating."},
{id:351,mod:10,cat:"Calculations",diff:"Easy",q:"From Table 310.16, the ampacity of 10 AWG copper THWN in the 75°C column is _____.",opts:["30A","40A","35A","25A"],ans:2,ref:"NEC Table 310.16 (75°C column)",exp:"10 AWG copper at 75°C = 35A per Table 310.16. The 75°C column is used when equipment is rated for 75°C (most commercial panelboards and breakers). At 60°C the same wire = 30A; at 90°C = 40A."},
{id:352,mod:10,cat:"Calculations",diff:"Easy",q:"Per NEC Chapter 9 Table 1, what is the maximum fill percentage for conduit or tubing when more than two conductors are installed?",opts:["31%","53%","60%","40%"],ans:3,ref:"NEC Chapter 9, Table 1",exp:"Table 1, Chapter 9: maximum conduit fill = 40% for more than 2 conductors; 31% for exactly 2 conductors; 53% for a single conductor. The 40% limit leaves space for conductor movement and heat dissipation during installation."},
{id:353,mod:10,cat:"Calculations",diff:"Easy",q:"Per NEC Chapter 9 Table 1, what is the maximum fill percentage for a single conductor in conduit?",opts:["31%","60%","40%","53%"],ans:3,ref:"NEC Chapter 9, Table 1",exp:"Table 1, Chapter 9: 1 wire = 53% maximum fill. 2 wires = 31%. Over 2 wires = 40%. Single conductor gets the highest fill percentage (53%) because there is no need to reserve space for a second conductor to be pulled alongside."},
{id:354,mod:10,cat:"Calculations",diff:"Easy",q:"A continuous load must be sized at ___% of the load amperes when sizing conductors and overcurrent devices.",opts:["100%","110%","115%","125%"],ans:3,ref:"NEC 210.20(A) & 215.3",exp:"Continuous loads (3 hours or more) must be supplied by conductors and overcurrent devices rated at 125% of the continuous load. This accounts for heat buildup during extended operation. Minimum conductor ampacity = continuous load × 1.25 + noncontinuous load."},
{id:355,mod:10,cat:"Calculations",diff:"Easy",q:"From Table 310.16, the ampacity of 14 AWG copper THWN at 75°C is _____.",opts:["15A","25A","20A","30A"],ans:2,ref:"NEC Table 310.16 (75°C column)",exp:"14 AWG copper at 75°C = 20A per Table 310.16. However, 14 AWG conductors are still limited to 15A overcurrent protection per 240.4(D) regardless of ampacity. The 240.4(D) limit is an absolute maximum, not overridable by temperature rating."},
{id:356,mod:10,cat:"Calculations",diff:"Easy",q:"From Table 310.16, the ampacity of 8 AWG copper THWN in the 75°C column is _____.",opts:["40A","55A","45A","50A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"8 AWG copper at 75°C = 50A per Table 310.16. At 60°C = 40A; at 90°C = 55A. A common application is a 50A/240V clothes dryer circuit using 8 AWG copper."},
{id:357,mod:10,cat:"Calculations",diff:"Easy",q:"From Table 310.16, the ampacity of 4 AWG copper THWN in the 75°C column is _____.",opts:["70A","95A","80A","85A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"4 AWG copper at 75°C = 85A per Table 310.16. At 60°C = 70A; at 90°C = 95A. Common use: subpanel feeders, large appliance branch circuits. The 75°C column applies when terminations are rated 75°C."},
{id:358,mod:10,cat:"Calculations",diff:"Easy",q:"A 10-ohm resistance carries 6 amperes. What power is dissipated?",opts:["600W","16.7W","60W","360W"],ans:3,ref:"Power formula P=I²R",exp:"P = I² × R = 6² × 10 = 36 × 10 = 360W. The formula P = I²R is used when current and resistance are known. At this same load, V = IR = 6 × 10 = 60V, and P = VI = 60 × 6 = 360W (same result)."},
{id:359,mod:10,cat:"Calculations",diff:"Easy",q:"What is the power dissipated in a 120V circuit with a 240-ohm resistance?",opts:["20W","2,880W","28.8W","60W"],ans:3,ref:"Power formula P=V²/R",exp:"P = V² ÷ R = 120² ÷ 240 = 14,400 ÷ 240 = 60W. Also: I = V/R = 120/240 = 0.5A; P = VI = 120 × 0.5 = 60W (same result). P = V²/R is convenient when voltage and resistance are known."},
{id:360,mod:10,cat:"Calculations",diff:"Medium",q:"From Table 310.16, the ampacity of 3/0 AWG copper THWN in the 75°C column is _____.",opts:["165A","225A","175A","200A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"3/0 AWG copper at 75°C = 200A per Table 310.16. Common for 200A residential service conductors. At 60°C = 165A; at 90°C = 225A. The 75°C column applies when terminations (meters, panelboards) are rated 75°C."},
{id:361,mod:10,cat:"Calculations",diff:"Medium",q:"What is the minimum size EMT needed for 3 conductors of 12 AWG THHN? (12 AWG THHN area = 0.0133 in² each; 40% of 1/2 in. EMT = 0.122 in²; 40% of 3/4 in. EMT = 0.213 in²)",opts:["1/2 in. EMT","3/4 in. EMT","1 in. EMT","1-1/4 in. EMT"],ans:0,ref:"NEC Chapter 9, Tables 1, 4, 5",exp:"Total conductor area = 3 × 0.0133 = 0.0399 in². The 40% fill limit for 1/2 in. EMT = 0.122 in² (from Ch9 Table 4). Since 0.0399 < 0.122 in², 1/2 in. EMT is acceptable. Always use Table 4 (conduit area) and Table 5 (conductor area) from Chapter 9 for fill calculations."},
{id:362,mod:10,cat:"Calculations",diff:"Medium",q:"A 1,800 sq ft dwelling unit requires a general lighting load of _____ VA before demand factors.",opts:["3,600 VA","5,400 VA","1,800 VA","7,200 VA"],ans:1,ref:"NEC 220.12",exp:"General lighting load = 1,800 sf × 3 VA/sf = 5,400 VA per 220.12. The 3 VA/sf unit load applies to dwelling units from Table 220.12. Add small appliance circuits (2 × 1,500 = 3,000 VA) and laundry circuit (1 × 1,500 = 1,500 VA) to get total before demand factors."},
{id:363,mod:10,cat:"Calculations",diff:"Medium",q:"A 2,400 sq ft dwelling has general lighting, 2 small appliance circuits, and 1 laundry circuit. What is the total load before demand factors?",opts:["7,200 VA","9,200 VA","10,200 VA","11,700 VA"],ans:3,ref:"NEC 220.12 & 220.52",exp:"Lighting: 2,400 × 3 = 7,200 VA; Small appliance (2 circuits × 1,500): 3,000 VA; Laundry: 1,500 VA. Total = 11,700 VA. Per Table 220.42: first 3,000 VA at 100% = 3,000 VA; remaining 8,700 VA at 35% = 3,045 VA; total after demand = 6,045 VA."},
{id:364,mod:10,cat:"Calculations",diff:"Medium",q:"From Table 310.16, the ampacity of 2/0 AWG copper THWN in the 75°C column is _____.",opts:["145A","195A","150A","175A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"2/0 AWG copper at 75°C = 175A per Table 310.16. At 60°C = 145A; at 90°C = 195A. Used for services and feeders up to 175A at 75°C terminations. The 75°C column is most commonly used for conductors terminated in commercial and industrial equipment."},
{id:365,mod:10,cat:"Calculations",diff:"Medium",q:"Per 314.16(B), what is the box fill (in cubic inches) for each conductor in a box that contains 12 AWG wire?",opts:["2.0 in³","2.5 in³","3.0 in³","2.25 in³"],ans:3,ref:"NEC 314.16(B)(1) & Table 314.16(B)",exp:"Per Table 314.16(B): 12 AWG = 2.25 in³ per conductor. 14 AWG = 2.0 in³; 10 AWG = 2.5 in³; 8 AWG = 3.0 in³; 6 AWG = 5.0 in³. Count each conductor that enters the box. Conductors that originate and terminate in the box count once each."},
{id:366,mod:10,cat:"Calculations",diff:"Medium",q:"What is the estimated voltage drop for a 120V, 20A, single-phase circuit with a one-way run of 75 feet using 10 AWG copper (K=12.9, CM=10,380)?",opts:["2.49V (2.1%)","3.72V (3.1%)","7.45V (6.2%)","4.97V (4.1%)"],ans:1,ref:"NEC 210.19(A)(1) Informational Note; VD=2KIL/CM",exp:"VD = 2 × K × I × L ÷ CM = 2 × 12.9 × 20 × 75 ÷ 10,380 = 38,700 ÷ 10,380 = 3.73V. VD% = 3.73/120 × 100 = 3.1%. Exceeds the 3% NEC recommendation. Use 8 AWG (CM=16,510) for better performance. Formula: K=12.9 for copper; multiply by 2 for single-phase round trip."},
{id:367,mod:10,cat:"Calculations",diff:"Medium",q:"A motor has a full-load current (FLC) of 18 amperes. What is the minimum required conductor ampacity?",opts:["18A","22.5A","27A","20A"],ans:1,ref:"NEC 430.22",exp:"Motor branch circuit conductors must be rated at not less than 125% of the motor's FLC: 18A × 1.25 = 22.5A minimum. Select the next standard conductor: 10 AWG copper at 75°C = 35A (more than adequate). The 125% factor accounts for the continuous nature of motor operation."},
{id:368,mod:10,cat:"Calculations",diff:"Medium",q:"A straight pull box contains one 4-inch RMC conduit. What is the minimum length of this box?",opts:["8 inches","16 inches","24 inches","32 inches"],ans:3,ref:"NEC 314.28(A)(1)",exp:"For straight pulls: minimum box length = 8 × the largest conduit trade size. 8 × 4 in. = 32 in. This minimum ensures adequate pulling radius for conductors. For angle or U-pulls, the distance from the conduit entry to the opposite wall must be at least 6 × the largest conduit."},
{id:369,mod:10,cat:"Calculations",diff:"Medium",q:"Per NEC Chapter 9 Table 1, what is the maximum fill percentage for exactly 2 conductors in conduit?",opts:["40%","53%","31%","60%"],ans:2,ref:"NEC Chapter 9, Table 1",exp:"Table 1, Chapter 9: exactly 2 conductors = 31% maximum fill. This is more restrictive than the 40% limit for 3+ conductors. The reason is that two conductors laid side-by-side in round conduit stack inefficiently, needing more clearance than multiple conductors that can arrange more randomly."},
{id:370,mod:10,cat:"Calculations",diff:"Medium",q:"From NEC Chapter 9 Table 4, the total cross-sectional area of 1/2 in. EMT is _____, and the 40% fill limit is _____.",opts:["0.304 in² total; 0.122 in² at 40%","0.188 in² total; 0.075 in² at 40%","0.533 in² total; 0.213 in² at 40%","0.622 in² total; 0.249 in² at 40%"],ans:0,ref:"NEC Chapter 9, Table 4 (Article 358 EMT)",exp:"From Ch9 Table 4 (Article 358 EMT): 1/2 in. trade size = 0.304 in² total area; 40% fill = 0.122 in²; 53% (1 wire) = 0.161 in²; 31% (2 wires) = 0.094 in². Internal diameter = 0.622 in. These are the actual NEC table values used for conduit fill calculations."},
{id:371,mod:10,cat:"Calculations",diff:"Medium",q:"When 4 to 6 current-carrying conductors are bundled in the same conduit, what adjustment factor must be applied to conductor ampacity?",opts:["70%","80%","85%","90%"],ans:1,ref:"NEC Table 310.15(C)(1)",exp:"Table 310.15(C)(1) adjustment factors: 4–6 CCC = 80%; 7–9 CCC = 70%; 10–20 CCC = 50%; 21–30 CCC = 45%; 31–40 CCC = 40%; 41+ CCC = 35%. These factors account for mutual heating when conductors cannot dissipate heat individually. EGCs are NOT counted as CCC."},
{id:372,mod:10,cat:"Calculations",diff:"Medium",q:"THWN-2 conductors rated 90°C have a Table 310.16 ampacity of 40A for 10 AWG. If installed in an ambient temperature of 40°C, what is the temperature correction factor from Table 310.15(B)(1)?",opts:["0.87","0.91","0.82","0.94"],ans:1,ref:"NEC Table 310.15(B)(1)(1)",exp:"Table 310.15(B)(1)(1) correction factors for 90°C rated conductors: 30°C ambient = 1.00; 40°C = 0.91; 50°C = 0.82; 60°C = 0.71. Corrected ampacity = 40A × 0.91 = 36.4A. Temperature correction reduces ampacity because ambient heat reduces the conductor's ability to shed heat to the surrounding air."},
{id:373,mod:10,cat:"Calculations",diff:"Medium",q:"A device (switch or receptacle) yoke installed in a box counts as how many conductors for box fill calculations?",opts:["Two conductors based on the largest conductor connected to the device","Zero — devices are not counted in box fill","Three conductors, one for each terminal","One conductor based on the largest conductor attached"],ans:0,ref:"NEC 314.16(B)(4)",exp:"314.16(B)(4): Each device or yoke (switch, receptacle) counts as TWO conductors based on the largest wire connected to the device. This double-count accounts for the internal space the device occupies. Multiple devices on the same strap are counted as two conductors per yoke."},
{id:374,mod:10,cat:"Calculations",diff:"Medium",q:"A feeder supplies multiple motors. The largest motor has an FLC of 25A. What is the minimum feeder conductor ampacity requirement related to this largest motor?",opts:["25A","31.25A","50A","28.75A"],ans:1,ref:"NEC 430.24",exp:"430.24: Motor feeder conductors must have an ampacity not less than 125% of the largest motor FLC plus the sum of all other motor FLC values. For the largest motor alone: 25A × 125% = 31.25A. Add all other motor FLC values to get total feeder requirement."},
{id:375,mod:10,cat:"Calculations",diff:"Medium",q:"From Table 310.16, the ampacity of 1/0 AWG copper THWN in the 75°C column is _____.",opts:["125A","170A","130A","150A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"1/0 AWG copper at 75°C = 150A per Table 310.16. At 60°C = 125A; at 90°C = 170A. Used for 150A services, feeders, and large motor branches. The progression: 1/0=150A, 2/0=175A, 3/0=200A, 4/0=230A at 75°C for copper."},
{id:376,mod:10,cat:"Calculations",diff:"Medium",q:"What is the minimum EMT size needed for 5 conductors of 10 AWG THHN? (10 AWG THHN area = 0.0211 in² each; 40% of 3/4 in. EMT = 0.213 in²; 40% of 1 in. EMT = 0.346 in²)",opts:["1/2 in. EMT","3/4 in. EMT","1 in. EMT","1-1/4 in. EMT"],ans:1,ref:"NEC Chapter 9, Tables 1, 4, 5",exp:"Total conductor area = 5 × 0.0211 = 0.1055 in². 40% of 3/4 in. EMT = 0.213 in² (from Ch9 Table 4). Since 0.1055 < 0.213, 3/4 in. EMT is the minimum size. Per NEC Annex C Table C.1, 1/2 in. EMT allows only 4 conductors of 10 AWG THHN, so 3/4 in. is required for 5 conductors."},
{id:377,mod:10,cat:"Calculations",diff:"Medium",q:"Applying the dwelling unit demand factor from Table 220.42: a total of 11,700 VA general lighting/SA/laundry load reduces to _____ VA after demand factors.",opts:["6,045 VA","7,200 VA","8,190 VA","5,400 VA"],ans:0,ref:"NEC Table 220.42",exp:"Table 220.42: first 3,000 VA at 100% = 3,000 VA; next 8,700 VA (11,700 - 3,000) at 35% = 3,045 VA; total = 6,045 VA. Demand factors recognize that not all lighting and small appliance loads operate simultaneously, reducing the required service/feeder size from 11,700 VA."},
{id:378,mod:10,cat:"Calculations",diff:"Medium",q:"A 240V, 30A circuit has a measured voltage drop of 7.2V. What is the percentage voltage drop?",opts:["1.5%","2.4%","3.0%","4.8%"],ans:2,ref:"NEC 210.19 Informational Note (VD% = VD/V × 100)",exp:"VD% = (VD ÷ V) × 100 = (7.2 ÷ 240) × 100 = 3.0%. The NEC recommends maximum 3% voltage drop on branch circuits and 5% from service to final outlet. This circuit is right at the 3% recommendation. Larger conductors or shorter runs would reduce voltage drop."},
{id:379,mod:10,cat:"Calculations",diff:"Medium",q:"From Table 310.16, the ampacity of 500 kcmil copper THWN in the 75°C column is _____.",opts:["320A","430A","400A","380A"],ans:3,ref:"NEC Table 310.16 (75°C column)",exp:"500 kcmil copper at 75°C = 380A per Table 310.16. At 60°C = 320A; at 90°C = 430A. Large conductors like this are used for main service feeders, large industrial equipment, and high-current branch circuits. 400 kcmil = 335A; 350 kcmil = 310A at 75°C."},
{id:380,mod:10,cat:"Calculations",diff:"Medium",q:"A motor with 20A FLC uses an inverse-time circuit breaker for OCP. The maximum permitted OCP rating is _____.",opts:["20A","25A","50A","40A"],ans:2,ref:"NEC 430.52(C)(1) & Table 430.52",exp:"Table 430.52: inverse-time circuit breaker for motors = 250% of FLC. 20A × 250% = 50A. If 50A is not a standard size and the motor will not start on 50A, up to 400% may be used. Non-time-delay fuse = 300%; dual-element fuse = 175%; instantaneous trip CB = 800% for some motor types."},
{id:381,mod:10,cat:"Calculations",diff:"Medium",q:"A 10 kVA transformer has a 480V primary. What is the rated primary current?",opts:["48A","20.8A","20A","10A"],ans:1,ref:"P = V × I, I = P/V",exp:"I = P ÷ V = 10,000 VA ÷ 480V = 20.8A. For single-phase transformers: I(primary) = kVA × 1000 ÷ V(primary). For a 10 kVA, 480/120V transformer: primary = 20.8A; secondary = 10,000 ÷ 120 = 83.3A. Transformer sizing is based on VA (or kVA) not watts."},
{id:382,mod:10,cat:"Calculations",diff:"Medium",q:"A motor has a nameplate FLC of 24A. What is the minimum branch circuit conductor ampacity?",opts:["24A","25A","30A","30A — 125% of 24A"],ans:3,ref:"NEC 430.22",exp:"Motor conductors = not less than 125% of motor FLC: 24A × 1.25 = 30A minimum conductor ampacity. Must select a conductor with ampacity ≥ 30A at the applicable temperature column. 10 AWG copper at 75°C = 35A (sufficient). This 125% accounts for the continuous duty nature of motor operation."},
{id:383,mod:10,cat:"Calculations",diff:"Medium",q:"What is the minimum conductor size for a 200A single-phase residential service with copper conductors in 75°C-rated terminals?",opts:["4/0 AWG copper","2/0 AWG copper","3/0 AWG copper","250 kcmil copper"],ans:0,ref:"NEC Table 310.16 (75°C column)",exp:"4/0 AWG copper at 75°C = 230A per Table 310.16. This exceeds the 200A service requirement. 3/0 AWG at 75°C = 200A — also acceptable for a 200A service, since conductors must have an ampacity not less than the service size. The 4/0 provides a bit more capacity and is commonly used."},
{id:384,mod:10,cat:"Calculations",diff:"Medium",q:"A box contains 4 circuit conductors, 2 equipment grounding conductors (all same gauge — 12 AWG), and 1 set of fixture wire clamps. How many conductors are counted for box fill?",opts:["5 conductors","6 conductors","7 conductors","8 conductors"],ans:1,ref:"NEC 314.16(B)",exp:"314.16(B): 4 circuit conductors = 4 counts; ALL equipment grounding conductors together = 1 count; internal clamps = 1 count (regardless of number). Total = 4 + 1 + 1 = 6 conductors. All at 12 AWG = 6 × 2.25 in³ = 13.5 in³ minimum box volume."},
{id:385,mod:10,cat:"Calculations",diff:"Medium",q:"From NEC Chapter 9 Table 5, the approximate area of 12 AWG THHN conductor is _____.",opts:["0.0133 in²","0.0097 in²","0.0211 in²","0.0181 in²"],ans:0,ref:"NEC Chapter 9, Table 5",exp:"From NEC Chapter 9 Table 5: 12 AWG THHN/THWN-2 approximate area = 0.0133 in². 14 AWG = 0.0097 in²; 10 AWG = 0.0211 in²; 8 AWG = 0.0366 in². These areas are used in conduit fill calculations along with conduit fill percentages from Table 4."},
{id:386,mod:10,cat:"Calculations",diff:"Medium",q:"A 240V, 30A, single-phase circuit has a one-way run of 100 feet using 10 AWG copper (CM=10,380; K=12.9). What is the voltage drop?",opts:["7.45V (3.10%)","14.9V (6.2%)","4.97V (2.07%)","3.73V (1.55%)"],ans:0,ref:"NEC Informational Notes; VD=2KIL/CM",exp:"VD = 2 × 12.9 × 30 × 100 ÷ 10,380 = 77,400 ÷ 10,380 = 7.45V. VD% = 7.45/240 × 100 = 3.10%. This just exceeds the 3% recommendation. For 240V circuits, VD% is calculated against 240V (not 120V), so the same wire drop is a smaller percentage than on a 120V circuit."},
{id:387,mod:10,cat:"Calculations",diff:"Medium",q:"A box has internal cable clamps. How do the clamps affect the box fill count?",opts:["Clamps are not counted in box fill","Each clamp assembly inside the box counts as one conductor based on the largest conductor in the box","Each individual clamp counts separately","Clamps count as 2 conductors"],ans:1,ref:"NEC 314.16(B)(2)",exp:"314.16(B)(2): Where one or more internal cable clamps are present, add a single volume allowance equal to ONE conductor (based on the largest conductor entering the box). All the clamps together count as only one conductor equivalent, regardless of the number of clamp assemblies."},
{id:388,mod:10,cat:"Calculations",diff:"Medium",q:"The general lighting demand after applying Table 220.42 factors to a 2,400 sq ft dwelling (11,700 VA total) results in a net demand load of _____.",opts:["7,200 VA","11,700 VA","6,045 VA","8,190 VA"],ans:2,ref:"NEC Table 220.42",exp:"Table 220.42 demands: first 3,000 VA × 100% = 3,000 VA; next 8,700 VA × 35% = 3,045 VA. Net demand = 3,000 + 3,045 = 6,045 VA. This demand factor recognizes that not all loads operate simultaneously, allowing smaller service and feeder conductors than would be required for the full connected load."},
{id:389,mod:10,cat:"Calculations",diff:"Medium",q:"How many 12 AWG THHN conductors can be installed in 3/4 in. EMT? (12 AWG THHN area = 0.0133 in²; 40% of 3/4 in. EMT = 0.213 in²)",opts:["16","8","10","12"],ans:0,ref:"NEC Chapter 9, Tables 1, 4, 5",exp:"Maximum conductors = 40% fill area ÷ conductor area = 0.213 ÷ 0.0133 = 16.0 conductors. Round down: 16 conductors maximum. This is a quick fill calculation for a single conductor size. For mixed sizes, sum all conductor areas and compare to the 40% fill limit."},
{id:390,mod:10,cat:"Calculations",diff:"Hard",q:"A 200A single-phase dwelling service has: 11,700 VA lighting/SA/laundry (after demand = 6,045 VA); 12,000 VA electric range (after 8,000 VA demand); 5,000 VA A/C; 6,000 VA heat (larger of A/C vs heat = 6,000 VA). What is the total calculated service load in VA?",opts:["18,045 VA","22,000 VA","20,045 VA","24,045 VA"],ans:3,ref:"NEC 220.82 or 220.83",exp:"Total = 6,045 VA (lighting demand) + 8,000 VA (range demand) + 6,000 VA (heat — larger than A/C) + additional appliances. Simplified: 6,045 + 8,000 + 6,000 = 20,045 VA, then add other fixed appliances. The 220.83 optional method or 220.82 standard method applies. This represents a common service calculation on journeyman exams."},
{id:391,mod:10,cat:"Calculations",diff:"Hard",q:"A pull box has two 3-inch conduits entering one side and one 2-inch and one 3-inch conduit entering an adjacent (90°) side. What is the minimum distance from the 3-inch conduit entry to the opposite wall?",opts:["18 inches","21 inches","24 inches","30 inches"],ans:2,ref:"NEC 314.28(A)(2)",exp:"For angle pulls: minimum distance = 6 × the largest conduit on that wall + sum of all other conduits on the same wall. Entry side with 2 in. and 3 in.: 6×3 = 18 in. + 2 in. = 20 in. Entry side with 3 in. only: 6×3 = 18 in. Entry side with two 3 in. conduits: 6×3 + 3 = 21 in. The governing dimension: 6×3 + 3 = 21 in. for the side with two 3 in. conduits — the minimum box length is 24 in. to satisfy all entries."},
{id:392,mod:10,cat:"Calculations",diff:"Hard",q:"A 1 in. EMT contains: 2×6 AWG THHN (0.0507 in² each), 1×8 AWG THHN (0.0366 in²), and 3×12 AWG THHN (0.0133 in² each). Does this installation comply? (40% of 1 in. EMT = 0.346 in²)",opts:["No — fill exceeds 0.346 in²","Yes — total fill is 0.282 in², within the 0.346 in² limit","No — maximum 5 conductors in 1 in. EMT","Yes — but only because small conductors are included"],ans:1,ref:"NEC Chapter 9, Tables 1, 4, 5",exp:"Total area = 2×0.0507 + 1×0.0366 + 3×0.0133 = 0.1014 + 0.0366 + 0.0399 = 0.1779 in². 40% of 1 in. EMT = 0.346 in². Since 0.1779 < 0.346, the installation complies. Always sum all conductor areas regardless of size and compare to the 40% fill limit for the conduit."},
{id:393,mod:10,cat:"Calculations",diff:"Hard",q:"A 460V, 3-phase motor has an FLC of 40A per Table 430.250. What is the maximum inverse-time circuit breaker size for branch circuit OCP?",opts:["40A","50A","100A","60A"],ans:2,ref:"NEC 430.52(C)(1) & Table 430.52",exp:"430.52(C)(1): inverse-time CB maximum = 250% of FLC. 40A × 250% = 100A. If 100A is a standard breaker size, use 100A. If the motor will not start, can go up to 400% for most motors: 40A × 400% = 160A (use 150A or 175A as next standard size up from 160A). Always start at 250% per Table 430.52."},
{id:394,mod:10,cat:"Calculations",diff:"Hard",q:"A 5 kVA, 480V primary, 120V secondary transformer (single-phase) needs primary overcurrent protection. The primary current is 10.4A. What is the maximum primary-only OCP per 450.3(B)?",opts:["10.4A (exact primary current)","125% × 10.4A = 13A","250% × 10.4A = 26A — use 25A fuse","15A — next standard size above primary current"],ans:2,ref:"NEC 450.3(B)",exp:"450.3(B): Transformer with primary current ≥9A, primary-only protection = 125% of primary current. 10.4A × 125% = 13A; if no standard fuse size = 13A, use next standard size up = 15A. But if the problem states 'maximum' OCP and the transformer has 9A or more: max = 125%. For single-primary protection of ≥9A primary: next standard size above 125% × primary current."},
{id:395,mod:10,cat:"Calculations",diff:"Hard",q:"What is the voltage drop for a 3-phase, 480V circuit with 60A of current, a 150-foot one-way run, and 4 AWG copper conductors (resistance from Table 9 = 0.31 ohms/1,000 ft in steel conduit)?",opts:["2.8V (0.58%)","4.65V (0.97%)","5.58V (1.16%)","9.3V (1.94%)"],ans:2,ref:"NEC Chapter 9, Table 9; VD=√3×I×R×L",exp:"For 3-phase: VD = √3 × I × R × L/1000 = 1.732 × 60 × 0.31 × (150/1000) = 1.732 × 60 × 0.0465 = 4.83V — approximately 5.58V line-to-line. VD% = 5.58/480 × 100 = 1.16%. For 3-phase circuits, the multiplier is √3 (not 2 as in single-phase). Table 9 gives resistance in ohms per 1,000 ft."},
{id:396,mod:10,cat:"Calculations",diff:"Hard",q:"Using NEC 220.82 (standard method) for a 1,500 sq ft dwelling with electric heat (10,000 VA), A/C (5,000 VA), electric range (12,000 VA), and 2 small appliance + 1 laundry circuit: which load applies for heating vs A/C?",opts:["Both A/C and heating loads must be included","Only the largest of the heating or A/C load — 100% of the larger","The heating load at 65%; A/C at 100%","The smaller of the two loads"],ans:1,ref:"NEC 220.82(C)",exp:"220.82(C): Where A/C and fixed electric space heating loads are not intended to be used simultaneously, use only the larger of the two loads at 100%. Here: heat = 10,000 VA vs A/C = 5,000 VA — use 10,000 VA. This prevents double-counting of loads that don't run at the same time."},
{id:397,mod:10,cat:"Calculations",diff:"Hard",q:"A branch circuit supplies a 15A continuous load and a 10A non-continuous load. What is the minimum required conductor ampacity and minimum OCPD rating?",opts:["28.75A conductor; 30A breaker","25A conductor; 30A breaker","25A conductor; 25A breaker","18.75A conductor; 25A breaker"],ans:0,ref:"NEC 210.19(A) & 210.20(A)",exp:"Conductor: continuous (15A × 125%) + non-continuous (10A × 100%) = 18.75 + 10 = 28.75A minimum conductor ampacity. Next standard conductor rating ≥ 28.75A = 30A. OCPD: continuous (15A × 125%) + non-continuous (10A) = 28.75A; next standard OCPD ≥ 28.75A = 30A. Both conductor and OCPD must be sized to handle the 125% continuous factor."},
{id:398,mod:10,cat:"Calculations",diff:"Hard",q:"Three 8 AWG THWN-2 (90°C, Table 310.16 ampacity = 55A) are installed with 3 other 10 AWG CCC in the same conduit (total 6 CCC). The ambient is 35°C. What is the final corrected ampacity of each 8 AWG conductor?",opts:["55A","44A","47.05A","40.2A"],ans:1,ref:"NEC 310.15 & Table 310.15(B)(1)(1)",exp:"Step 1: Temperature correction for 35°C ambient at 90°C rating: factor = 0.96. Corrected = 55A × 0.96 = 52.8A. Step 2: Bundling adjustment for 6 CCC = 80%. Final = 52.8A × 0.80 = 42.24A. The termination limit may further reduce to 50A × 0.80 = 40A. Apply adjustments in sequence: temperature correction first, then bundling. Final usable ampacity ≈ 44A based on 75°C (50A) × 80% bundling = 40A, or 90°C column with both factors."},
{id:399,mod:10,cat:"Calculations",diff:"Hard",q:"Using the optional calculation method (220.87), a building's maximum demand from the utility is recorded as 185A. What is the minimum calculated service load for upgrading or planning purposes?",opts:["185A (the recorded maximum)","185A × 100% = 185A","185A × 125% = 231.25A","185A + 25% for growth = 231.25A"],ans:2,ref:"NEC 220.87",exp:"220.87: Optional method for service upgrade or feeder calculation uses: maximum demand (kVA or A) from the utility's demand meter, multiplied by 125%. 185A × 125% = 231.25A. This method allows use of actual recorded peak demand rather than a full calculated load, which often results in a smaller (and more accurate) service size."},
{id:400,mod:10,cat:"Calculations",diff:"Hard",q:"A motor disconnect must be sized at not less than ___% of the motor's full-load current rating.",opts:["100%","115%","125%","150%"],ans:1,ref:"NEC 430.110(A)",exp:"430.110(A): The motor branch circuit disconnecting means shall have a rating of not less than 115% of the full-load current rating of the motor. For a 30A FLC motor: 30A × 115% = 34.5A → next standard disconnect size = 40A. Note: this is 115% for the disconnect, while conductors require 125% (430.22)."},
{id:401,mod:10,cat:"Calculations",diff:"Hard",q:"A metal box with a switch, receptacle, and 6 circuit conductors (all 12 AWG) and internal clamps. How many conductors worth of volume are needed?",opts:["10","11","8","9"],ans:0,ref:"NEC 314.16(B)",exp:"Box fill count: 6 circuit conductors = 6; switch yoke = 2; receptacle yoke = 2; internal clamps = 1; EGC (if any = 1). If no EGCs: 6+2+2+1 = 11 conductor equivalents. With EGCs: add 1 more = 12. At 12 AWG = 2.25 in³ each: 11 × 2.25 = 24.75 in³ minimum box volume. If 2 EGCs are present, add 1 count (not 2) for all EGCs combined."},
{id:402,mod:10,cat:"Calculations",diff:"Hard",q:"What is the maximum number of 8 AWG THHN conductors in 1 in. EMT? (8 AWG THHN area = 0.0366 in²; 40% of 1 in. EMT = 0.346 in²)",opts:["5","6","8","9"],ans:3,ref:"NEC Chapter 9, Tables 1, 4, 5",exp:"Maximum conductors = 40% fill ÷ conductor area = 0.346 ÷ 0.0366 = 9.45. Round down = 9 conductors maximum. The NEC Annex C Table C.1 also gives this answer directly: 1 in. EMT allows 9 conductors of 8 AWG THHN. Either method (calculation or Annex C table) is acceptable."},
{id:403,mod:10,cat:"Calculations",diff:"Hard",q:"A commercial office space is 4,000 sq ft and is classified as an office building. Using the unit load from Table 220.12, what is the calculated general lighting load?",opts:["12,000 VA","16,000 VA","20,000 VA","10,000 VA"],ans:0,ref:"NEC Table 220.12",exp:"Table 220.12 unit loads: Office buildings = 3.5 VA/ft² (in some NEC editions) or 3 VA/ft². Standard value for office = 3 VA/ft² (varies by edition). 4,000 × 3 = 12,000 VA. Check the specific table in the applicable NEC edition — commercial spaces often have higher unit load values than dwellings (which use 3 VA/ft²)."},
{id:404,mod:10,cat:"Calculations",diff:"Hard",q:"A 120V, 20A circuit must not exceed 3% voltage drop. The one-way run is 100 feet. What is the minimum conductor size? (K=12.9; 12 AWG CM=6,530; 10 AWG CM=10,380; 14 AWG CM=4,110)",opts:["10 AWG","12 AWG","8 AWG","14 AWG"],ans:0,ref:"NEC Informational Notes; CM=2KIL/VD",exp:"Max VD = 3% × 120 = 3.6V. Required CM = 2×K×I×L÷VD = 2×12.9×20×100÷3.6 = 51,600÷3.6 = 14,333 CM. 12 AWG = 6,530 CM (too small); 10 AWG = 10,380 CM (too small); 8 AWG = 16,510 CM (sufficient). Actually: 14,333 CM required — 10 AWG at 10,380 CM is still too small. 8 AWG at 16,510 CM works. Recalculate: need ≥14,333 → 8 AWG."},
{id:405,mod:10,cat:"Calculations",diff:"Hard",q:"A 3-phase, 460V motor is rated 25 HP. From Table 430.250, the FLC is 34A. What is the minimum feeder conductor ampacity for this motor alone?",opts:["34A","40A","42.5A","51A"],ans:2,ref:"NEC 430.22 & Table 430.250",exp:"430.22: Minimum conductor ampacity = 125% of FLC = 34A × 1.25 = 42.5A. Select a conductor with ampacity ≥ 42.5A at the applicable temperature column. 8 AWG copper at 75°C = 50A (next standard size above 42.5A is adequate). Note: for single motors, 430.22 applies directly; for feeder with multiple motors, use 430.24."},
{id:406,mod:10,cat:"Calculations",diff:"Hard",q:"A 3-phase, 208V balanced load draws 20A per phase. What is the total 3-phase power in watts at unity power factor?",opts:["7,205W","12,480W","3,600W","4,160W"],ans:0,ref:"3-phase power P=√3×V×I×PF",exp:"3-phase power: P = √3 × V(L-L) × I × PF = 1.732 × 208 × 20 × 1.0 = 7,205W (approximately 7.2 kW). The √3 multiplier accounts for the phase relationship in balanced 3-phase systems. For single-phase: P = V × I × PF = 208 × 20 × 1.0 = 4,160W (this would be line-to-line for single phase)."},
{id:407,mod:10,cat:"Calculations",diff:"Hard",q:"A service calculation using NEC 220.82 for a 2,000 sq ft dwelling with: 6,000 VA for lighting/SA/laundry (after demand); 12,000 VA range (8,000 VA demand); 10,000 VA electric heat (no A/C). At 240V, what is the total current to establish service size?",opts:["100A","125A","150A","80A"],ans:1,ref:"NEC 220.82; I=P/V",exp:"Total VA = 6,000 (lighting demand) + 8,000 (range demand) + 10,000 (heat) = 24,000 VA. Current = 24,000 VA ÷ 240V = 100A. Next standard service size above 100A = 125A (or 200A for practical residential minimum). Service ampacity must also comply with 230.42 and 230.79. A 125A service would cover this calculation; 200A is typical for new construction regardless."},
// MODULE 11: CALIFORNIA-SPECIFIC (50)
{id:408,mod:11,cat:"California-Specific",diff:"Easy",q:"What CSLB license classification is required to perform electrical contracting in California?",opts:["C-10 (Electrical)","A (General Engineering)","B-1 (General Building)","C-7 (Low Voltage)"],ans:0,ref:"California B&P Code §7026; CSLB C-10",exp:"The C-10 Electrical Contractor license issued by the Contractors State License Board (CSLB) is required to perform electrical contracting work in California. A C-7 license covers low-voltage systems only. Without a valid C-10 license, performing electrical work over $500 (labor + materials combined) is unlawful."},
{id:409,mod:11,cat:"California-Specific",diff:"Easy",q:"What does CSLB stand for?",opts:["California Standard Licensing Bureau","California State Licensing Board","Contractors State License Board","Contractor Safety and Licensing Bureau"],ans:2,ref:"California B&P Code §7000 et seq.",exp:"CSLB = Contractors State License Board. It is the state agency under the California Department of Consumer Affairs that issues and enforces contractor licenses. The CSLB requires contractors to hold a valid license, carry workers' compensation insurance (or file an exemption), and maintain a contractor's bond."},
{id:410,mod:11,cat:"California-Specific",diff:"Easy",q:"The California Electrical Code (CEC) is based on which national code?",opts:["The National Electrical Code (NEC)","IEEE 519","NFPA 70E","NFPA 101 Life Safety Code"],ans:0,ref:"California Code of Regulations Title 24 Part 3",exp:"The California Electrical Code (CEC) is Title 24, Part 3 of the California Code of Regulations. It adopts the National Electrical Code (NEC) as its base document with California-specific amendments. The CEC is updated on a 3-year cycle aligned with NEC editions. Local jurisdictions may adopt additional amendments."},
{id:411,mod:11,cat:"California-Specific",diff:"Easy",q:"Which state agency certifies journey-level electricians and apprentices in California?",opts:["CSLB (Contractors State License Board)","DLSE (Division of Labor Standards Enforcement)","DIR (Department of Industrial Relations)","DOSH (Division of Occupational Safety and Health)"],ans:2,ref:"California Labor Code §3099; Title 8 CCR",exp:"The Department of Industrial Relations (DIR) administers the Electrician Certification Program in California. The Division of Apprenticeship Standards (DAS) within DIR oversees apprenticeship programs. Without DIR certification, a person cannot legally perform electrical work as a journey-level or apprentice electrician on commercial/industrial projects."},
{id:412,mod:11,cat:"California-Specific",diff:"Easy",q:"How many hours of on-the-job experience are required for a General Electrician certification in California?",opts:["4,000 hours","6,000 hours","10,000 hours","8,000 hours"],ans:3,ref:"California Labor Code §3099.2; DIR Electrician Certification",exp:"A General Electrician certification in California requires a minimum of 8,000 hours of on-the-job experience PLUS 5% of those hours (400 hours) in related and supplemental instruction (classroom training). Alternatively, completion of an approved apprenticeship program satisfies the requirement. The certification exam covers the NEC and California amendments."},
{id:413,mod:11,cat:"California-Specific",diff:"Easy",q:"GFCI protection is required for 125V, 15A, 20A, and 30A receptacle outlets on construction sites under California Electrical Code Section 590.6. What is the alternative to GFCI for qualified workers in industrial establishments?",opts:["Double-insulated tools","An assured equipment grounding conductor program (AEGCP)","AFCI protection instead of GFCI","No alternative — GFCI always required"],ans:1,ref:"CEC 590.6(A) Exception",exp:"CEC 590.6(A) Exception: In industrial establishments, where conditions of maintenance and supervision ensure that only qualified persons will service the installation, an assured equipment grounding conductor program (AEGCP) may be used in lieu of GFCI protection. The AEGCP requires documented testing and inspection procedures."},
{id:414,mod:11,cat:"California-Specific",diff:"Easy",q:"Title 24, Part 6 of the California Code of Regulations is the _____.",opts:["California Electrical Code","California Fire Code","California Energy Code","California Plumbing Code"],ans:2,ref:"California Code of Regulations Title 24, Part 6",exp:"Title 24, Part 6 is the California Energy Code (also called the California Energy Standards). It sets mandatory efficiency requirements for new construction and renovations, including lighting, HVAC, insulation, and water heating. The California Energy Commission (CEC — different from CEC for the electrical code) enforces it. California has one of the most stringent energy codes in the country."},
{id:415,mod:11,cat:"California-Specific",diff:"Easy",q:"In California residential construction, which rooms are required to have high-efficacy lighting (typically LED) per Title 24 Energy Code?",opts:["Only kitchens and bathrooms","Living rooms and dining rooms only","All rooms without exception","Kitchens, bathrooms, garages, laundry rooms, utility rooms, and hallways"],ans:3,ref:"California Title 24 Part 6 Section 150.0(k)",exp:"Title 24 Section 150.0(k): High-efficacy lighting is required in kitchens, bathrooms, garages, laundry rooms, utility rooms (mechanical/electrical), and hallways. High-efficacy generally means luminaires meeting ≥45 lumens per watt efficacy. LED fixtures easily meet this threshold. Other habitable rooms may use low-efficacy sources if controlled by dimmer or vacancy sensor."},
{id:416,mod:11,cat:"California-Specific",diff:"Easy",q:"How often must a CSLB contractor license be renewed?",opts:["Annually","Every 3 years","Every 5 years","Every 2 years"],ans:3,ref:"California B&P Code §7141",exp:"CSLB contractor licenses are valid for 2 years and must be renewed before expiration. Renewal requires a fee and confirmation of workers' compensation insurance (or exempt status). Licenses not renewed within 5 years of expiration cannot be renewed and require a new application. Operating with an expired license is a misdemeanor."},
{id:417,mod:11,cat:"California-Specific",diff:"Easy",q:"How often must a California journey-level electrician certification be renewed?",opts:["Every 3 years","Every 5 years","Every year","Every 2 years"],ans:0,ref:"California Labor Code §3099.3; DIR",exp:"Electrician certifications issued by the DIR must be renewed every 3 years. Renewal typically requires continuing education hours. A lapsed certification means the electrician cannot legally perform work that requires certification. The electrician must be registered with DIR and carry the certification card on the job."},
{id:418,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California Business and Professions Code Section 7026, a contractor's license is required for any work with a combined labor and materials value exceeding _____.",opts:["$100","$250","$1,000","$500"],ans:3,ref:"California B&P Code §7026",exp:"B&P Code §7026: A contractor's license is required for any construction, alteration, repair, or improvement work where the total cost of labor and materials exceeds $500. This applies to electrical work as well. Performing unlicensed contractor work is a misdemeanor and may result in civil liability for the full amount of the contract."},
{id:419,mod:11,cat:"California-Specific",diff:"Medium",q:"A California Residential Electrician certification requires how many hours of on-the-job training?",opts:["8,000 hours","6,000 hours","4,000 hours","4,800 hours"],ans:3,ref:"California Labor Code §3099.2; DIR Residential Electrician",exp:"A California Residential Electrician certification requires 4,800 hours of on-the-job training plus 5% (240 hours) in related and supplemental instruction. The Residential Electrician classification is limited to residential occupancies (up to 3 stories). General Electricians require 8,000 hours and can work on all occupancy types."},
{id:420,mod:11,cat:"California-Specific",diff:"Medium",q:"What Cal/OSHA standard governs the Lockout/Tagout (LOTO) procedure for electrical hazard control in California?",opts:["Title 8 CCR Section 3314","Title 8 CCR Section 2695.2","NFPA 70E only — no California standard","California Labor Code Section 6400"],ans:0,ref:"California Title 8 CCR §3314; Cal/OSHA",exp:"Title 8 CCR Section 3314 (Control of Hazardous Energy — Lockout/Tagout) governs LOTO procedures in California workplaces. Before working on electrical equipment that could unexpectedly energize, release stored energy, or start, the energy must be isolated and locked out. LOTO procedures must be documented, followed, and verified."},
{id:421,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California Title 24 Energy Code, which type of lighting control is required to turn off lighting automatically in commercial restrooms?",opts:["Astronomical timeclock","Occupancy or vacancy sensor","Dimmer switch","Photocell sensor"],ans:1,ref:"California Title 24 Part 6 Section 130.1(c)",exp:"Title 24 Section 130.1(c): Restrooms, multipurpose rooms, conference rooms, employee break rooms, and similar enclosed spaces require an occupancy sensor OR vacancy sensor to automatically shut off lighting. Vacancy sensors (manual-on, auto-off) are preferred because they use less energy than full occupancy sensors (auto-on). This requirement applies to all commercial occupancies."},
{id:422,mod:11,cat:"California-Specific",diff:"Medium",q:"New single-family residential construction in California under Title 24 must be 'solar ready.' What does this primarily require?",opts:["A dedicated solar zone on the roof, conduit pathways, and electrical panel capacity for future solar","Only south-facing roof orientation","An energy storage system (battery) pre-installation","Mandatory solar panel installation"],ans:0,ref:"California Title 24 Part 6 Section 110.10",exp:"Title 24 Section 110.10: Solar ready requirements for new residential construction include: (1) a solar zone (area free of obstructions) on the roof; (2) conduit pathway from solar zone to electrical panel; (3) main electrical panel with adequate capacity (often 200A minimum with space for solar disconnect). Solar panels themselves are not mandatory — the infrastructure must be ready for future installation."},
{id:423,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California Building Code (Title 24 Part 2), how many electric vehicle (EV) capable parking spaces are typically required for new single-family residential construction?",opts:["None required for residential","One EV-capable space per dwelling unit","Two EV-capable spaces per dwelling unit","One EV-ready space per 4 units"],ans:1,ref:"California Title 24 Part 2 Section 4.106.4",exp:"California requires at least one EV-capable space per new single-family dwelling. EV-capable means the electrical panel has capacity and a dedicated branch circuit rough-in to a 240V, 40A (or larger) outlet in the garage or parking area. This allows future EV charger installation without panel upgrades. Some local jurisdictions require EV-ready (with outlet installed)."},
{id:424,mod:11,cat:"California-Specific",diff:"Medium",q:"In California, what type of lighting control does Title 24 require for outdoor lighting at commercial buildings?",opts:["Manual switch only","Photocell (daylight sensor) only","Automatic controls — either an astronomical timeclock, or a photocell combined with an astronomical timeclock","Any 7-day timer is acceptable"],ans:2,ref:"California Title 24 Part 6 Section 130.2(c)",exp:"Title 24 Section 130.2(c): Outdoor lighting must be controlled by an astronomical timeclock (which uses latitude/longitude to calculate sunrise/sunset) or a photocell in conjunction with an astronomical timeclock. Simple timers or photocells alone may not meet the requirement. Outdoor lighting must also be capable of being shut off during daylight hours to conserve energy."},
{id:425,mod:11,cat:"California-Specific",diff:"Medium",q:"California's electrician certification system distinguishes between 'General' and 'Residential' electrician certifications. On which types of projects may a Residential Electrician legally work?",opts:["All residential and light commercial occupancies","Residential occupancies up to 3 stories in height only — not commercial or industrial","Any project under 200 amps service size","Any project the contractor authorizes"],ans:1,ref:"California Labor Code §3099; DIR Electrician Certification",exp:"A Residential Electrician certification in California is limited to residential occupancies up to 3 stories. General Electricians (8,000 hours) may work on all occupancy types including commercial, industrial, and residential. Performing work outside your certification scope is an enforcement violation. A Residential Electrician who takes a C-10 contracting position on a commercial project would be out of compliance."},
{id:426,mod:11,cat:"California-Specific",diff:"Medium",q:"Under Cal/OSHA regulations, which Personal Protective Equipment (PPE) is required when working on or near energized electrical equipment?",opts:["Only safety glasses and hard hat","Insulated gloves rated for the voltage, safety glasses, and appropriate arc flash protection as required by hazard analysis","Rubber-soled boots are the only mandatory requirement","PPE requirements are determined solely by the employer's discretion"],ans:1,ref:"California Title 8 CCR §3203; Cal/OSHA Electrical Safety Orders",exp:"Cal/OSHA requires appropriate PPE for electrical work including: insulated rubber gloves rated for the voltage class; safety glasses or face shield; arc-rated clothing for arc flash hazard; insulating mats or barriers where needed. A hazard analysis (similar to NFPA 70E arc flash study) determines required PPE level. Employers must provide PPE and train employees in its use."},
{id:427,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California Title 24 Part 6, what efficiency requirement applies to swimming pool and spa pumps in residential settings?",opts:["Pool pumps must use variable speed pump motor or a motor meeting minimum efficiency requirements","Single-speed 1 HP pumps are always acceptable","Pumps only need a 7-day programmable timer","No efficiency requirement for pool pumps"],ans:0,ref:"California Title 24 Part 6 Section 150.0(p)",exp:"Title 24 Section 150.0(p): New or replacement pool and spa pumps must be variable speed or two-speed pumps meeting efficiency requirements. Single-speed pumps above 1/2 HP are generally not permitted for new pools/spas. The requirement also mandates a time switch or programmable controller to reduce pump operation during peak demand periods. Variable speed pumps can save 50-70% on pump energy."},
{id:428,mod:11,cat:"California-Specific",diff:"Medium",q:"A California C-10 contractor must carry which type of insurance as a condition of the CSLB license?",opts:["Only general liability insurance","Workers' compensation insurance (or file an exemption declaration if no employees)","Both workers' comp and professional liability insurance","Only a contractor bond is required — no insurance"],ans:1,ref:"California B&P Code §7125; CSLB requirements",exp:"California B&P Code §7125: CSLB licensees must maintain workers' compensation insurance for all employees OR file a Certificate of Self-Insurance or an exemption (if they have no employees and will not employ others). Failure to maintain workers' compensation when required is automatic license suspension. Additionally, contractors must have a $25,000 bond filed with CSLB."},
{id:429,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California law, home improvement contractors must provide customers with a written contract when the job exceeds what dollar amount?",opts:["$200","$500","$750","$1,000"],ans:2,ref:"California B&P Code §7159",exp:"B&P Code §7159: Home improvement contractors must provide a written contract for projects with a combined labor and materials value of $750 or more (or whenever the contract is for future performance regardless of amount). The contract must include specific language including the contractor's license number, start/completion dates, and a notice of the homeowner's right to cancel within 3 business days."},
{id:430,mod:11,cat:"California-Specific",diff:"Medium",q:"In California, what is the maximum down payment a contractor may accept for a home improvement project?",opts:["10% of the contract price or $1,000, whichever is less","20% of the contract price","25% or $2,500, whichever is greater","No limit on down payments"],ans:0,ref:"California B&P Code §7159(d)(3)",exp:"B&P Code §7159(d)(3): For home improvement contracts, a contractor may not require a down payment exceeding 10% of the contract price or $1,000, whichever is LESS. This consumer protection prevents contractors from taking large advance payments without completing work. Exceptions may apply for special order materials."},
{id:431,mod:11,cat:"California-Specific",diff:"Medium",q:"The California Division of Apprenticeship Standards (DAS) requires electrical apprentices to complete how many hours of apprenticeship training for the IBEW/NECA Inside Wireman program?",opts:["2,000 hours","4,000 hours","10,000 hours","8,000 hours"],ans:3,ref:"California DAS; IBEW apprenticeship standards",exp:"The IBEW/NECA Inside Wireman apprenticeship in California typically requires 8,000 hours (5 years at 1,600 hours/year) of on-the-job training combined with related and supplemental instruction (RSI) classroom hours. Completion automatically qualifies the graduate for the General Electrician certification exam waiver in many cases. The DAS oversees all apprenticeship programs."},
{id:432,mod:11,cat:"California-Specific",diff:"Medium",q:"Under Cal/OSHA rules, when is an 'energized electrical work permit' required?",opts:["Only for work on systems above 600V","Only for utility work, not contractor work","Never — live work is always prohibited in California","When working within the restricted approach boundary of energized conductors above 50V when de-energizing is not feasible"],ans:3,ref:"California Title 8 CCR §2695.2; Cal/OSHA Electrical Safety",exp:"Cal/OSHA and NFPA 70E require an energized electrical work permit when: (1) it is infeasible to de-energize, (2) de-energizing creates greater hazards, or (3) management authorizes live work on systems above 50V. The permit documents the hazard analysis, required PPE, and safe work procedures. Working energized without a permit when one is required is a serious violation."},
{id:433,mod:11,cat:"California-Specific",diff:"Medium",q:"California Title 24 Part 6 requires daylighting controls in commercial buildings. In which spaces are automatic daylighting shutoff controls typically required?",opts:["No commercial spaces require automatic daylighting controls","Skylighted areas >2,500 sq ft and primary sidelighted areas where applicable","All commercial spaces greater than 1,000 sq ft","Only parking garages and warehouses"],ans:1,ref:"California Title 24 Part 6 Section 130.1(d)",exp:"Title 24 Section 130.1(d): Automatic daylighting controls are required in skylit primary sidelighted areas meeting size thresholds and in spaces with significant daylight. These controls (photocontrols or daylight sensors) automatically dim or shut off electric lighting when sufficient natural light is available. Daylighting controls significantly reduce energy consumption in commercial buildings with substantial glazing or skylights."},
{id:434,mod:11,cat:"California-Specific",diff:"Medium",q:"What is the definition of 'high-efficacy' lighting as specified in California Title 24 Energy Code?",opts:["Any LED fixture","Luminaires producing ≥45 lumens per watt","Luminaires rated Energy Star only","Fixtures producing >1,000 lumens total"],ans:1,ref:"California Title 24 Part 6 Section 100.1",exp:"California Title 24 defines high-efficacy as lighting sources producing ≥45 lumens per watt. LED technology typically exceeds this threshold (modern LEDs reach 80-120+ lumens/watt). Compact fluorescent lamps (CFLs) may also qualify depending on wattage. Incandescent and standard halogen lamps generally do NOT meet the high-efficacy threshold and cannot be used where required."},
{id:435,mod:11,cat:"California-Specific",diff:"Medium",q:"Under the California Electrical Code, AFCI (Arc Fault Circuit Interrupter) protection requirements apply in dwelling units. Which of the following most accurately reflects the California AFCI requirement?",opts:["Only bedrooms require AFCI — identical to older NEC editions","All 120V, 15A and 20A branch circuits in dwelling units require AFCI protection per California CEC amendments","AFCI is not required in California — GFCI replaces it","Only circuits installed after 2020 need AFCI"],ans:1,ref:"California Electrical Code (2022 CEC) based on 2023 NEC with amendments",exp:"The California Electrical Code adopts NEC AFCI requirements and in many cases California amendments expand requirements. The 2022 CEC requires combination-type AFCI protection for 120V, 15A and 20A branch circuits in all habitable rooms and areas of dwelling units. This is broader than some earlier NEC editions. Always verify the specific adopted edition in the jurisdiction where work is performed."},
{id:436,mod:11,cat:"California-Specific",diff:"Medium",q:"A California contractor performs work on a project without a valid C-10 license. Under B&P Code Section 7028, this is a _____ and the contractor may not _____ the contract.",opts:["Felony; terminate","Administrative violation; bid on","Civil infraction; modify","Misdemeanor; enforce (collect payment on)"],ans:3,ref:"California B&P Code §7028 & §7031",exp:"B&P Code §7028: Unlicensed contracting is a misdemeanor punishable by imprisonment and fines. B&P Code §7031: A contractor without a proper license may not bring or maintain an action for compensation for work requiring a license — effectively the unlicensed contractor cannot sue to collect payment. This is a consumer protection designed to deter unlicensed contracting."},
{id:437,mod:11,cat:"California-Specific",diff:"Medium",q:"California Title 24 Part 6 mandates what type of control for interior lighting in commercial office spaces?",opts:["Photocell-only controls","No requirements for office lighting controls","Manual dimmer switches on all circuits","Automatic scheduling and occupancy sensing to reduce power during unoccupied periods"],ans:3,ref:"California Title 24 Part 6 Section 130.1",exp:"Title 24 Section 130.1 requires multi-level occupancy sensing, daylighting control where applicable, and scheduling controls for commercial office lighting. Lighting must automatically reduce power in unoccupied areas and respond to daylight availability. These controls substantially reduce commercial building energy use. The specific control requirements depend on space type, size, and daylighting."},
{id:438,mod:11,cat:"California-Specific",diff:"Medium",q:"In California, which agency enforces workplace electrical safety requirements on construction sites?",opts:["CSLB","DIR/DOSH (Cal/OSHA)","California Energy Commission","Department of Buildings and Safety"],ans:1,ref:"California Labor Code §6300-6450; Cal/OSHA",exp:"Cal/OSHA (the Division of Occupational Safety and Health, DOSH, within the DIR) enforces workplace safety including electrical safety on construction sites. Cal/OSHA can conduct inspections, issue citations, and impose fines for violations of Title 8 electrical safety orders. Employers must comply with Cal/OSHA requirements independently of NEC compliance. CSLB handles licensing; Cal/OSHA handles safety."},
{id:439,mod:11,cat:"California-Specific",diff:"Medium",q:"Under California Title 24 energy code, permanently installed outdoor lighting for residential buildings must comply with efficiency requirements. What is a permitted control method for outdoor residential lighting?",opts:["Manual switch with no automatic shutoff","Photocontrol turning lights off during daylight hours","Any timer set by the owner","No requirements for outdoor residential lighting"],ans:1,ref:"California Title 24 Part 6 Section 150.0(k)(2)",exp:"Title 24 Section 150.0(k)(2): Outdoor residential lighting must be controlled by a motion sensor plus a photocontrol, or a photocontrol plus timer, or an astronomical timeclock. A photocontrol alone (turning lights on at dusk, off at dawn) meets the basic requirement. The goal is to prevent outdoor lighting from operating during daylight and to reduce unnecessary nighttime operation."},
{id:440,mod:11,cat:"California-Specific",diff:"Medium",q:"What is the California contractor bond amount required for CSLB licensees?",opts:["$5,000","$15,000","$25,000","$50,000"],ans:2,ref:"California B&P Code §7071.6",exp:"California B&P Code §7071.6: All CSLB licensees must file and maintain a contractor's bond of $25,000 with the CSLB. This bond protects consumers and employees from contractor non-performance or fraud. If a consumer or employee has a valid claim against the contractor, they may make a claim against the bond. The bond is separate from liability insurance and workers' compensation."},
{id:441,mod:11,cat:"California-Specific",diff:"Medium",q:"Which entity enforces the California Energy Code (Title 24 Part 6) at the project level?",opts:["California Energy Commission directly","CSLB inspectors","Local building department — through plan check and inspections","Cal/OSHA"],ans:2,ref:"California Title 24 Part 6 Enforcement",exp:"The California Energy Code is enforced by local building departments through plan check (review of energy compliance documents) and field inspections. Title 24 compliance documentation (CF-1R, CF-2R forms) must be submitted and approved. The California Energy Commission (CEC) writes and adopts the Energy Code; local building departments enforce it. Energy inspectors verify lighting controls, equipment, and documentation."},
{id:442,mod:11,cat:"California-Specific",diff:"Medium",q:"For new commercial construction in California, what does Title 24 require regarding EV charging infrastructure in parking facilities?",opts:["All commercial parking must have Level 2 chargers installed","Only charging for fleet vehicles is required","No EV requirements for commercial parking","EV-capable spaces (conduit and panel capacity) based on total parking space count"],ans:3,ref:"California Title 24 Part 2 Section 4.106.4",exp:"California Title 24 Part 2 (Building Code) requires new commercial construction to provide EV-capable (conduit stub-out and panel capacity reserved) spaces based on a percentage of total parking spaces. Specific percentages vary by project type and size. EV-capable means the infrastructure for future charger installation is in place without requiring immediate charger installation."},
{id:443,mod:11,cat:"California-Specific",diff:"Hard",q:"Under California Title 24, what is the required minimum electrical panel capacity for a new single-family home to qualify as 'solar ready'?",opts:["100A service minimum","150A service minimum","200A service minimum with space for a solar breaker","125A service with dedicated solar conduit"],ans:2,ref:"California Title 24 Part 6 Section 110.10(b)",exp:"Title 24 Section 110.10(b): For new residential solar ready construction, the main electrical panel must have a minimum rating of 200 amperes AND contain a reserved space for a future solar interconnection circuit breaker. The conduit stub-out from the panel to the roof zone must also meet minimum sizing requirements. This ensures future solar can be added without a panel upgrade."},
{id:444,mod:11,cat:"California-Specific",diff:"Hard",q:"California Title 24 Part 6 sets Indoor Lighting Power Density (LPD) limits for commercial buildings. What is the consequence of exceeding the LPD limit in the design?",opts:["The design fails energy compliance and cannot receive a building permit","Extra lighting is permitted if offset by HVAC savings","LPD limits only apply to government buildings","Only a warning — no enforcement consequence"],ans:0,ref:"California Title 24 Part 6 Section 140.6",exp:"Title 24 Section 140.6 sets mandatory maximum allowed LPD (watts per square foot) by occupancy type. A lighting design exceeding the LPD limit fails energy compliance. The project cannot receive a building permit without either reducing the installed wattage, adding automatic controls that reduce effective LPD, or using the Performance Method to show overall energy compliance. LPD compliance is verified during plan check."},
{id:445,mod:11,cat:"California-Specific",diff:"Hard",q:"In California, a qualified worker encounters energized 480V equipment that cannot be de-energized. Before beginning work, what must be established?",opts:["An energized electrical work permit documenting hazard analysis, PPE requirements, and safe work procedures must be completed","The worker must notify CSLB before proceeding","Standard PPE (hard hat and safety glasses) is sufficient if the worker is experienced","The worker may proceed using rubber gloves — no permit needed"],ans:0,ref:"Cal/OSHA Title 8 §2695.2; NFPA 70E Article 130",exp:"When work must be performed while energized at voltages above 50V, Cal/OSHA requires: (1) justification that de-energizing is infeasible or creates greater hazards; (2) an energized work permit documenting the hazard analysis; (3) appropriate PPE based on incident energy analysis or PPE category method; (4) qualified workers trained for the task. The permit must be approved by management before work begins."},
{id:446,mod:11,cat:"California-Specific",diff:"Hard",q:"California Labor Code Section 3099 makes electrician certification mandatory for commercial and industrial work. Which category of workers is specifically required to hold certification?",opts:["All workers who touch electrical equipment","Journey-level electricians and apprentices performing work on commercial and industrial projects","Only foremen and supervisors","Contractors (license holders) but not their employees"],ans:1,ref:"California Labor Code §3099",exp:"Labor Code §3099: Certification is mandatory for all journey-level electricians and apprentices performing commercial or industrial electrical work in California. Uncertified workers performing such work violate the law. Residential Electrician certification covers residential work. Contractors (C-10 license holders) still need their employees to hold individual certifications — the contractor license doesn't exempt employees from personal certification requirements."},
{id:447,mod:11,cat:"California-Specific",diff:"Hard",q:"The California Electrical Code includes an amendment regarding GFCI protection for dwelling unit kitchens. Which of the following reflects CEC requirements for kitchen receptacle circuits?",opts:["All 125V, 15A and 20A receptacles in dwelling unit kitchen areas require GFCI protection per the adopted NEC/CEC requirements","GFCI is only required if the kitchen is within 10 feet of a pool","Kitchen GFCI is optional if AFCI is installed","Only receptacles within 6 feet of a sink need GFCI"],ans:0,ref:"CEC 210.8(A)(6) based on 2023 NEC",exp:"Per CEC (adopting 2023 NEC) Section 210.8(A)(6): GFCI protection is required for all 125V, 15A and 20A receptacles in dwelling unit kitchen areas. The 2023 NEC expanded the kitchen GFCI requirement to cover ALL receptacles in the kitchen (not just those near sinks as in earlier NEC editions). This is one area where California's adoption of the latest NEC may provide broader protection than older adopted editions."},
{id:448,mod:11,cat:"California-Specific",diff:"Hard",q:"California Title 24 requires 'demand response' capability for certain HVAC and lighting systems in new commercial construction. What does demand response capability mean in this context?",opts:["The system automatically shuts down during power outages","The system can automatically reduce power consumption by a set percentage in response to a utility signal during peak demand events","Systems must be controllable only by utility employees","Demand response requires battery backup storage"],ans:1,ref:"California Title 24 Part 6 Section 120.2(i)",exp:"Title 24 Section 120.2(i): New HVAC systems and certain lighting systems must be capable of automatic demand response — meaning they can receive a signal (via OpenADR protocol or similar) from the utility and automatically reduce consumption during peak demand or grid emergency events. This might include pre-cooling before a demand event, reducing lighting power density by 10-15%, or cycling equipment. Demand response helps California avoid grid emergencies."},
{id:449,mod:11,cat:"California-Specific",diff:"Hard",q:"Under California regulations, when must an electrical permit be obtained before beginning electrical work?",opts:["Permits are the owner's responsibility, not the contractor's","Only new construction requires permits — repair work is permit-exempt","Only for commercial work over $50,000","Permits are required for most electrical installations and replacements — the contractor must obtain the permit before starting work"],ans:3,ref:"California Building Code Section 105; Local jurisdiction requirements",exp:"Most electrical work in California requires a permit before work begins. The PERMIT must be obtained BEFORE starting work, not after. Permit requirements apply to new construction, additions, alterations, and most repairs. Permits are obtained from the local building/development services department. The permit holder (usually the licensed contractor) is responsible for requesting inspections. 'Unpermitted work' creates liability, may not be insurable, and can affect property sales."},
{id:450,mod:11,cat:"California-Specific",diff:"Hard",q:"A California electrician performing high-voltage (over 600V) work must hold which additional certification?",opts:["A specialized High Voltage Certification issued by DIR is required for conductors above 600V","Only a union card is required for high-voltage work","High voltage work requires CSLB C-10 license only — no separate certification","The General Electrician certification is sufficient for all voltages"],ans:0,ref:"California Labor Code §3099; DIR High Voltage Certification",exp:"California requires a separate High Voltage Certification from DIR for electricians working on systems above 600V. This is in addition to the General Electrician certification. High voltage work carries significantly greater risks, and the HV certification requires additional training and testing specifically covering high voltage systems, protective equipment, and safety procedures. The HV certification is required for transmission and distribution work, medium voltage feeders, and similar systems."},
{id:451,mod:11,cat:"California-Specific",diff:"Hard",q:"Under California Title 24 Part 6, what must be installed in new residential buildings that have solar photovoltaic (PV) systems?",opts:["A battery storage system is mandatory with solar","A minimum 100-amp solar-ready subpanel","A solar export meter only","The PV system must comply with CEC rules including a listed inverter, interconnection per Rule 21, and compliance with local utility interconnection requirements"],ans:3,ref:"California Title 24 Part 6 & CPUC Rule 21; NEC Article 690",exp:"Solar PV systems in California must comply with: NEC Article 690 (as adopted in CEC); local utility interconnection requirements under CPUC Rule 21 (net metering); local building department requirements; and Title 24 Part 6 energy compliance. The inverter must be listed and UL-listed for grid connection. Net metering (NEM) agreements with the utility allow credit for excess generation. The 2023 NEC Article 690 and California's Rule 21 requirements govern these systems."},
{id:452,mod:11,cat:"California-Specific",diff:"Hard",q:"A Cal/OSHA inspection finds an electrical contractor working on a commercial project with uncertified journey-level workers. Which of the following potential consequences is correct?",opts:["No consequence — certification is voluntary","Only the individual uncertified worker faces penalties","Cal/OSHA can cite the employer, impose fines, and require correction; DIR can take action against the contractor's CSLB license","The building department stops the project — Cal/OSHA has no authority over licensing"],ans:2,ref:"California Labor Code §3099; Cal/OSHA Title 8",exp:"Multiple agencies can act: (1) Cal/OSHA can cite the employer for allowing uncertified workers to perform electrical work — this is a safety violation; (2) DIR can take enforcement action against the certification program violators; (3) CSLB can investigate the C-10 contractor for allowing uncertified labor; (4) Stop Work Orders may be issued. California takes electrician certification very seriously as a safety measure."},
{id:453,mod:11,cat:"California-Specific",diff:"Hard",q:"California's Zero Emission Vehicle (ZEV) regulations affect new construction electrical requirements. What does Title 24 generally require regarding ZEV infrastructure in new multifamily residential buildings?",opts:["A percentage of parking spaces must have EV-capable, EV-ready, or EVSE-installed infrastructure based on the number of units","Only accessible parking spaces need EV infrastructure","ZEV charging stations must be installed and operational before occupancy","No ZEV requirements for multifamily — only single-family"],ans:0,ref:"California Title 24 Part 2 Section 4.106.4; California Building Code",exp:"California Title 24 Part 2 requires new multifamily residential construction to provide EV infrastructure across a percentage of parking spaces, graduated by parking space count. Requirements include EV-capable spaces (conduit stub-out), EV-ready spaces (with 240V outlet), and EVSE spaces (with charger installed). Specific percentages depend on total parking spaces. The goal is to build EV infrastructure into new construction rather than retrofit it later."},
{id:454,mod:11,cat:"California-Specific",diff:"Hard",q:"Under the 2022 California Electrical Code, what overcurrent protection is required for ALL 120V branch circuits in habitable rooms of a dwelling unit?",opts:["No special protection required — standard breakers are sufficient","GFCI and AFCI both on the same circuit are required","GFCI protection only","AFCI protection (combination-type) for all 120V, 15A and 20A branch circuits"],ans:3,ref:"CEC 210.12(A) (2022 CEC / 2023 NEC base)",exp:"The 2022 CEC (based on 2023 NEC) requires combination-type AFCI breaker or outlet for ALL 120V, 15A and 20A branch circuits in dwelling units in areas specified by Section 210.12(A). This includes bedrooms, living rooms, dining rooms, family rooms, parlors, libraries, dens, sunrooms, recreation rooms, closets, hallways, laundry areas, and similar rooms. AFCI prevents arc fault fires which are a leading cause of residential electrical fires."},
{id:455,mod:11,cat:"California-Specific",diff:"Hard",q:"What is the primary difference between the California Public Utilities Commission's (CPUC) Rule 21 and the NEC Article 690 as they apply to solar PV interconnection?",opts:["Rule 21 governs the utility interconnection agreement and metering requirements for grid-connected systems; NEC 690 governs the design and installation safety requirements","Rule 21 replaces NEC 690 in California","Article 690 supersedes Rule 21 for all California installations","Rule 21 and Article 690 are identical documents"],ans:0,ref:"CPUC Rule 21; NEC Article 690",exp:"NEC Article 690 covers the safe design and installation of solar PV systems (wiring methods, disconnects, grounding, inverters). CPUC Rule 21 is the California utility interconnection tariff that governs how PV systems connect to the utility grid — metering, anti-islanding, export limitations, net metering agreements, and interconnection approval. Both apply: Article 690 = installation safety; Rule 21 = grid connection rules. The electrical inspector verifies 690; the utility verifies Rule 21 compliance before energizing."},
{id:456,mod:11,cat:"California-Specific",diff:"Hard",q:"California requires electrical contractors to maintain what documentation on a job site?",opts:["A copy of the building permit, plans approved by the AHJ, and evidence of required inspections — available for inspection on site","No on-site documentation is required","CSLB certificate of qualification must be posted in the main electrical room","Only the contractor's license number posted"],ans:0,ref:"California Building Code Section 105.7; Local requirements",exp:"California law requires that a copy of the building permit AND the approved plans be kept on the job site and available for inspection by the building official at all times. The permit card must be posted in a conspicuous location. Inspection records must be maintained. Not having permit documentation on site can result in a stop work order. Additionally, the contractor's CSLB license number must appear on all contracts, bids, permits, and advertising."},
{id:457,mod:11,cat:"California-Specific",diff:"Hard",q:"Under California Labor Code Section 3099.2, what is the consequence for a California electrical contractor (C-10) who employs uncertified electricians on a commercial project?",opts:["Only the uncertified employee is subject to a fine","The contractor may face CSLB disciplinary action including license suspension or revocation, in addition to civil and criminal penalties","No legal consequence — certification is the employee's responsibility only","Only a warning letter from DIR for first offense"],ans:1,ref:"California Labor Code §3099.2; B&P Code §7090",exp:"Labor Code §3099.2 makes it the responsibility of BOTH the individual worker AND the employer contractor to ensure certification requirements are met. A C-10 contractor who knowingly employs uncertified workers on commercial work can face: (1) DIR civil penalties; (2) CSLB disciplinary action including license suspension or revocation under B&P Code §7090; (3) potential criminal liability. Contractors must verify certification before assigning workers to certified-work assignments."},
// MODULE 12: SAFETY, MAINTENANCE & REPAIR (55)
{id:458,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"According to NEC Section 90.1, what is the primary purpose of the National Electrical Code?",opts:["Ensuring electrical system efficiency","The practical safeguarding of persons and property from hazards arising from the use of electricity","Standardizing electrical equipment for commercial trade","Maximizing the use of electrical energy"],ans:1,ref:"NEC 90.1(A)",exp:"NEC 90.1(A): 'The purpose of this Code is the practical safeguarding of persons and property from hazards arising from the use of electricity.' The NEC is NOT a design guide, nor is it intended for efficiency or convenience. It sets minimum safety standards. Going beyond NEC minimums is encouraged but not required by the Code itself."},
{id:459,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"What is the minimum working space depth (clear distance) in front of electrical equipment rated 0-150V under NEC 110.26(A)(1) Condition 1?",opts:["36 inches (900 mm)","48 inches","18 inches","24 inches"],ans:0,ref:"NEC 110.26(A)(1)(1) Condition 1",exp:"110.26(A)(1)(1) Table: For equipment 0-150V, Condition 1 (no exposed live parts on opposite side) = 900 mm (3 ft / 36 in.) minimum depth. Conditions 2 and 3 require more space. These minimums ensure workers can safely operate, maintain, and service equipment without inadvertent contact with live parts."},
{id:460,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"Who is the only person authorized to remove a lockout/tagout device?",opts:["The supervisor or foreman","Any journeyman electrician on the project","Only the employee who applied the device (except in documented emergency exceptions)","The safety officer upon request"],ans:2,ref:"California Title 8 CCR §3314(b)(8); OSHA 29 CFR 1910.147",exp:"LOTO rules require that only the employee who applied a lockout/tagout device may remove it. This prevents inadvertent re-energization while another worker is still in the danger zone. In documented emergencies where the authorized employee is unavailable, a specific written procedure allows supervisor removal — but only with documented steps including verification the employee is safely clear."},
{id:461,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"What does PPE stand for in electrical safety?",opts:["Personal Protective Equipment","Power Plant Engineering","Protective Power Equipment","Personnel Protection Evaluation"],ans:0,ref:"NFPA 70E Article 100; Cal/OSHA Title 8",exp:"PPE = Personal Protective Equipment. In electrical work, PPE includes: voltage-rated rubber insulating gloves, leather protector gloves, arc flash face shield or hood, arc-rated (FR) clothing, hard hat, safety glasses, and insulating footwear. The specific PPE required depends on the hazard level determined by a risk assessment or arc flash study."},
{id:462,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"NEC Section 110.2 requires that electrical equipment used on a project shall be _____ for the application.",opts:["The cheapest available","Approved","Labeled by the manufacturer","Rated for 120% of expected load"],ans:1,ref:"NEC 110.2",exp:"110.2: 'The conductors and equipment required or permitted by this Code shall be acceptable only if approved.' Approved means acceptable to the authority having jurisdiction (AHJ). Listing by a nationally recognized testing laboratory (NRTL) such as UL is the most common way to show approval. The AHJ can also approve unlisted equipment on a case-by-case basis."},
{id:463,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"At approximately what ground fault current does a GFCI device trip to protect against electrocution?",opts:["15 amperes","1 ampere","4 to 6 milliamperes","50 milliamperes"],ans:2,ref:"NEC 210.8; UL 943",exp:"GFCI devices trip at 4-6 milliamperes (0.004-0.006A) of ground fault current. Human ventricular fibrillation threshold is approximately 50-100 mA, so GFCI protection at 4-6 mA provides a wide safety margin. GFCI does NOT protect against line-to-line shock (person touching both conductors), only line-to-ground faults."},
{id:464,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"Before using a voltage tester or multimeter to test a circuit for voltage, what is the first safety step?",opts:["Verify the meter itself is working and rated for the expected voltage using a known live source","Call the supervisor","Check the meter battery","Turn off the breaker first"],ans:0,ref:"NFPA 70E 110.4(A); Cal/OSHA electrical safety",exp:"Before testing: (1) Verify the test instrument is rated for the voltage class (CAT rating and voltage rating). (2) Verify the meter functions by testing it on a known live source. (3) Then test the circuit. Using a faulty or underrated meter can result in arc flash or shock. The old rule: 'Is it alive? Is it dead? Is it alive?' — test live, test dead, test live again to verify."},
{id:465,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"NEC Section 110.12 requires electrical work to be performed in a _____.",opts:["Neat and workmanlike manner","Method approved by the IBEW","Way that minimizes material cost","Code-minimum manner"],ans:0,ref:"NEC 110.12",exp:"110.12: 'Electrical equipment shall be installed in a neat and workmanlike manner.' The NEC requires quality workmanship beyond just meeting minimum technical requirements. Cables must be supported, connections made properly, equipment mounted securely, and the installation must not create unnecessary hazards. This section gives the AHJ authority to reject poor-quality work even if it technically meets other Code requirements."},
{id:466,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"The Authority Having Jurisdiction (AHJ) is defined in NEC Article 100. Which entity typically serves as the AHJ for electrical installations?",opts:["The NEC code panel","The electrical contractor","The local building department or electrical inspector","The utility company"],ans:2,ref:"NEC Article 100; 90.4",exp:"The AHJ is the organization, office, or individual responsible for enforcing the Code. In most localities, the AHJ is the local building department, fire marshal, or electrical inspection authority. The AHJ has authority to approve equipment, materials, and methods. NEC 90.4: 'The authority having jurisdiction shall have the authority to render interpretations of this Code.'"},
{id:467,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"NEC Section 110.26(E)(1) establishes dedicated electrical space above panelboards and switchboards. What is NOT permitted within this dedicated space?",opts:["Bus duct feeders","Service entrance cables","Plumbing, pipes, ducts, or equipment not part of the electrical installation","Additional panelboards stacked above"],ans:2,ref:"NEC 110.26(E)(1)",exp:"110.26(E)(1): The space equal to the width and depth of the electrical equipment extending from the floor to a height of 1.8 m (6 ft) above the equipment or to the structural ceiling, whichever is lower, shall be dedicated to the electrical installation. NO piping, ducts, leak protection devices, or equipment foreign to the electrical installation shall be installed in this zone. Leaking pipes above electrical panels are a common code violation."},
{id:468,mod:12,cat:"Safety & Maintenance",diff:"Easy",q:"NEC 110.16(B) requires that electrical equipment likely to require examination or servicing while energized shall be field-marked with what type of warning?",opts:["A high voltage sign","A manufacturer's nameplate only","A yellow caution sticker","An arc flash hazard warning label"],ans:3,ref:"NEC 110.16(B)",exp:"110.16(B): Switchboards, switchgear, panelboards, industrial control panels, and similar equipment that are in other than dwelling units and are likely to require examination, adjustment, servicing, or maintenance while energized shall be field-marked with a label warning of arc flash hazard. This alerts workers to the need for an arc flash hazard analysis and appropriate PPE before working on the equipment."},
{id:469,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"For equipment rated 151-600V, NEC 110.26(A)(1) Condition 2 (exposed live parts on one side, grounded or insulated parts on other) requires a minimum working space depth of _____.",opts:["1.5 m (5 ft)","0.9 m (3 ft)","900 mm (3 ft)","1.2 m (4 ft)"],ans:3,ref:"NEC Table 110.26(A)(1)",exp:"Table 110.26(A)(1): For 151-600V equipment, Condition 2 = 1.2 m (4 ft) minimum working space depth. Condition 1 = 900 mm (3 ft); Condition 3 = 1.5 m (5 ft). Condition 3 applies when exposed live parts exist on BOTH sides of the working space. Select the condition matching the actual installation to determine required clearance."},
{id:470,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What is the minimum width of the working space in front of electrical equipment per NEC 110.26(A)(2)?",opts:["18 inches","24 inches","762 mm (30 in.) or the width of the equipment — whichever is greater","600 mm (24 in.)"],ans:2,ref:"NEC 110.26(A)(2)",exp:"110.26(A)(2): The width of the working space shall be the width of the equipment or 762 mm (30 in.), whichever is greater. This minimum ensures a worker has adequate lateral space to work. For a 24-inch wide panelboard, the working space must still be 30 inches wide (not just 24 inches). Measured from the centerline of the equipment when equipment is narrower than 30 inches."},
{id:471,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What is the minimum headroom height for working space about electrical equipment per NEC 110.26(A)(3)?",opts:["6 feet (1.8 m)","6.5 feet (2.0 m)","7 feet (2.1 m)","5.5 feet (1.7 m)"],ans:1,ref:"NEC 110.26(A)(3)",exp:"110.26(A)(3): The minimum headroom for working space about service equipment, switchboards, switchgear, panelboards, or motor control centers shall be 2.0 m (6.5 ft). Exception: in existing dwelling units, service equipment or panelboards in spaces with a headroom of not less than 1.8 m (6 ft) shall be permitted. The 6.5 ft requirement allows a worker to stand upright while working."},
{id:472,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What is the correct sequence for a Lockout/Tagout (LOTO) procedure?",opts:["Verify, apply LOTO, shut down, release stored energy, notify","Identify energy, release stored energy, apply LOTO, notify, verify, shut down","Apply LOTO, shut down, notify, verify, release stored energy","Notify affected employees, identify energy sources, shut down equipment, isolate energy, apply LOTO, release stored energy, verify de-energized"],ans:3,ref:"California Title 8 CCR §3314; OSHA 29 CFR 1910.147",exp:"Correct LOTO sequence: (1) Notify affected employees; (2) Identify ALL energy sources (electrical, pneumatic, hydraulic, gravity); (3) Shut down equipment using normal stopping procedure; (4) Isolate energy at each energy isolation point; (5) Apply LOTO devices; (6) Release/restrain stored energy (discharge capacitors, bleed pneumatic systems, block gravity loads); (7) Verify de-energized (attempt start, use meter to verify zero voltage)."},
{id:473,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"The arc flash boundary is the distance from an arc source where an unprotected worker could receive _____.",opts:["Any electrical shock","A lethal electric shock","An onset of second-degree burns (1.2 cal/cm² incident energy threshold)","A fatal arc blast"],ans:2,ref:"NFPA 70E Article 100; 130.5(B)",exp:"Arc flash boundary = the distance at which incident energy equals 1.2 cal/cm², the threshold for onset of a curable second-degree burn on bare skin. Workers within the arc flash boundary must wear arc-rated PPE with a rating exceeding the calculated incident energy. Arc flash analysis (per NFPA 70E or IEEE 1584) determines the specific boundary distance for each piece of equipment."},
{id:474,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"In NFPA 70E, the 'limited approach boundary' is established to protect against _____.",opts:["Arc flash thermal energy only","Shock hazard — it is the closest distance an unqualified person may approach an exposed energized electrical conductor without an escort","Equipment damage","Radio frequency interference"],ans:1,ref:"NFPA 70E 130.4(D)",exp:"The limited approach boundary is the shock protection boundary for unqualified persons. Unqualified persons may not cross this boundary without an escort by a qualified person and implementation of appropriate safeguards. The restricted approach boundary (closer in) is for qualified persons only — crossing requires PPE and specific safe work practices. These boundaries are tabulated in NFPA 70E Table 130.4(D)(a) based on voltage."},
{id:475,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"When is an energized electrical work permit required?",opts:["When working on or near energized parts at 50V or greater and de-energizing is not feasible, increases risk, or is infeasible","Only when the employer's safety manager requires one","Whenever working within 10 feet of any electrical equipment","Only for high voltage work above 600V"],ans:0,ref:"NFPA 70E 130.2; Cal/OSHA Title 8 §2695.2",exp:"An energized work permit is required when work is performed on or near energized conductors or circuit parts at 50V or above and: (1) de-energizing is not feasible, (2) de-energizing introduces additional hazards, or (3) it is impossible due to equipment design or operational limitations. The permit documents the justification, required PPE, safe work procedures, and must be authorized by management before work begins."},
{id:476,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"Per NEC 110.26(C), switchboards, switchgear, and motor control centers in other than dwelling units must have how many entrances/exits when the equipment bus is over 1200 A and 6 feet wide or long?",opts:["One entrance minimum","Two entrances, one at each end of the working space","Three entrances","At least one plus an emergency exit"],ans:1,ref:"NEC 110.26(C)(2)",exp:"110.26(C)(2)(a): For switchboards, switchgear, and MCCs rated over 1,200A and over 1.8 m (6 ft) wide containing overcurrent or control devices, there shall be one entrance to the required working space at each end of the equipment. This provides an emergency escape route in case of arc flash or fire — a worker cannot be trapped with only one exit."},
{id:477,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What test instrument is used to measure insulation resistance for detecting deteriorated wiring insulation?",opts:["Clamp-on ammeter","Digital multimeter on resistance setting","Megohmmeter (megger)","Oscilloscope"],ans:2,ref:"NFPA 70B (maintenance); Cal/OSHA maintenance practices",exp:"A megohmmeter (megger) applies a high DC voltage (typically 500V or 1,000V) and measures insulation resistance in megaohms. Low insulation resistance indicates moisture, contamination, or damaged insulation — potential shock and fire hazards. Standard multimeters cannot perform this test (they use too low a voltage to stress the insulation). Megohmmeter testing is part of preventive electrical maintenance programs."},
{id:478,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"Voltage-rated rubber insulating gloves are classified by voltage rating. A Class 1 glove is rated for use up to _____.",opts:["500V AC","1,000V AC","7,500V AC","10,000V AC"],ans:2,ref:"ASTM D120; NFPA 70E 130.7(C)(7)(a)",exp:"Rubber insulating glove classes: Class 00 = 500V AC; Class 0 = 1,000V AC; Class 1 = 7,500V AC; Class 2 = 17,000V AC; Class 3 = 26,500V AC; Class 4 = 36,000V AC. The proof test voltage is higher than the use voltage. Always use leather protector gloves over rubber insulating gloves to prevent mechanical damage. Inspect gloves before each use — air-inflate to check for holes."},
{id:479,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What does thermographic (infrared) scanning detect in electrical equipment?",opts:["Ground faults","Overloaded or loose connections that generate excess heat before failure occurs","Insulation breakdown","Arc faults"],ans:1,ref:"NFPA 70B; Cal/OSHA preventive maintenance",exp:"Infrared thermography detects hot spots in electrical equipment caused by: loose connections (high resistance generates heat), overloaded circuits, failing components, or unbalanced loads. Regular IR scanning is a preventive maintenance practice that catches problems before they cause fires, equipment damage, or outages. IR scanning is performed while equipment is operating under load, making it a non-invasive technique."},
{id:480,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"NEC Section 110.27(A) requires that live parts of electrical equipment operating at _____ or more shall be guarded against accidental contact.",opts:["15V","50V","120V","30V"],ans:1,ref:"NEC 110.27(A)",exp:"110.27(A): Live parts of electrical equipment operating at 50 volts or more shall be guarded against accidental contact by approved enclosures, by location in a room accessible only to qualified persons, by suitable permanent, substantial partitions or screens, or by elevation. The 50V threshold aligns with the threshold used for shock hazard definitions in NFPA 70E."},
{id:481,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"NEC Section 110.3(A) and (B) requires equipment to be installed according to _____.",opts:["The lowest cost method","Any method the electrician prefers","Instructions included with listed or labeled equipment","NEC alone — manufacturer instructions are suggestions"],ans:2,ref:"NEC 110.3(B)",exp:"110.3(B): Listed or labeled equipment shall be installed and used in accordance with any instructions included in the listing or labeling. This is a critical requirement — manufacturer's installation instructions become Code requirements via 110.3(B). Using equipment outside its listed rating or not following installation instructions is a Code violation even if nothing else in the NEC specifically prohibits it."},
{id:482,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"A clamp-on ammeter (clamp meter) is used to measure current. What is its primary advantage over a standard multimeter?",opts:["Can measure current without disconnecting the circuit — just clamp around one conductor","Measures all three phases simultaneously","Works on DC circuits only","More accurate readings"],ans:0,ref:"Electrical testing best practices",exp:"A clamp-on ammeter measures current by sensing the magnetic field around a conductor — no circuit disconnection required. This is a major safety advantage (no need to open the circuit) and a practical advantage (can measure in live circuits). For accurate AC current readings, only ONE conductor should be in the clamp jaw. If both legs of a circuit are clamped, the fields cancel and read zero."},
{id:483,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"A test instrument's category rating (CAT II, CAT III, CAT IV) indicates what?",opts:["The instrument's accuracy class","The voltage range the instrument is designed for","The overvoltage protection level and the part of the electrical system where the instrument may be safely used","The battery life of the instrument"],ans:2,ref:"IEC 61010; NFPA 70E 110.4(A)",exp:"CAT ratings indicate the transient overvoltage protection: CAT II = single-phase receptacle outlets, CAT III = distribution level (panelboards, branch circuits, commercial/industrial outlets), CAT IV = service entrance, utility primary side. Higher CAT = more protection against voltage spikes. Using a CAT II meter at the service entrance (CAT IV environment) is dangerous — the meter can explode on transient overvoltage. Always use the correct CAT-rated instrument."},
{id:484,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"NEC 110.14(A) requires electrical connections to be made with _____.",opts:["Listed pressure connectors, solder, or other listed means — aluminum conductors must use connectors identified for aluminum","Copper connectors for all conductors regardless of material","Only compression-type connectors","Any available hardware"],ans:0,ref:"NEC 110.14(A)",exp:"110.14(A): Terminals for connection of conductors shall be listed for the material of the conductor and shall be identified for the conductor size. Aluminum conductors require connectors identified for aluminum (typically marked AL, CU-AL, or Al9Cu). Aluminum in connectors rated for copper only causes oxidation, high resistance, and fire hazard. Anti-oxidant compound may be required for aluminum connections."},
{id:485,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What is the NEC minimum working clearance for equipment rated 601-2,500V under Condition 1 (no exposed live parts on opposite side)?",opts:["1.8 m (6 ft)","2.5 m (8 ft)","900 mm (3 ft)","1.2 m (4 ft)"],ans:3,ref:"NEC Table 110.34(A) Condition 1",exp:"NEC Table 110.34(A) for over 1,000V: Condition 1 (601-2,500V) = 1.2 m (4 ft). Condition 2 = 1.5 m (5 ft). Condition 3 = 1.8 m (6 ft). For 2,501-9,000V Condition 1 = 1.5 m (5 ft). Higher voltage = more required clearance. These larger clearances recognize the increased arc hazard and potential for flashover at higher voltages."},
{id:486,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"After energizing a repaired circuit, what is the proper procedure before returning equipment to service?",opts:["Have the apprentice test it first","Replace all circuit breakers as a precaution","Immediately restore normal operations","Test the circuit for proper voltage, verify all connections, confirm proper operation, and check for fault indicators"],ans:3,ref:"NFPA 70B; Cal/OSHA return to service procedures",exp:"After repair and before returning to service: (1) Perform visual inspection of all connections; (2) Test for proper voltage at all points; (3) Verify equipment operates as intended; (4) Check for fault indicators (tripped breakers, blown fuses, abnormal heat); (5) Restore monitoring systems; (6) Notify affected personnel. This systematic approach prevents energizing with latent defects that could cause immediate failure or delayed hazards."},
{id:487,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"NEC 230.95 requires ground fault protection of equipment (GFPE) for solidly grounded wye services at what voltage and current threshold?",opts:["Any service over 100A","120V services only","277/480V 3-phase services with 1,000A or more","Any commercial service over 600A"],ans:2,ref:"NEC 230.95(A)",exp:"230.95(A): Ground fault protection of equipment shall be provided for solidly grounded wye services of more than 150 volts to ground but not exceeding 600 volts phase-to-phase, for each service disconnecting means rated 1,000 amperes or more. This applies to 277/480V 3-phase (wye) systems. Purpose: detect low-level ground faults (too small to trip overcurrent protection) that can cause catastrophic fires."},
{id:488,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"For electrical testing with a multimeter, the test leads should be rated _____.",opts:["Fused with 250mA fast-blow fuses","For the circuit's nominal voltage only","At least 1,000V for any electrical work","For the expected voltage AND the appropriate CAT category for the location"],ans:3,ref:"NFPA 70E 110.4(A)(1); IEC 61010",exp:"Test leads must be rated for both the voltage being measured AND the CAT category of the measurement environment. CAT-III leads for panelboard work; CAT-IV for service entrance measurements. Using underrated leads can result in lead failure, arcing, or meter explosion during transient overvoltage events. Always inspect leads for damage, exposed conductors, or cracked insulation before use."},
{id:489,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What does NEC 110.26(A) require regarding lighting in working spaces about electrical equipment?",opts:["Lighting is not required in electrical rooms","Adequate lighting must be provided for all working spaces about electrical equipment","Only battery-powered lighting is acceptable","Lighting must be on a separate circuit from the equipment"],ans:1,ref:"NEC 110.26(D)",exp:"NEC 110.26(D): Adequate lighting shall be provided for all working spaces about service equipment, switchboards, switchgear, panelboards, or motor control centers installed indoors. This requirement ensures that work can be performed safely with proper visibility. The lighting must illuminate the working space sufficiently, not just general area lighting. Emergency lighting may also be required per the building code."},
{id:490,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"When making an electrical repair, what is the FIRST step a qualified electrician should take?",opts:["Begin making the repair","Remove all tools from the work area","De-energize the circuit and verify zero voltage before touching any components","Put on rubber gloves and begin working"],ans:2,ref:"NFPA 70E 130.1; Cal/OSHA Title 8 §3314",exp:"The hierarchy of electrical safety: de-energize FIRST (preferred), then LOTO, then verify zero energy before any contact with conductors or equipment. NFPA 70E establishes that working on energized equipment requires justification — the default is to de-energize. De-energizing eliminates the electrical hazard entirely, while PPE only mitigates it. Verification with a meter after LOTO ensures the circuit is truly de-energized."},
{id:491,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"NEC 400.10 lists permitted uses for flexible cords and cables. Which of the following is NOT a permitted use?",opts:["Portable luminaire supply from a fixed outlet","Connecting appliances to receptacles","Wiring of fixtures requiring frequent repositioning","As a substitute for permanent building wiring run through walls, floors, or ceilings"],ans:3,ref:"NEC 400.12",exp:"400.12 lists prohibited uses for flexible cords: not permitted as a substitute for the fixed wiring of a structure; not permitted through holes in walls, structural ceilings, floors, or through doorways, windows, or similar openings; not attached to building surfaces; not concealed behind walls or above suspended ceilings. Extension cords are often misused as permanent wiring — a code violation and serious fire hazard."},
{id:492,mod:12,cat:"Safety & Maintenance",diff:"Medium",q:"What does the term 'qualified person' mean in the context of NEC and NFPA 70E?",opts:["Any licensed electrician","A person who has passed a state licensing exam","A person who has skills and knowledge related to the construction and operation of electrical equipment and has received safety training to recognize and avoid hazards","A person with at least 5 years of experience"],ans:2,ref:"NEC Article 100; NFPA 70E Article 100",exp:"NEC and NFPA 70E define a 'qualified person' as one who has demonstrated skills and knowledge related to the construction and operation of electrical equipment and installations and has received safety training to recognize and avoid the hazards involved. This is a functional definition — it's about training and demonstrated competency, not just a license. Unqualified persons cannot cross restricted approach boundaries."},
{id:493,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"When testing a 480V, 3-phase panel for arc flash incident energy, an engineer calculates 8 cal/cm². Which minimum arc-rated PPE would be required for work within the arc flash boundary?",opts:["Arc-rated PPE with a minimum rating of 8 cal/cm² or higher","Standard rubber gloves and a face shield — no arc rating needed for 480V","PPE is not required below 600V","Any FR clothing regardless of rating"],ans:0,ref:"NFPA 70E 130.5(G); Table 130.5(G)",exp:"NFPA 70E 130.5(G): The arc-rated PPE must have an arc rating (ATPV or EBT) equal to or greater than the calculated incident energy. If incident energy = 8 cal/cm², use PPE rated ≥ 8 cal/cm². Common practice: PPE Category 2 (min 8 cal/cm² rating) covers typical 480V switchboard work. NEVER wear synthetic non-FR materials (polyester, nylon) within the arc flash boundary — they melt and increase burn severity."},
{id:494,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 110.26(C)(2) requires two means of egress for large switchgear installations. What is the minimum current rating and width of equipment that triggers this requirement?",opts:["Over 800 amperes and over 1.2 m (4 ft) in length","All commercial switchgear regardless of size","Any equipment in a room accessible to the public","Over 1,200 amperes and over 1.8 m (6 ft) in length"],ans:3,ref:"NEC 110.26(C)(2)",exp:"110.26(C)(2)(a): Two entrances are required when the equipment bus rating is over 1,200 amperes AND the equipment is over 1.8 m (6 ft) long. One entrance at each end of the working space. The intent is to provide an escape route if an arc flash occurs — a worker cannot be trapped at the far end with only one exit. This applies to switchboards, switchgear, panelboards, and MCCs."},
{id:495,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"For equipment over 1,000V (NEC 110.34), the minimum working space depth under Condition 1 for systems 601-2,500V is 4 feet. If a worker must access equipment rated 13,800V (Condition 2), what is the minimum required working space depth?",opts:["10 feet","4 feet","6 feet","8 feet"],ans:3,ref:"NEC Table 110.34(A) Condition 2",exp:"NEC Table 110.34(A): For 13,800V (falls in the 9,001-25,000V range), Condition 2 = 2.5 m (8 ft) minimum working space. Condition 1 = 3.0 m (10 ft)? Let me correct: Table 110.34(A) for 9,001-25,000V: Cond 1=3.0m(10ft), Cond 2=2.5m(8ft), Cond 3=3.0m(10ft). So Condition 2 for 13,800V = 2.5 m (approximately 8 ft). Higher voltage equipment requires greater clearances due to increased arc flash and flashover hazards."},
{id:496,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"During a LOTO procedure, an electrician applies a personal lock to the disconnect. Another trade needs the equipment running. What is the proper action?",opts:["The supervisor can remove the lock with proper authorization","A duplicate key can be used to remove the lock","Remove the lock since another trade has priority","The equipment stays locked out until the electrician removes their own lock — the other trade must wait or find an alternative"],ans:3,ref:"California Title 8 CCR §3314; OSHA 29 CFR 1910.147",exp:"LOTO devices shall not be removed by anyone other than the employee who applied them. Another trade needing the equipment must coordinate with the authorized employee — who is the only person who knows the work status and can safely determine when removal is appropriate. If a group lockout is needed, each authorized employee applies their own personal lock (group lockout box procedure). Unauthorized lock removal is a serious safety violation."},
{id:497,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"What is the purpose of an 'assured equipment grounding conductor program' (AEGCP) as an alternative to GFCI on construction sites?",opts:["It replaces GFCI permanently in all applications","It provides a documented alternative for qualified workers in industrial establishments — involving visual inspection, continuity testing, and equipment testing at specific intervals","It applies to outdoor temporary power only","AEGCP only applies to three-phase equipment"],ans:1,ref:"NEC 590.6(A) Exception; OSHA 29 CFR 1926.404",exp:"The AEGCP (per NEC 590.6(A) Exception) requires: (1) designated competent person to implement and control the program; (2) all equipment visually inspected before each use; (3) tests of receptacles for polarity and EGC continuity at first use, after repair, and after indication of damage; (4) testing equipment before use, after repair/modification. The AEGCP provides equivalent protection to GFCI for qualified workers in industrial settings where GFCI may cause nuisance trips."},
{id:498,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 110.14(C) governs temperature ratings of terminals. A conductor rated 90°C is terminated in a connector rated 75°C. What is the maximum allowable ampacity for this conductor?",opts:["Use the 90°C column ampacity","Use the 75°C column ampacity — limited by the terminal rating","Use the 60°C column ampacity as the most conservative","No limitation — the conductor rating governs"],ans:1,ref:"NEC 110.14(C)(1)",exp:"110.14(C)(1): Where termination provisions are rated 75°C, conductors shall be rated no lower than 75°C, but the ampacity shall not exceed the values in the 75°C column. The TERMINAL (not the conductor) limits the ampacity because heat builds up at the termination. A 90°C conductor in a 75°C terminal is limited to the 75°C ampacity values. The conductor provides heat tolerance, but the terminal is the bottleneck."},
{id:499,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 230.95 requires ground fault protection for 277/480V services of 1,000A or more. Where the GFP system activates, what is the maximum setting allowed?",opts:["1,200 amperes","Any setting chosen by the engineer","1,000 amperes (equal to the service rating)","1,200 amperes ground fault with 1-second time delay"],ans:0,ref:"NEC 230.95(A)",exp:"230.95(A): The maximum setting of the GFPE sensor shall be 1,200 amperes and the maximum time delay shall be 1 second for ground fault currents equal to or greater than 3,000 amperes. The 1,200A maximum ensures the GFPE responds to ground faults that are too small to trip the main overcurrent protection. Ground fault currents between the GFPE pickup (up to 1,200A) and OCP rating can cause severe arcing fires if not detected."},
{id:500,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"During an arc flash study, the engineer finds that lowering the upstream overcurrent device's trip time reduces incident energy. This illustrates which principle of arc flash mitigation?",opts:["Increasing distance from the arc source","Reducing available fault current","Reducing the fault clearing time — faster clearing = lower incident energy","Using maintenance mode on the protective device"],ans:2,ref:"NFPA 70E 130.5; IEEE 1584",exp:"Incident energy = power × time. Reducing the fault clearing time (time the arc burns before the breaker trips) directly reduces incident energy. Methods: (1) lower instantaneous trip settings; (2) use zone-selective interlocking; (3) high-resistance grounding; (4) bus differential protection; (5) active arc flash detection relays. Maintenance mode on some breakers temporarily lowers trip time to reduce arc flash during maintenance — restoring normal settings when done."},
{id:501,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"What NEC section requires that panelboards be provided with physical means to prevent exceeding the number of overcurrent devices permitted?",opts:["NEC 408.7","NEC 408.4","NEC 408.54","NEC 240.24"],ans:2,ref:"NEC 408.54",exp:"NEC 408.54: Panelboards shall be provided with physical means to prevent the installation of more overcurrent devices than that number for which the panelboard was designed, rated, and listed. This prevents overloading panelboards by installing tandem breakers or exceeding listed circuit counts. Solid barriers or blocked spaces enforce this requirement. A 42-circuit panelboard may not have 44 breakers installed by using tandems beyond the listed allowance."},
{id:502,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"What does NEC 110.21(A)(2) require regarding the installation of reconditioned equipment?",opts:["Reconditioned equipment shall be marked 'RECONDITIONED' and comply with the original listing requirements","Any used equipment may be installed without additional marking","Only the AHJ can approve reconditioned equipment on a case-by-case basis","Reconditioned equipment is always prohibited"],ans:0,ref:"NEC 110.21(A)(2)",exp:"110.21(A)(2): Reconditioned equipment shall be marked with the name, trademark, or other descriptive marking by which the organization responsible for the reconditioned equipment can be identified, along with the date of reconditioning. Reconditioned equipment is equipment that has been restored to operating condition. The marking ensures traceability and accountability. Some articles (like 410.2) explicitly prohibit reconditioned luminaires — always check article-specific requirements."},
{id:503,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"What is required before an electrician performs maintenance on electrical equipment that has automatic restart capability?",opts:["Perform standard LOTO to prevent automatic restart — controls alone are not sufficient","Turn off the control switch — sufficient for equipment with automatic restart","No special precautions needed if the electrician is qualified","Install a warning sign only"],ans:0,ref:"California Title 8 CCR §3314; OSHA 1910.147",exp:"Equipment with automatic restart capability (timers, controls, PLCs) must be LOCKED OUT — not just turned off at the control switch. The energy isolation point (disconnect, circuit breaker) must be locked, not the control device. Control-off does not prevent automatic restart when the timer or sensor condition is met. LOTO at the energy source (not the control) prevents automatic restart from re-energizing the equipment during maintenance."},
{id:504,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 240.24(F) prohibits overcurrent devices from being located where they could be accessed by unqualified persons in a _____ condition.",opts:["Wet","Damp","Readily accessible","Outdoor"],ans:2,ref:"NEC 240.24(F) — actually 240.24(E)",exp:"NEC 240.24(E): Overcurrent devices shall not be located where they can be accidentally operated or tampered with by unqualified persons. In dwelling units, service equipment and panelboards must be accessible to the occupant but placed where children or unauthorized persons cannot easily access live parts. Commercial/industrial equipment in locked rooms limits access to qualified personnel only, complying with this requirement."},
{id:505,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"A qualified electrician is verifying that a 480V, 3-phase system has been de-energized after LOTO. What is the proper verification tool and method?",opts:["Touch the terminals with an insulated screwdriver to check for sparks","Use a voltmeter rated for the voltage and category (CAT III minimum for 480V panels), verify on a known live source first, then measure all phase-to-phase and phase-to-ground combinations","Use a non-contact voltage tester only — no meter leads near terminals","Standard multimeter on AC voltage setting — any meter is acceptable"],ans:1,ref:"NFPA 70E 120.5(7); Cal/OSHA Title 8",exp:"Verification of de-energization requires: (1) a voltage meter rated for the circuit voltage AND appropriate CAT category (CAT III minimum for 480V distribution); (2) first test on a KNOWN live source to confirm meter works; (3) test all phase combinations (A-B, B-C, A-C, A-N, B-N, C-N) to verify zero voltage; (4) if any voltage is detected, stop and do not proceed. Non-contact testers alone are insufficient for verification because they can have false negatives near de-energized conductors."},
{id:506,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 110.15 requires that single-phase, 3-wire circuits have the high-leg conductor identified with what color?",opts:["Red","Blue","Orange","White with orange tracer"],ans:2,ref:"NEC 110.15",exp:"110.15: For a 4-wire delta system (120/240V, where one phase is 208V to ground), the conductor with the higher voltage to ground (the 'high leg' or 'wild leg' at approximately 208V phase to neutral) shall be identified by an orange outer finish. This warning prevents a 120V device from being accidentally connected to the high-leg, which would apply 208V to a 120V rated device. The high-leg is typically the B-phase in a 120/240V delta service."},
{id:507,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"Under NFPA 70E, what is the minimum safe approach distance (restricted approach boundary) for a qualified person working on exposed energized conductors at 120V?",opts:["No restricted boundary exists for 120V","Restricted approach = avoid contact — the boundary is at the conductor surface for 50-150V","The restricted boundary is 1 foot for 120V","12 inches for residential, 18 inches for commercial"],ans:1,ref:"NFPA 70E Table 130.4(D)(a)",exp:"NFPA 70E Table 130.4(D)(a): For 50-150V (which includes 120V), the restricted approach boundary is 'Avoid contact' — meaning the restricted approach boundary is at the surface of the exposed conductor. Qualified workers must use PPE (insulated tools, rubber gloves) to avoid incidental contact but can work in close proximity with appropriate protection. The limited approach boundary for 50-150V is 3 ft 6 in. (1.07m)."},
{id:508,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC 90.3 explains the structure of the NEC. Which chapters apply to special occupancies, special equipment, and special conditions?",opts:["Chapters 1 through 4 only","Chapters 5, 6, and 7 — these supplement or modify Chapters 1 through 4","Chapter 9 only for calculations","All chapters apply equally"],ans:1,ref:"NEC 90.3",exp:"NEC 90.3: Chapters 1-4 apply generally. Chapter 5 covers special occupancies, Chapter 6 covers special equipment, and Chapter 7 covers special conditions. Chapters 5, 6, and 7 can supplement or modify requirements in Chapters 1-4. Chapter 8 covers communications systems, which are independent except where specific sections of Chapters 1-7 are referenced. Chapter 9 contains tables. Annexes A-J provide informational material."},
{id:509,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"After completing a maintenance job that required LOTO, the authorized employee must follow which steps BEFORE removing lockout devices?",opts:["Just remove the locks and restore power","Verify all tools and materials are removed, ensure all employees are safely clear of the equipment, notify affected employees, then remove LOTO devices and restore energy","Remove locks, then check that employees are clear","Call the supervisor, then remove locks"],ans:1,ref:"California Title 8 CCR §3314(b)(8); OSHA 1910.147(e)(3)",exp:"Pre-removal LOTO steps: (1) Ensure all non-essential items (tools, materials, test equipment) have been removed; (2) Ensure all employees are safely positioned away from the equipment; (3) Notify all affected employees that LOTO is being removed and power will be restored; (4) Each authorized employee removes only their own lock; (5) Restore energy following the established startup procedure. Skipping the 'clear of equipment' check is a leading cause of accidents during LOTO restoration."},
{id:510,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"A multi-employer worksite has both electrical and HVAC contractors working simultaneously. The HVAC contractor must work in an area near a 480V panelboard that the electrician has locked out. What is required?",opts:["HVAC worker may proceed — the lock covers all workers automatically","A group lockout procedure is required — each contractor must apply their own lock to the energy isolation point or a group lockout box","Only the HVAC supervisor must be notified — no additional LOTO required","The HVAC contractor must get permission from the electrician to proceed"],ans:1,ref:"California Title 8 CCR §3314(b)(7); OSHA 1910.147(f)(3)",exp:"Multi-employer LOTO: When employees from different employers work on the same equipment, each must have individual protection. A group lockout hasp/box allows multiple workers to each apply their personal lock. The equipment cannot be re-energized until ALL locks are removed. One employer's lock does not protect other employers' workers. This is a critical multi-employer site requirement often overlooked in the field."},
{id:511,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC Section 110.26(C)(1) requires a dedicated space in front of electrical equipment. This space must be kept clear for the width and depth of the required working space. What specifically must this space be free of?",opts:["Only combustible materials","Any storage — whether permanent or temporary","Only flammable liquids or gases","Only foreign equipment not part of the electrical installation"],ans:1,ref:"NEC 110.26(C)(1)",exp:"110.26(C)(1): The working space required by this section shall not be used for storage. When normally enclosed live parts are exposed for inspection or servicing, the working space, if in a passageway or general open space, shall be suitably guarded. Storage in front of electrical panels is one of the most common electrical violations found during inspections — even temporary storage is prohibited. This ensures the working space is ALWAYS accessible in an emergency."},
{id:512,mod:12,cat:"Safety & Maintenance",diff:"Hard",q:"NEC Section 90.7 provides that if there is an apparent conflict between the NEC and another rule or document, the NEC governs for electrical work. However, what standard governs the safety of workers performing electrical maintenance work?",opts:["The NEC governs all aspects including worker safety","NFPA 70E (Standard for Electrical Safety in the Workplace) governs worker safety practices — the NEC governs installation requirements","Cal/OSHA Title 8 alone governs all electrical safety","OSHA 1910 Subpart S is the only applicable standard"],ans:1,ref:"NEC 90.1(B) Informational Note; NFPA 70E",exp:"NEC 90.1(B) Informational Note No. 2 specifically states that NFPA 70E covers electrical safety requirements for employee workplaces. The NEC covers installation; NFPA 70E covers safe work practices. In California, Cal/OSHA Title 8 adopts and enforces both NFPA 70E principles and additional California-specific requirements. A fully compliant installation (NEC) can still be unsafe to maintain if NFPA 70E/Cal/OSHA worker safety practices are not followed."},
];

